WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[79213] = { title = "The Anachronism", description = "Insert the batteries into the cylindrical holes on the console.\n\nThen, titans willing, we will see what it holds.", objectives = "Activate the Excavated Console and use the device to defeat the Sargassum Guardian in Golgrin's Reach.", progress = "To obtain the power necessary, find an elemental of sufficient size to charge the artifact.\n\nIf I am right, the titan artifact will do the rest.", completion = "Curious. It is emitting a signal I have seen before.\n\nI have an idea where this may lead us." }
WordHunterWoW_QuestEN[79216] = { title = "Web of Manipulation", description = "This town has been under siege, overrun by spiders! Even when we clear them out, they always return.\n\nSomething is behind these attacks!\n\nA small ledge northeast of Light's Bloom harbors these spiders. Scout out the ledge. Find out what is driving these spiders to attack us, and put an end to it!", objectives = "Explore the nearby ledge and deal with any threats within.", progress = "Have you solved our spider problem?", completion = "Excellent work, <name>.  Now let us see if that puts an end to this eight-legged invasion!" }
WordHunterWoW_QuestEN[79217] = { title = "Back to Base", description = "Getting this factory up and running will be a challenge, but I think we'll figure out something. Let's head back to Gundargaz and consult with a friend of ours.\n\nHis mind will be a big help to us here.", objectives = "Meet Brinthe back in Gundargaz.", completion = "Are you ready to put our heads together and come up with a plan?" }
WordHunterWoW_QuestEN[79218] = { title = "Renowned with the Hallowfall Arathi", description = "Your labors on behalf of our people have not gone unnoticed. Nor will they go unrewarded.\n\nFind me in Mereldar.", objectives = "Speak with Auralia Steelstrike in Mereldar.", completion = "Supplies run thin, but in your hands these goods will benefit all Algari. May the Sacred Flame light your path." }
WordHunterWoW_QuestEN[79219] = { title = "Renowned with the Council of Dornogal", description = "The Council continues to be in your debt, friend.\n\nIf you visit me in Dornogal, I will give you supplies to reduce that debt.", objectives = "Speak with Auditor Balwurz in Dornogal.", completion = "Dispensing rewards. Thank you, champion. This should be sufficient remuneration for your efforts." }
WordHunterWoW_QuestEN[79220] = { title = "Renowned with the Assembly of the Deeps", description = "Good work deserves good reward, yes?\n\nAssembly is grateful. Waxmonger Squick is grateful. Show gratefulness with many supplies.\n\nCome see Waxmonger Squick in Gundargaz.", objectives = "Speak with Waxmonger Squick in Gundargaz.", completion = "For you! Take!" }
WordHunterWoW_QuestEN[79221] = { title = "The Unusual Bug", description = "Nerubians in Rak-Ush may find this strange little spider of interest.", objectives = "Deliver this Unusual Bug to Widow Arak'nai in Rak-Ush.\n\nProvided item:", completion = "Oh, I was wondering where those had gone, thank you for returning it!" }
WordHunterWoW_QuestEN[79222] = { title = "Shadow-Hardened Mainspring", description = "<Maybe it was the effects of prolonged darkness or tinkering by Ezgi Irongear, but the strength of this spring would be of interest to Speaker Kuldas in Gundargaz.>", objectives = "Deliver this item to Kuldas in Gundargaz.\n\nProvided item:", completion = "Most excellent find, this will require significant examination!" }
WordHunterWoW_QuestEN[79223] = { title = "Finally, An Archivist!", description = "So you've got your bearings now? You've felt the dirt? You've smelled the history?\n\nWhy not celebrate this glorious moment of above average success with... a cap!\n\nThat's right! Take this token to our beloved provisioner, Aristta. She'll be happy to provide you with one of our all-purpose caps to signify your elevation to Archivist from naive passerby.", objectives = "Purchase an Archivist's Buckled Cap from Provisioner Aristta.", progress = "The cap suits you quite well!", completion = "Regardless of any assessment of your current aptitude, at least one could say that you look the part!\n\nNow then, your talents have been requested again by my colleagues. Better not tarry!" }
WordHunterWoW_QuestEN[79224] = { title = "Gathering Intel", description = "The Widow Arak'nai sent word via one of those \"weave-rats\" of hers. She has a lead that may be relevant to our cause, and has invited us to investigate. All the training in the world is useless without knowledge of our enemy.\n\nMy own reconnaissance efforts in Azj-Kahet were met with... mixed results, as you may recall. I admit I am not keen on venturing down there again so soon. Fortunately, reinforcements have arrived with a capable spymaster.\n\nUnfortunately, she is... well. You'll see.", objectives = "Speak with Widow Arak'nai at the Weaver's Lair in Azj-Kahet.", completion = "As I was telling your surly little spymaster, I expect this to be a mutually beneficial undertaking.\n\nWe shall both walk out of it with the information we need." }
WordHunterWoW_QuestEN[79225] = { title = "The Lost Flame", description = "<A tinderbox of a Hallowfall Expedition member, its return would help honor the memory of those who bravely gave their lives.>\n\nAn expedition scout might possess knowledge about this item.>", objectives = "Deliver the Expedition Tinderbox to Keyrra Flamestonge at the Shadowgrove Vineyards.\n\nProvided item:", completion = "On the Day of Shadows, Augustine panicked and broke ranks.\n\nThere were rumors he had left Hallowfall and found a way to the surface. I see he failed." }
WordHunterWoW_QuestEN[79226] = { title = "The Big Dig: Traitor's Rest", description = "Don your cap, put on a pair of sturdy gloves, and grab a snack because Traitor's Rest is ready for Archivists everywhere to sink their history-craving teeth into!", objectives = "Aid Eadweard Dalyngrigge and the Azerothian Archivists at The Big Dig in Traitor's Rest.", progress = "Not every day you unearth ancient dragon mysteries... or even a dragon themselves!", completion = "<Eadweard rustles through his unending robe pockets.>\n\nHere you are, Archivist <name>! Take this to Provisioner Aristta for your compensation.\n\nMay I suggest a new set of clothes, as your current set is... quite soiled." }
WordHunterWoW_QuestEN[79227] = { title = "A Spider's-Eye View", description = "I have eyes in every crevice of the city save for one that has... eluded me.\n\nThe Transformatory is the grounds of Ansurek's most precocious minions and treasured pets. It is where the Ascension process was developed. I've only gotten my claws on it recently, thanks to dear Y'tekhi. Much of it remains uncomfortably shrouded.\n\nA more legs-on approach is in order. Place shadecasters to collect intel from my scouts, then meet Y'tekhi and your own spymaster Voss in a discreet corner of the district.", objectives = "Place shadecasters to rendezvous with the Weaver's scouts in the Umbral Bazaar, the Eastern Span, and the Twitching Gorge.", completion = "I don't like the sound of those reports. Looks like whatever they're cooking is coming to a head, right in time for us to walk in.\n\nDon't worry. I'll let you know if we get in too deep." }
WordHunterWoW_QuestEN[79230] = { title = "Creeping Through Corridors", description = "I've identified three sites of interest to investigate. \n\nA stockpile on the east side of the complex, a warehouse in the center, and lastly, that big storehouse with royal Sureki flags outside it. We'll rendezvous there.\n\nThere's less chance of discovery if we move separately through the area. You may be hidden from most nerubians, but the Ascended will sniff you out. Chuck some of these anger pheromones at them if you get heat, it'll distract them.\n\nStay sharp, stay quiet.", objectives = "Investigate the western stockpile, central warehouse, and royal stores of the Transformatory, using anger pheromones to distract guards and avoid detection.", progress = "Don't let your guard down. Not here.", completion = "We came down here to figure out what these nerubians were up to. I don't think I like the answer." }
WordHunterWoW_QuestEN[79231] = { title = "Back to Headquarters! Again!", description = "You've done truly incredible work! The proof is obvious: you are, in fact, a proper Azerothian Archivist.\n\nMeet us all back at our headquarters in Thaldraszus. Eadweard would like codify all your helpful labors and achievements for our group.", objectives = "Meet with Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", completion = "Excellent work, <name>! Most excellent work!\n\nI can see that I was right in bringing you aboard. You have a true archivist's spirit!" }
WordHunterWoW_QuestEN[79232] = { title = "Those Who Fell", description = "Since the Day of Shadows these lands have been a dangerous place. \n\nThe kobyss are emboldened, the nerubians probe our lands, creatures of pure shadow have begun to manifest themselves.\n\nThe memory of those who have fallen is etched in our everyday lives. We must locate their remains to bring closure. \n\nSearch for the Tinderboxes of these missing expedition members and return them to me.", objectives = "Locate the remains of Oskaer Daleclash, Dalian Ironlink, and Idona Seerstone, and recover their tinderboxes.", progress = "Have you located the tinderboxes?", completion = "These tinderboxes are but a small symbol of the immense loss we suffered on the Day of Shadows. We will recover the bodies you have located and begin to heal the memories of our loved ones." }
WordHunterWoW_QuestEN[79233] = { title = "Lab Access", description = "As much as I adore skulking in the shadows, the juiciest intel is going to be inside the laboratory of the Grand Splicer.\n\nOf course you'll need the proper pheromones once you're in, but we can take care of that with a little biological forgery.\n\nThe nerubian loyalists here are surely on the invite list. Six of their secretions should be enough to disguise the three of us.", objectives = "Collect 6 Loyalist Secretions from nerubian loyalists in the Transformatory area.", progress = "If you saw me? No you didn't.", completion = "Finally! I was waiting for when we'd stumble upon the real intrigue." }
WordHunterWoW_QuestEN[79234] = { title = "A Small Bag of Seeds", description = "<This small bag of seeds seems forgotten, perhaps Aliya Hillhelm could make use of them.>", objectives = "Deliver this small bag of seeds to Aliya Hillhelm at the Hillhelm Stead.\n\nProvided item:", completion = "Why thank you!" }
WordHunterWoW_QuestEN[79237] = { title = "Making of a Monster", description = "We've got a new objective: Figure out what Ansurek's plans are for this... thing.\n\nWe'll find our answers inside the laboratory of the Grand Splicer. I'd bet my blades on it.\n\nI scouted a maintenance hatch on the roof that you can grapple up to. Y'tekhi brewed up some weird concoction that they claim will get us the proper clearance once inside. Yuck.\n\nMeet you in there.", objectives = "Access the Laboratory of the Grand Splicer via roof hatch, then investigate clues as to the purpose of the First Ascended.", progress = "I don't like this. There's something we're still missing here.", completion = "That... wasn't what I expected to find out. \n\n<Lilian clears her throat.>\n\nFamily drama aside, whatever the old queen used to be, she'll be a big problem for us when she inevitably shows up on the battlefield." }
WordHunterWoW_QuestEN[79239] = { title = "The Queen's Chains", description = "Ansurek... that worm, that witless, gutless little--\n\n<Y'tekhi growls under their breath, struggling to maintain their composure.>\n\nIf this is what's become of Neferess, we must free her. She is still our queen. My mistress will know what to do.\n\nWhen the Weaver discovers what they've all done, there will not be a crevice deep enough to escape her wrath.", objectives = "Destroy Neferess's shackles.", completion = "Remember when I said I'd let you know when we're in over our heads? This is it." }
WordHunterWoW_QuestEN[79240] = { title = "Rogue Agent", description = "We lost Y'tekhi.\n\nWe can worry about the how of it later. Right now, we need to worry about taking them down before they make things worse.\n\n<Lilian snorts.>\n\nI guess we came down here to find out what Xal'atath had up her sleeve. ...I wish we'd minded our own business.", objectives = "Subdue Y'tekhi.", progress = "Hard to think of how this could have gone any worse.", completion = "We're out of the public eye, for a moment.\n\nGetting Y'tekhi back to the Weaver is my priority. Yours is dealing with the weapons." }
WordHunterWoW_QuestEN[79241] = { title = "Go Loud", description = "So much for keeping this operation quiet. At least now that our cover's blown, we can really mess things up.\n\nThey're hauling weapons across the south bridge. If we turn those weapons against them, they'll have to resupply their whole army. That'll buy us time, at least.\n\nI've identified six weak spots across the convoy. Rig up bombs to all six, then get out of there and watch the fireworks.", objectives = "Plant 6 Commandeered Nerubian Charges at specified points across the convoy, then remotely detonate them.", progress = "They know we're here. May as well make the most of it.", completion = "Not only is the convoy in shambles, but we were able to slip away in the chaos. If there's one thing you're good at, it's making noise.\n\nStaying quiet? Eh, we can work on it." }
WordHunterWoW_QuestEN[79243] = { title = "Manufactured Mutiny", description = "We don't have the firepower to dismantle their whole manufacturing operation, but what we do have is two leftover vials of anger pheromones. Let's make them count.\n\nThere's a siege marshal and a quartermaster overseeing the preparations and giving everyone orders. Logistics types, but they still pack a punch. That's where those pheromones come in.\n\nHit them with a vial, and their own armies will turn against them. Take out both, and we watch the operation crumble.", objectives = "Slay Siege Marshal Tekhzok and Royal Quartermaster Ze'erik.", progress = "Those aggression pheromones came in handy... let's make sure not to waste them.", completion = "It's only a delay, not a hard stop, but it's still a big one. It'll give the folks up top more time to prepare." }
WordHunterWoW_QuestEN[79244] = { title = "News From Below", description = "I could hear the explosions from here. That'll buy us some time. Maybe I'd even be relieved, if this had gone less poorly.\n\nY'tekhi is secured in the back, where they can't overhear anything. Whatever Xal'atath did... it hasn't worn off yet. The Weaver has people looking into it, but the outlook is grim.\n\nAlleria is going to want a status report. Good luck.", objectives = "Inform Widow Arak'nai about what was found in the Transformatory. Then, return to Alleria at Dornogal on the Isle of Dorn.", progress = "Nothing to do but keep going.", completion = "At the end of the day, we delayed their advance and got some good, actionable intel that everyone up here can work towards.\n\nWas it worth it? Time will tell." }
