WordHunterWoW_QuestEN[79254] = { title = "Everspout", description = "", objectives = "" }
WordHunterWoW_QuestEN[79255] = { title = "Crunchy Competition [DNT]", description = "The spiders steal our prey! They feast on the grubs and leave none for us.\n\nNo, no grubs for the kobolds where spiders lay in wait.\n\nKill them so we can have the Chittering Den to ourselves.", objectives = "Kill Queen Rickiticka in the Chittering Den.\nKill 10 spiders in the Chittering Den." }
WordHunterWoW_QuestEN[79256] = { title = "A Hint of Fear", description = "My father thinks that while he and Dagran were dealing with the skardyn tae the south, he caught a sensation o' his old hammer, Fearbreaker.\n\nHe said it slipped out o' his fingers when Dalaran crashed, and it's been bothering him mightily. That hammer belongs tae the Bronzebeard clan, and has for generations. But he hasn't been himself lately, either.\n\nI'm willing tae have a look, so he doesn't worry that he might've missed it. Meet me down at Camp Murroch, and we'll have a quick look around.", objectives = "Meet Moira Thaurissan outside Camp Murroch.", completion = "Well...\n\nI wasn't expecting to actually see Fearbreaker here.\n\nIt's really here, but it ain't exactly within easy reach." }
WordHunterWoW_QuestEN[79257] = { title = "Grotto Grievances", description = "", objectives = "" }
WordHunterWoW_QuestEN[79258] = { title = "Mineral Water Woes", description = "When that magic hammer fell into the Deeps, I knew it could be a formidable weapon against the skardyn menace. Your friend has told me that it's 'particular' about its wielder.\n\nFortunately, I am a hero!\n\nAnd as a hero, I know how to get close to it. We need to have a good mix of pollen and water plastered onto us. That way, the beast standing over it will think we're just like it.\n\nThat mineral water has to be the exact right temperature to mix with the lashroom dust and blend in.", objectives = "Acquire the proper-temperature mineral water from the Living Grotto springs.", completion = "That was a right pain. But we got the water Berrund asked for.\n\nIt's time we get a move on. I don't want my father's hammer to just languish there in the mud. That doesn't sit right with me, not at all." }
WordHunterWoW_QuestEN[79259] = { title = "Put On a Good Face", description = "Berrund here says that the massive beast standing over Fearbreaker is very particular about what kinds of creatures it allows near it.\n\nIf we blend in, he says, we can get close enough tae nab the hammer. But tae blend in, he says we have tae get covered by the dust an' pollen in the grotto. \n\nThose Lashrooms look like they're a good place to start. \n\nIt all seems suspicious tae me, but fer now, we'll play along until I can recover Fearbreaker and bring it back to my father.", objectives = "Collect Lashroom Dust from Lashrooms in the Living Grotto.", progress = "Have you gathered up that dust? It's the only way you're going to get near that hammer, especially with that creature wandering around.", completion = "<Berrund the Gleaming appears not to have a speck of pollen on himself.>\n\nYou got yourself good and covered in that lashroom dust, all right.\n\nI'm a bit surprised you're not itching and sneezing, like your friend here." }
WordHunterWoW_QuestEN[79260] = { title = "Epicenter", description = "There is the creature standing between us and that magic hammer. It certainly made an impact when it landed here in the Ringing Deeps, didn't it? Look at the size of that crater!\n\nWith the pollen and water splashed on you like this, you should be able to approach that beast and, theoretically, not be harmed. You'll blend right in with it!\n\nBut if it does turn aggressive, don't worry, I'll be right behind you.\n\nWe'll get that hammer out of here safely!", objectives = "Approach the Verdant Hulk.", completion = "Why that amber-sucking, slime-spined, travesty of an earthen! I've met troggs with more honor!\n\nHe took Fearbreaker! He took my family's hammer and left us to die to that creature!\n\nThis cannot stand. I will not allow such disrespect to you... or to me." }
WordHunterWoW_QuestEN[79261] = { title = "Boiling Mad", description = "That gravel-brained ingrate! He took Fearbreaker and ran off to the north!\n\nIt's not that I want that hammer for myself. I don't. But it belongs to the Bronzebeard clan. It should be in the hands of someone who respects its power!\n\nWe need to track him down before he hurts himself or someone else with that hammer!", objectives = "Track Berrund and Fearbreaker through the Ringing Deeps.", completion = "These earthen have had a bad time of it.\n\nBerrund's already run headlong into there, but if he was hoping to clean up the ills of the place, he's clearly in over his rocky head.\n\n<Moira points to the nearby rocky contusion>\n\nLook, he can barely keep hold o' Fearbreaker! What if he drops it and is killed? We need tae find him." }
WordHunterWoW_QuestEN[79262] = { title = "Clean Up House", description = "It looks like the destruction around the Coreway rattled loose more than just a few stones down here. It's stirred up all sorts o' dark things.\n\nIf this was a thriving mining operation, it ain't anymore. \n\nWe need to help the earthen get it under control again, and that means thinning out these beasts.", objectives = "Slay agitated creatures in the Rumbling Wastes.", progress = "I want to get Fearbreaker back, but we need to clear out some of these agitated beasts first.", completion = "That's a mite better. At least there won't be so many of those creatures running amok around this area.\n\nNow we've got other problems.\n\nWe've got skardyn." }
WordHunterWoW_QuestEN[79263] = { title = "Fault Lines", description = "Berrund took Fearbreaker for himself. I suppose he thought he could save these people. Be the hero.\n\nBut ye can't go about doing the wrong thing for the right reasons.  I know from experience. If a rock is hollow tae begin with, it never can be solid again, no matter how hard ye try. \n\nHe's likely tae need saving himself now. Let's find him in this blasted place.", objectives = "Find Berrund the Gleaming within the Rumbling Wastes.", progress = "You found me?", completion = "<Berrund the Gleaming's skin is chipped and damaged. His eyes can barely focus. He is near to death.>\n\nEvery time... I tried to use the hammer... it just got away from me. I could have saved people. I don't... I don't..." }
WordHunterWoW_QuestEN[79264] = { title = "These Strong Hands", description = "<Berrund the Gleaming coughs dustily.>\n\nI knew I couldn't take the skardyn without some help. I thought, if I just had that magic hammer, then nothing would stop me. I had to have it, you see, or else, maybe I wasn't who I was made to be.\n\nBut it kept slipping out of my fingers. Like it didn't want anything to do with me. It fell out of my hands at the worst moment and now... <He coughs again.>\n\nIt's clearly not mine. It never was. I'm... I'm... sorry.", objectives = "Witness Moira Thaurissan.", completion = "I thought this day would never come because my Da' would never have given me Fearbreaker. He probably would have wanted it to happen a different way.\n\nBut I have it now, and I'll make sure it gets back to him safe.\n\nFirst though, we have unfinished business here." }
WordHunterWoW_QuestEN[79265] = { title = "Fearbreaker", description = "The skardyn have taken over the operations here in the Rumbling Wastes. That's why Berrund thought he needed Fearbreaker.\n\nWe're going to finish that job before I take the hammer back to Magni.\n\nWhat kind of a queen would I be if I wasn't willing tae put myself in danger for the good of others? Let's get in there and save as many as we can.", objectives = "Slay skardyn and save earthen in the Rumbling Wastes with Moira Thaurissan.", completion = "We got there in a roundabout way, but we still made a difference in the lives of these earthen.\n\nBerrund, hopefully, has learned a lesson in real heroism. But I suppose we'll see in time.\n\nNow, let's get this over with." }
WordHunterWoW_QuestEN[79266] = { title = "The Bronzebeard Legacy", description = "Well, we did what we set out tae do... and more. We found Fearbreaker and did some good with it.\n\nNow it's time tae bring it back tae Magni.\n\nLet's hope Berrund learned a lesson here, but I suspect he'll manage tae get himself in trouble again soon. Hopefully, it'll be fer the right reasons an' with the right support.", objectives = "Meet Moira Thaurissan in Gundargaz.", completion = "It's funny. I can see why me Da' was so fond o' this hammer. And what it meant when he trusted others tae hold onto it.\n\nFearbreaker's got a mind of its own, in ways. It wants what it wants. \n\nI suppose I relate." }
WordHunterWoW_QuestEN[79267] = { title = "Wax On, Pot Off", description = "If candles are important to kobold society, I have an idea that might disrupt their production... or at least make sure there's an unpleasant surprise waiting for our enemy.\n\nTake that cinderbrew. Drop some in those large vats of wax the kobolds are prepping at the top of that hill. It's a powerful explosive. It burns aggressively, so try not to drop any.\n\nIt should certainly make any candles made with that wax quite feisty, once they're lit.", objectives = "Sabotage the pots of wax in the Warrens.", progress = "Try not to breathe too many of the fumes.", completion = "Hopefully, that takes them down a peg or two.\n\nA leader's power waxes and wanes. With all this destruction, the Candle King's power is waning." }
WordHunterWoW_QuestEN[79268] = { title = "Gundrak Fast Track", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[79269] = { title = "Gundrak Fast Track - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[79270] = { title = "Gundrak Fast Track - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
