WordHunterWoW_QuestEN[79274] = { title = "Coldarra Climb - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[79276] = { title = "The Squishier, the Better [DNT]", description = "Spiders stole my key. I can't get to my treasure without my key!", objectives = "Collect Nebb's Key and use it to retrieve Nebb's Treasure." }
WordHunterWoW_QuestEN[79282] = { title = "The Grand Debut", description = "The Proscenium is looking amazing! Are you ready to get on stage?\n\nGive us a hand as part of the crew, and we'll give you a chance to act.\n\nWill you accept this directive?", objectives = "Complete one Theater Troupe event in The Proscenium.", progress = "I haven't seen you on stage yet, <name>. You won't win any fans by standing around!", completion = "What a good show! I think your work on the Proscenium has made this an excellent stage.\n\nCome by again sometime. We always need hands for the cast and crew!" }
WordHunterWoW_QuestEN[79295] = { title = "Hose 'Em Down - Activate", description = "", objectives = "" }
WordHunterWoW_QuestEN[79297] = { title = "Nightwatch", description = "Xal'atath is using the Order of Night to serve her whims.\n\nI overheard some of the Arathi complaining about a new wave of propaganda that has been put up around Mereldar. Find what you can and deliver it to General Steelstrike. I'll be there as soon as I can.\n\nWe need to convince her of the severity of this threat.", objectives = "Collect 8 Order of Night Propaganda.", progress = "Anything I can help you with, <name>?", completion = "<General Steelstrike reads through the propaganda you brought her.>\n\nI need to know more about this Xal'atath." }
WordHunterWoW_QuestEN[79300] = { title = "The Notebook", description = "{name}, I need your help. My whole future is on the line! I came to Lightspark to be an airship captain, and I've put in a ton of work to excel here. But my notebook is missing, with my final report!\n\nI'm top in the class, but if I don't turn it in soon, I won't be our next airship captain. Please help me find it.\n\nI thought I left it out by the canyon where we review each other's skiff piloting, but it wasn't there when I checked. Can you help me look for it?", objectives = "Help Sophietta look for her notebook.", completion = "Edwyn took it? Of course. \n\nHe desperately wants to be selected as captain, but he knows I'm ahead in the rankings. His only chance is if I can't turn in my report. We have to get it back!" }
WordHunterWoW_QuestEN[79301] = { title = "Height Club", description = "I'm so tired of Edwyn. From the day we all arrived, he's been telling everyone he'll be selected as captain.\n\nHe's a great flyer--very talented, and he knows his stuff. But his ego gets in the way of treating people as he should. And he knows my grades and flight review scores are higher.\n\nBut if I can't turn in my report, he'll be the next captain. Take it back from him!", objectives = "Confront Edwyn about the notebook.", progress = "Did you get it back? I'd love to see the look on Edwyn's face...", completion = "He threw it into the valley and the WIND TOOK IT?!" }
WordHunterWoW_QuestEN[79302] = { title = "Gone with the Wind", description = "I can't believe Edwyn threw my report out into the wind. \n\nCan you please track down what papers you can find? I'll look for any around the school grounds, you check the valley. \n\nThis report is already late... But I had some really good insights around airship capabilities. When Headmaster Fynch sees them, maybe he'll still allow me to turn it in.\n\nBring me whatever pages you find!", objectives = "Recover 10 pages from Sophietta's report.", progress = "I hope you found all the pages, <name>!", completion = "I really wish this looked better. I'm honestly ashamed to turn it in, if Headmaster Fynch will even let me. \n\nBut we have to try--the ideas are what matters, and they're still true!" }
WordHunterWoW_QuestEN[79303] = { title = "A Principled Principal", description = "Great work gathering these up. I found a few blowing around up here, so I think we've got all the pages. Let's get this to Headmaster Fynch! He's probably in the classroom.\n\nI sure hope he accepts it. He says he doesn't accept late work, but there were a lot of extenuating circumstances at play here. And if he doesn't, I'll be reporting to Edwyn as my captain. I'm not sure I could do that, after what's happened.", objectives = "Get Sophietta's report to Headmaster Fynch.", completion = "Sophietta has been a phenomenal student. Honestly, I am too close to the situation to make that decision without bias. But it was too nuanced to reject without consideration.\n\nAs an outsider, I know your decision wasn't colored by months spent with these students, so I could trust your judgment. I appreciate your help in resolving the situation, <name>." }
WordHunterWoW_QuestEN[79304] = { title = "Care Package", description = "My cousin Sophietta and I came to Hallowfall together as stalwarts. Since arriving, we both lived here in Dunelle's Kindness for years. But she left last year to follow her dream of being one of our airship captains, or at least joining an airship crew.\n\nShe's a strong person, but I don't know how she's doing. Especially without Innkeeper Valrin's sweetrolls! She can't get them at Lightspark, the Sky Academy. Will you take these to her, and make sure she's doing alright?", objectives = "Take the care package to Sophietta Lynflayme at Lightspark Sky Academy.", progress = "What's this? Are these for me?", completion = "That was very kind of Barahl to send these. You can tell him I'm doing well, but first, do you think you could help me with something?" }
WordHunterWoW_QuestEN[79309] = { title = "Status Report", description = "Airships give the Arathi Army command of the skies. But roads are the lifeblood of empires. My scouts protect and light the passageways of Hallowfall for our citizens.\n\nOne such patrol has been late to report their walk of the eastern road. Seek my missing scouts by the sight of smoke or flame. Arathi soldiers know better than to linger in the dark.", objectives = "Locate the missing Arathi Army scouting party.", completion = "<Scout Wayshelm does not meet your gaze.>" }
WordHunterWoW_QuestEN[79310] = { title = "Seek the Lost", description = "Guard our ways, repel the dark. Civilize this twisted land. All in the name of our empire. This is the mission of the Arathi Army. A mission I can heed no longer.\n\nI am afraid.\n\nI won't go back into the dark. Not after what I've seen. If Maevest or any of my other companions survived, they must crave the mercy of a swift death. And I left them to that terror.\n\nTell Captain Trueflame her scouts died in darkness, one and all.", objectives = "Look for a member of Wayshelm's party.", progress = "<Scout Wayshelm gazes into the flames of his campfire.>", completion = "<Scout Wayshelm clutches the compass tight and finally raises his gaze to regard you.>" }
WordHunterWoW_QuestEN[79311] = { title = "Stem the Flow", description = "The roads were meant to be lit. But the path was overgrown, the lanterns dark. Swarming, frothing, and reeking with rot. It all happened so fast. By the time we realized the danger, the beasts were upon us. The largest of them was huge and black as night.\n\nIt is our duty to slay monsters and push back the darkness. But the thought of going back fills with me fear. \n\nI've lost my nerve. But you, outsider, can still make this right.", objectives = "Slay 12 Bloatrot Stingers or Fungal Infestors.", progress = "<Scout Maevest's compass gleams in the firelight. Wayshelm has bound it with twine and now wears it around his neck.>", completion = "You're alive. Praise the Sacred Flame." }
WordHunterWoW_QuestEN[79312] = { title = "Mow the Masses", description = "Maevest and I broke away from the others and fled, their screams left in our wake. Foul muck smothered our lanterns and we stumbled in the dark through knee-high waters. I heard a splash like she had tripped and fallen in, but I couldn't bring myself to look back.\n\nOnly later did I find the tiny bite marks on my ankles. Be warned, there's something in the water.\n\nI took notice of fronds growing from the pools. Swarming insects feast on their sickly nectar. Destroy those plants and starve the beasts.", objectives = "Cut down 8 Foulnectar Fronds.", completion = "<Scout Wayshelm gives you an approving nod and finds a grim smile.>\n\nIn the dark, even the plants want us dead." }
WordHunterWoW_QuestEN[79313] = { title = "What Grows in the Dark", description = "We are told never to walk in the darkness. To carry light wherever we go. The thought of returning this way filled me with dread. \n\nBut your courage shines with splendor, {name}. At your side, my way is lit.\n\nNo more hiding. The beast clad in black chitin, the one that killed my friends, dies in that cave. I am with you.", objectives = "Slay Fallowbarb.", completion = "Wayshelm told me everything.\n\nA debt of gratitude is owed. To you, and to the scouts who gave their life for our empire." }
WordHunterWoW_QuestEN[79315] = { title = "Lord Harlbrand", description = "", objectives = "" }
WordHunterWoW_QuestEN[79316] = { title = "Malfunctioning Harvester", description = "", objectives = "" }
WordHunterWoW_QuestEN[79317] = { title = "Morkus Grimlock", description = "", objectives = "" }
WordHunterWoW_QuestEN[79318] = { title = "Narla Thunderhoof", description = "", objectives = "" }
WordHunterWoW_QuestEN[79319] = { title = "Frenzied Owlbeast", description = "", objectives = "" }
WordHunterWoW_QuestEN[79320] = { title = "Gorthak Grimtusk", description = "", objectives = "" }
WordHunterWoW_QuestEN[79321] = { title = "The Catalyst's Gift", description = "I have an urgent message for you, adventurer.\n\nThe Revival Catalyst seems to be responding to the land's rumblings--perhaps even your feats!\n\nMiraculously, it now shares its power for nothing in return except one's mere presence.\n\nAntuka will know more. Go with haste, {name}. This is wondrous news.", objectives = "Speak to Antuka in Tyrhold.", completion = "Every other week, the catalyst will grant you enough power to imbue one piece of equipment.\n\nKeeper Tyr must be watching us. Wherever he is, this is no coincidence." }
WordHunterWoW_QuestEN[79322] = { title = "What the Duck?", description = "What the--why are all these ducks here? Something has them agitated. They almost knocked over my beautiful golden egg heirloom!\n\nWe need to clear out these chaotic quackers so we can continue our festivities. I'll keep them from entering the inn, but can you help clear out the rest?", objectives = "Scare off 10 ducks using the Horn of Honking.", progress = "Show those ducks who's boss!", completion = "Those ducks sure made a mess of things. Thanks, <name>." }
WordHunterWoW_QuestEN[79323] = { title = "A Fowl Concoction", description = "We need to put an end to this duck invasion.\n\nWhile I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My precious heirloom was among the items stolen!\n\nPlease, {name}. I won't stand for these pilfering poultry. I know a mage in Stormwind who might have some ideas on how to handle this.", objectives = "Speak with Emmery Fiske at the Wizard's Sanctum in Stormwind.", progress = "Have you spoken with Emmery yet?", completion = "Don't worry, I'm sure he'll have a good solution. Wait here, I think I see a portal forming." }
WordHunterWoW_QuestEN[79324] = { title = "To the Waterworks", description = "Getting the Waterworks up and running is our first objective. Nothing else we do matters if we can't get power to the facility.\n\nMeet up with Dagran and ZZ-01-47 once you get there. And try to keep them on the sidelines. I don't want to explain to Moira that her son was injured, or worse, under my care.", objectives = "Meet up with Dagran and ZZ-01-47 at the Waterworks.", completion = "This place is a mess! I think Zee-Zee and I will stay up here where it's dry." }
WordHunterWoW_QuestEN[79325] = { title = "Shadowvein Extraction", description = "I sent Zee-Zee ahead to the Shadowvein extraction site.\n\nFrom what they transmitted back it looks like the area is swarming with rock worms and covered in this... discharge. I gave them an upgrade while we were waiting for you.\n\nI don't know how effective it'll be in battle but the results should be shocking for anyone that tries to threaten them.", objectives = "Meet up with ZZ-01-47 at the Shadowvein Extraction Site.", completion = "<Zee-Zee beeps in recognition and excitement. It seems like they're ready to get underway.>" }
WordHunterWoW_QuestEN[79327] = { title = "The Glittering Shard", description = "<Glistening with an inner light, this shard of crystal feels warm to the touch..\n\nOrsenth may be interested in examining this piece of ore.>", objectives = "Bring the glistening clay to Orsenth near Nibelgaz Mine.\n\nProvided item:", completion = "A crystal shard? From a glittering cave? Why does that sound familiar to me?\n\n<She takes the crystal in her hands to examines more closely.>\n\nThis can't be! It's the healing crystal I mentioned earlier! We thought it was lost. What a wonder to hold it in my hands...\n\n<She sighs deeply, looking at Munderut.>\n\nI wish it could mend our minds as well as it mends our wounds. We need to get the vault back up and running." }
WordHunterWoW_QuestEN[79328] = { title = "Embassies and Envoys", description = "I feared what we would find when we returned here, but I am proud to see that though we were forced to leave, you were able to forge a friendship with the earthen and stand against the nerubians.\n\nWith your strength, we will win this. But first we need a plan, and for that we need space here in Dornogal for discussion.", objectives = "Set up your faction's embassy in Dornogal.", completion = "Ye mean tae tell me ye have been an interior decorator this whole time an ye have been holdin' out on me?\n\nWell done, <name>.\n\nYe are rearrangin' me chambers when we get home, ye are." }
WordHunterWoW_QuestEN[79329] = { title = "Glowing Harvest", description = "", objectives = "" }
WordHunterWoW_QuestEN[79330] = { title = "Duck Tales", description = "Take this potion, {name}. You should be able to communicate with your feathery friends with it.\n\nBut don't blame me for any unintended side effects you may experience.", objectives = "Use the potion to get information from 5 ducks.", progress = "Go on now, have a chat with those ducks!", completion = "What? Some of the ducks are druids?\n\nThey won't get away with their interference." }
WordHunterWoW_QuestEN[79331] = { title = "Just a Waddle Away", description = "We need to find out where those ducks are hiding our stolen goods! And who this mysterious Daetan is, while we're at it.\n\nI convinced Emmery to give me more of that potion. Take it and find my heirloom!", objectives = "Discover the duck's hiding spot.", progress = "Where would those ducks be hiding...", completion = "<Zinnia carefully examines the heirloom>\n\nDid a duck gnaw on this? This is going to take some elbow grease to polish out!\n\nThank you for your help, <name>." }
WordHunterWoW_QuestEN[79333] = { title = "The Fleet Arrives", description = "From the moment we crashed on this isle, it were clear as crystal we'd be needin' allies if we hoped to face Xal'atath. \n\nJaina and Thrall took off tae muster reinforcements, an' you and I set tae work seein' what could be done here with the earthen.\n\nAn' I have to say we've done well on our own, haven't we? \n\n<Moira smiles at you proudly.>\n\nBut it looks like our reinforcements may have finally arrived. Peacekeepers spied ships comin' this way. Go take a look an' confirm the good news!", objectives = "Scout the harbor for ships arriving from the Horde and Alliance fleet.", completion = "I'm glad to see you are well, <name>.\n\nThe journey took longer than anticipated. The capricious sea had its own plans it seems." }
WordHunterWoW_QuestEN[79335] = { title = "One More Tradition", description = "Before I shut down, I must craft an item that is meaningful to me. \n\nAs a Stonebound, I worked the mines. I had a lantern I made and used until I lost it in a collapse. I became Unbound shortly after.\n\nI wish to forge a new lantern to guide my way through these final moments.\n\nThe lantern was made of an ore found in small amounts around this area. I used a charged core in the lantern. You can find them in the stormfangs that roam these hills.\n\nGather the materials, and I will forge the lantern.", objectives = "Gather 5 ore and 5 Charged Cores near Fallside Outpost.", progress = "Have you gotten the materials I asked for?", completion = "These will do nicely!\n\nNow... hopefully I can remember how to forge a lantern." }
WordHunterWoW_QuestEN[79336] = { title = "The Forging of Memories", description = "Before its shutdown, we earthen would descend to the Awakening Machine below and renew our cycle. But now, even if it was still working, I would see my cycle broken and be remembered as I am.\n\n<Korgran lets out a deep sigh.>\n\nThese hands look strong, but they become heavier with each passing moment. The stiffness in my wrists and elbows will not let me carry the items to the forge.\n\nPlease, add the right material to the forge as I call them out.", objectives = "Help Korgran forge his lantern.", progress = "Oh, I almost forget. I did ask you to help with forging the lantern, didn't I?", completion = "Is it... hm, It looks like... I can't remember.\n\nBut this lantern is absolutely magnificent!" }
WordHunterWoW_QuestEN[79337] = { title = "The Last Journey", description = "This lantern is perfect.\n\nEnough of this. It is time! I can feel my memory clouding. We have to get going. Urtago is waiting for us. They will join us on my final journey to Mourning Rise, where we will conduct a ceremony.\n\n<Korgran forces a smile.>\n\nIt is nothing fancy, I promise. As I said, it is more symbolic than anything else.\n\nMy head feels heavy. What was I doing again? Hmm, oh, right! Meeting Urtago!", objectives = "Wait for Korgran and then regroup with Urtago outside at Fallside Outpost.", completion = "<name>, we have to find Korgran! If he keeps on exerting himself, he will shutdown in the middle of nowhere.\n\nAnd it's not safe for him to be out in his condition. He would be easy prey for stormfangs and even kobolds." }
WordHunterWoW_QuestEN[79338] = { title = "The Lost Earthen", description = "This is horrible! I knew I should have been keeping a closer eye on him.\n\nConfusion is the last symptom before a shutdown. Our memory is finite and starts overwriting. The more an earthen exert themselves, the faster their energy depletes and they lose memories. Korgran must be scared not knowing where he is--maybe not even who he is.\n\nI am such a boulder head!\n\n{name}, please, I think I saw him go east into the trees. Meet me there up the road!", objectives = "Help Urtago find Korgran.", progress = "Were you able to find any sign of Korgran?", completion = "Oh no, Korgran's condition is sliding downhill fast.\n\nShowing him the lantern was a good idea.\n\nThank you for guiding him back to me." }
WordHunterWoW_QuestEN[79339] = { title = "A Change of Tradition", description = "An Unbound earthen can't return to the Coreway, so we have Mourning Rise. But looking at Korgran, remembering our last conversation before...\n\nI may not be the Mourning Rise caretaker just yet, but with Korgran's condition, it falls to me to be in charge. \n\nAs Unbound, we made our own rules and traditions. So what if he doesn't want to stand at Mourning Rise? If a seaside memorial is what Caretaker Korgran wants, that's what he gets.\n\n{name}, meet me at the shore to the southeast of here.", objectives = "Meet Urtago and Korgran by the shore.", completion = "He enjoyed the walk, but it has taken a heavy toll on him.\n\nKorgran barely recognizes me now." }
WordHunterWoW_QuestEN[79340] = { title = "Tools of Declaration", description = "As Unbound caretakers, we have a tradition for when a master bequeaths their mantle to their apprentice. \n\nFiguratively, of course.\n\nTo do that, Korgran will need a horn.\n\nHe would then face me, blow the horn, and the sound signifies his passing the mantle of the Mourning Rise caretaker to me.\n\nI saw shalehorns to the west of here. I would be thankful if you could bring me several of their horns. I will choose one that is suitable.", objectives = "Collect 4 Pristine Horns near Restless Estuary.", progress = "Remember, the horns must be in pristine condition.", completion = "These are beautiful!\n\nI feel sorry for the shalehorns, but there are many of them around." }
WordHunterWoW_QuestEN[79341] = { title = "Cleansing Ashes", description = "The Unbound have a symbolic ceremony of cleansing. We perform it before a shutdown. \n\nIt is a symbolic process of purification. For it, we need to gather ashenfold, a flower that grows around the isle. We waft the smoke of the burned flowers through the fissures and cracks in our bodies to symbolically remove impurities.\n\nWe are then ready to embrace our final moments.\n\n<Urtago looks at Korgran with a hand on her chest. Her face falls.>", objectives = "Collect 6 ashenfold flowers near Restless Estuary.", progress = "Do you have the flowers, <name>?", completion = "Thank you, <name>. I will prepare them for the ritual." }
WordHunterWoW_QuestEN[79342] = { title = "As He Departs", description = "It is time for the ceremony, {name}.\n\nPlease place the bowl of ashenfolds by Korgran and then hand him the horn.\n\nOnce the ceremony concludes, I will be the new caretaker. Then I will have to say a final farewell to my friend.\n\nKorgran will shutdown peacefully, knowing we were here by his side in the place he loved most--something I wish and hope to have when it is my time.\n\nMy core is mud, but it is a great honor to stand here with him... and with you.", objectives = "Help Urtago and Korgran perform the ceremony.", progress = "It is a bittersweet moment.", completion = "What an honor it is to be here. To be present at such an event.\n\nYou were part of it, and I know that deep inside him, somewhere within Korgran's core, there will always be a living memory of you, <name>.\n\nThank you." }
WordHunterWoW_QuestEN[79343] = { title = "Everyday I'm Snufflin'", description = "Perhaps the kobolds of Gundargaz would be interested in this Odd Glob of Wax.", objectives = "Bring the Odd Glob of Wax to Gnawbles in Gundargaz.", progress = "You snuffle something good?", completion = "Middles always need more wax for project.\n\nTrade bigger, shinier ruby for if have lots. Get fancier things for helping.\n\nKeep snufflin'. Keep trading." }
WordHunterWoW_QuestEN[79344] = { title = "Urban Odyssey", description = "Did ye hear, {name}?\n\nA lot of folks from the city are eager to lend a hand an' support our attack on the nerubians and Xal'atath. I think it's worth reachin' out tae them tae see how they could pitch in.\n\nThe more support we gather, the better.", objectives = "Ask around Dornogal for pledges of support in the coming conflict.", progress = "I am glad to see you return, <name>.", completion = "Thank ye, <name>. The more people we get on board with helpin', the more successful we'll be.\n\nBut we won't get anywhere if we dunnae have a large enough fightin' force.\n\nThe earthen are nae in good shape. But I think Alleria may be helpin' with that." }
WordHunterWoW_QuestEN[79346] = { title = "Chew On That", description = "Fishing out here is not easy, especially when the spooky sounds of the darkness start to wear on the nerves.\n\nI've taken to chewing on the Duskstem from the tall plants nearby. It's sweet and chewy, keeps the jaw busy, and helps me pass the time!\n\nIf you could lend a hand by gathering some Duskstem with your flying mount, I would be most appreciative.", objectives = "Collect 20 Duskstem from the tallest plants that grow in the darkness.", progress = "Have you collected enough?", completion = "You made that look easy. It usually takes me an hour to climb one of those plants." }
WordHunterWoW_QuestEN[79349] = { title = "Entrepreneur, Inc.", description = "Okay, color me impressed. You are officially my Coinchamp! It's like a champion, only I pay you to do things. A mercenary, only with better branding.\n\nYou should meet my business partner, Ripsnoodle. He's working out some deals with his own coinchamps with the niffin over at Mmarl. He might have more work for you--though I recommend not buying anything he tries to sell you.\n\nYou can find Mmarl east of here. Just follow your nose, you can smell it from a mile away.", objectives = "Find Ripsnoodle in Mmarl.", completion = "Skedgit actually found something out there? She always did have a good nose for business." }
WordHunterWoW_QuestEN[79350] = { title = "Intro Dummy Quest Week 1 (Text Only)", description = "I am chuffed you are helping us with this venture that is so close to my heart.\n\nAs a lad, I loved dragons--as young children do--and was smitten with Sindragosa. I read all I could about her. When the Dragon Isles opened, I begged the Algeth'ar Academy to let me study the many volumes of Sindragosa's memoirs.\n\nIn them found a brief mention of a battle at Traitor's Rest. The Blue Dragons are staying mum, but clues to an epic story are all about here!\n\nI must know what happened here. For Sindragosa", objectives = "I am chuffed you are helping us with this venture that is so close to my heart.\n\nAs a lad, I loved dragons--as young children do--and was smitten with Sindragosa. I read all I could about her. When the Dragon Isles opened, I begged the Algeth'ar Academy to let me study the many volumes of Sindragosa's memoirs.\n\nIn them found a brief mention of a battle at Traitor's Rest. The Blue Dragons are staying mum, but clues to an epic story are all about here!\n\nI must know what happened here. For Sindragosa" }
WordHunterWoW_QuestEN[79351] = { title = "Level 25", description = "", objectives = "" }
WordHunterWoW_QuestEN[79352] = { title = "Level 24", description = "", objectives = "" }
WordHunterWoW_QuestEN[79354] = { title = "The Machine Speakers", description = "Ah, {name}! The {race} of the hour... We were just discussing you.\n\n<Moira nods towards Speaker Brinthe.>\n\nThere is some unfinished business for us to attend to, now that the High Speaker's transgressions have been corrected and the Awakening Machine restored once more.\n\nCare to stick around?", objectives = "Watch the conversation between Moira and Speaker Brinthe in Gundargaz.", completion = "It is a new day in the Ringing Deeps." }
WordHunterWoW_QuestEN[79355] = { title = "Prisoner Preservation", description = "The beasts took our people! Dragged them away when we were gettin' our first rest since our escape!\n\nWe only just escaped those nerubians. We can't afford ta lose more people.\n\nSearch Pillar-nest Vosh. It's where all those beasts came from. If we're lucky our people are still alive.", objectives = "Find 4 Expedition Members.", progress = "Survivin' ain't easy, but we gotta keep pushin' on.", completion = "You did all you could. I be in your debt. We be honorin' Jeti's memory by dealing with da nest." }
WordHunterWoW_QuestEN[79356] = { title = "Antifungal Firestarter", description = "Consider it a professional hunch, but those spores comin' out of those fungal pods and the ones afflictin' all da beasts are connected. \n\nMaybe if we destroy da fungal spore pods it'll slow whatever control those fungarians have on da beasts.\n\nTake these antifungal firebombs and torch as many fungal spore pods as you can!", objectives = "Burn 8 Fungal Spore Pods.", progress = "Too many strange tings occur this far underground. Watch yourself.", completion = "Excellent work my friend. Dat will keep these beasts in check." }
WordHunterWoW_QuestEN[79357] = { title = "Removing the Cap", description = "Aemara's mention of a large fungarian planting fungal pods worries me. Gotta be someting down in dat cave.\n\nWe can't just be waitin' for the fungarians to attack with a nest of mind-controlled beasts. We gotta prune dat plan before it has a chance to bloom.\n\nGet to Pillar-nest Vosh and kill that fungarian leader!", objectives = "Kill Agaricus Festerbloom.", completion = "That fungarian leader's plans are over, and the camp is safe again. Thank you, friend." }
WordHunterWoW_QuestEN[79367] = { title = "A Nebb in Need", description = "You! You no spider. Please, must help before spiders come again. \n\nNebb know Chittering Den. Never seen spiders here before. Eat grubs, eat kobolds. But spiders dark things from dark places. Hate light.\n\nCan't leave post. You take candles, yes? Light up barricade. Keep spiders away.", objectives = "Collect the Bundle of Candles and place candles along the barricade.", progress = "Keep away dark. Keep away spiders.", completion = "Good. We safe for now." }
WordHunterWoW_QuestEN[79368] = { title = "Hair of the Spider", description = "Light good, but more to do. \n\nSpiders came from everywhere. Nebb quick, Nebb heard them. But friend Snubjaw... he bit. Sick now.\n\nNebb might know a way, yes, turn venom into cure. Use bite to cure bite.\n\nBring venom. Hurry now!", objectives = "Collect 12 Undercrawler Venom.", progress = "You have venom?", completion = "Yes, nasty venom make perfect cure." }
WordHunterWoW_QuestEN[79369] = { title = "Protecting the Harvest", description = "Nebb young, no see past own snout. If harvest lost, many kobolds lost. Not just Snubjaw.\n\nCan no waste time. Kobolds starve if spiders gobble grubs and eggs.\n\nSave them, gather eggs. As many as can carry before spiders snatch all.", objectives = "Collect 20 Grub Eggs.", progress = "Bring eggs, we save harvest.", completion = "Many lost. With these, next grub season possible." }
WordHunterWoW_QuestEN[79370] = { title = "A Poultice for Poison", description = "Little venom, little wax...\n\n<Nebb reaches into his pouch and gives you a handful of thick, pungent wax.>\n\nYes, yes, should work. Finest poultice, family recipe. Hurry now, give to Snubjaw. He feel right better.", objectives = "Use Nebb's Poultice on Snubjaw.", progress = "Poultice fix him right up.", completion = "No work, he worse! But why?" }
WordHunterWoW_QuestEN[79371] = { title = "A Royal Cure", description = "Poultice no work! Wax right, venom wrong?\n\nYes... yes! Strongest cure need strongest venom. Nebb saw crawler. She queen in red and black, too big to bother with kobolds. Queen smelled juicy grubs and skittered for cave.\n\nNow you must follow. Collect royal venom. Please, Snubjaw have little time.", objectives = "Collect Queen Rickiticka's Venom to make a new poultice for Snubjaw.", progress = "Queen venom must work.", completion = "It work! He no green now. Thank you, thank you for saving friend Snubjaw." }
WordHunterWoW_QuestEN[79372] = { title = "A Clutch of Hope", description = "<The broodmother lies dead, coiled around a single egg. She gave her life to keep it from the spiders.\n\nYou should take it to Nebb. He and the other Grubtenders would know what to do with it.>", objectives = "Bring the egg to Nebb.", progress = "What this, another egg?", completion = "This not just any egg. Mother egg.\n\n<Nebb takes the egg from you. He holds it with reverence.>\n\nWith this, grubs not just survive. They thrive. Thank you. We protect." }
WordHunterWoW_QuestEN[79379] = { title = "Captain's Orders: No Prey, No Pay", description = "", objectives = "" }
WordHunterWoW_QuestEN[79380] = { title = "Bog Beast Banishment", description = "", objectives = "" }
WordHunterWoW_QuestEN[79381] = { title = "Captain's Orders: X Marks the Spot", description = "", objectives = "" }
WordHunterWoW_QuestEN[79382] = { title = "Captain's Orders: Plunderstudy", description = "", objectives = "" }
WordHunterWoW_QuestEN[79383] = { title = "Web of Manipulation - Activate", description = "", objectives = "" }
WordHunterWoW_QuestEN[79387] = { title = "Test Quest - Account Test (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[79432] = { title = "It's About Time", description = "Your timing is serendipitous. I require your assistance.\n\nNot all infinites have seen what Nozdormu has shown me. Not all would agree even if they had. Archaios is one such detractor. He must be eliminated.", objectives = "Slay Archaios the Artificer.", progress = "The other infinites jeopardize our mission. We cannot let them wreak havoc on the timeways.", completion = "Reckless. They have unraveled the threads of time!" }
WordHunterWoW_QuestEN[79433] = { title = "Seeking Expert Advice", description = "Take this spool to Moratari. Perhaps she can make sense of this relic.", objectives = "Speak with Moratari.\n\nProvided item:", completion = "What do you have there? This artifact is absolutely radiating with temporal power!\n\n<Moratari leans in for a closer look.>\n\nAha! Even more brilliant than I thought! Assimilating the latent temporal signatures of unraveled causalities...\n\nSorry, I am getting ahead of myself. Allow me to explain." }
WordHunterWoW_QuestEN[79434] = { title = "Weave It To Me", description = "The other infinites are not as judicious in their treatment of the timeline. They have rather torn through time in their reckless opposition to our efforts.\n\nThough we cannot simply mend the timeways, we may yet repurpose its loose threads.\n\nReclaim the threads of time from our enemies and we shall weave you a cloak worthy of the Infinite Dragonflight.", objectives = "Collect 3 Threads of Time from Infinite Ravagers.", progress = "It is our duty as responsible scholars to clean up after ourselves... and others.\n\n<Moratari glances toward the distant ravagers with an annoyed expression.>\n\nWe cannot let stray threads continue to create temporal anomalies.", completion = "Excellent. Now we just need something to hold them together." }
WordHunterWoW_QuestEN[79435] = { title = "What's Hours Is Yours", description = "Horos, our antiquities collector, should have a chronobadge you can use to fasten together the temporal threads you collected.\n\nWith the chronobadge, Momentus can craft the threads into a powerful cloak for you to wear!", objectives = "Purchase a Chronobadge from Horos, then speak with Momentus.", progress = "That cloak will be able to absorb loose threads of time, adding them to its own magic. The prospect of infinite power is enticing, is it not? Just don't let it go to your head.\n\nLet it go to your cloak instead!\n\n<Moratari giggles.>", completion = "Wonderful! Try this on.\n\nWith the temporal magic in this cloak, you will be able to see and collect the scattered threads of time.\n\nThere is no limit to how many you can have--the possibilities are infinite!" }
WordHunterWoW_QuestEN[79437] = { title = "Knot My Problem", description = "These temporal anomalies are getting out of control. Normally, our research does not unravel the timeline this much--I suspect the other infinites are to blame.\n\nUse this chronostabilizer to zip up the frayed rifts.\n\nBe aware--this may briefly create even more anomalies. I trust you know how to handle them.", objectives = "Use the Chronostabilizer to close 3 Time Rifts.", progress = "Every moment moves us toward a new possibility. With every fight, we learn and change.", completion = "Change begets change. Such is the way of the infinites. It is our duty to choose which changes are worth preserving." }
WordHunterWoW_QuestEN[79438] = { title = "Goodbyes Are Hard When You Live Forever", description = "We have one last anomaly to deal with here before we can study the history of Pandaria.\n\nHelp us stabilize the timeway and secure our mission.", objectives = "Defeat Eratus, the Unwoven Paradox.", progress = "Dealing with paradoxes can be difficult, but these are the risks we accept.", completion = "Thank you for your aid in battle, <name>. I am sure Eternus will have need of you yet!" }
WordHunterWoW_QuestEN[79440] = { title = "Recalling the War", description = "Our operations here are secure. For now, anyway!\n\nIt is time for you to begin your journey to the past so that we may observe how history unfolded.\n\nSpeak with Eternus if you have any final questions about our mission. She can show you how these events began.", objectives = "Ask Eternus to show you the events of the past.", completion = "Good luck, <name>. We will be watching you." }
WordHunterWoW_QuestEN[79448] = { title = "Leave No Flightstone Unturned", description = "It's so exciting to be in Valdrakken! Cuzolth and I have never been here before. And it's everything we hoped it would be. Some of the others have even introduced themselves. They actually thanked us for our work studying Flightstones and Crests. That's every researcher's dream!\n\nSo I need your help again. Could you find some Flightstones and a new piece of adventuring gear? Then come back to Cuzolth for an upgrade? It would really help us solidify our new position here.", objectives = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 4 equipment using Flightstones.", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! You are truly a supportive breeze in flight. Please take these tokens of thanks." }
WordHunterWoW_QuestEN[79453] = { title = "Awakened Crests, Unlimited Possibilities", description = "Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here.\n\nOf course, I'm sure you know that Flightstones can only go so far. You need Awakened Crests to upgrade powerful adventuring gear. Much like Flightstones, these Crests are rewarded through many different activities. Awakened Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Whelpling's Awakened Crests, and we can help you upgrade some gear further.", objectives = "Acquire 15 Whelpling's Awakened Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then return to Vaskarn in Valdrakken.", progress = "If you're having a hard time finding Whelpling's Awakened Crests, you can search for hidden treasures around the Dragon Isles. There's no shortage of those!", completion = "This is wonderful. I'm so excited for you to grow in power!" }
WordHunterWoW_QuestEN[79469] = { title = "Lurking Below", description = "", objectives = "" }
WordHunterWoW_QuestEN[79470] = { title = "Waters of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[79471] = { title = "Bleak Sand", description = "", objectives = "" }
WordHunterWoW_QuestEN[79475] = { title = "Charging Up That Hill", description = "Before we use the conduit to summon the stormrooks, we need to recharge it. There are other, gentler ways to do this but... we have to work with what's on hand. \n\nThe way to the peak is overrun with hostile elementals cast off from the storm. If we send them back to their plane, we can capture their residual energy and re-energize the conduit.\n\nWhile you work on recharging the conduit, we will go ahead and prepare for the ritual at the peak.", objectives = "Charge the conduit with elemental energy.", progress = "Have you finished charging the conduit?", completion = "The conduit! Do you feel that? It's humming--no, it's practically singing with power. \n\nI've heard this song before, late at night in the Stormperch's rookery. When the storms would come and lightning flashed across the bay, the rooks would answer just like this. \n\nYou can't hear it?" }
WordHunterWoW_QuestEN[79476] = { title = "Heeding the Call", description = "Earthen from across the island have been drawn to this place. Kind of a strange coincidence you'd show up now too.\n\nMaybe it's because Baelgrim's gone or... a new Stormward's coming. Or it could just be barometric pressure...\n\nBah! There's time enough to spin wild theories later. Right now, we need to assist the pilgrims that have foolishly attempted the summit unprepared. We can't be worrying about them while we try to summon the stormrooks.", objectives = "Help 8 Stranded Pilgrims on the mountain.", progress = "These earthen pilgrims seem intent on reaching the peak. I hope we can keep them safe.", completion = "If the storm summoned these earthen here, does that mean they have a role to play in what comes next? \n\nWe've directed them to hole up in the cave near the peak for now. I'm not sure what's next for them--or any of us." }
WordHunterWoW_QuestEN[79477] = { title = "Strays", description = "Kurdran Wildhammer has come to train the new Stormriders in aerial maneuvers. Thrall says his clan rides gryphons--much like the Stormriders ride stormrooks--so he should be of great help to us.\n\nUnfortunately, a few of our new recruits seem to have, uh, wandered off with their stormrooks. I wanted them to have a chance to bond, but it's time to come home.\n\nWould you mind rounding them up? Thrall and I are putting together something special for these \"rookies\" lessons.", objectives = "Round up the stray recruits.", progress = "You found those stray rookies yet?", completion = "Right then! Good on ye for roundin' everyone up. We're lookin' tae start formal flight trainin' and we wouldn't want any stragglers, now would we? \n\nI'm eager to see what these stormrooks--and the earthen--can do." }
WordHunterWoW_QuestEN[79480] = { title = "Paying Respects", description = "Please excuse my absence. It was never my intention to turn my back on the Stormriders, then or now. But I needed to come here and pay my respects to Baelgrim.\n\nUnfortunately, these blasted nerubians are still lingering. I think they're searching for something, but I don't know what. Whatever their reasons, I cannot abide them lurking where Baelgrim fell.", objectives = "Clear out nerubian stragglers.", progress = "I don't know who or what these nerubians are searching for, but they defile this place with their presence. Clear them out.", completion = "This is a gift. Baelgrim may be gone, but his stormrook seems ready to carry on his fight. It's been a long time since I've felt such a connection. Such purpose. I don't intend to turn my back a second time." }
WordHunterWoW_QuestEN[79481] = { title = "Tending to the Terrified", description = "All happen so fast. One moment, we gathering eggs and grubs. Next, spiders swarming.\n\nNebb drag me here, many others trapped. Caught in webs, soon to be feasts. Must save the Grubtenders. \n\nWe tenders, not fighters. Do not let friends become meals.", objectives = "Rescue 6 Terrified Grubtenders.", completion = "Aha, Grubtenders free! They survive to harvest again." }
WordHunterWoW_QuestEN[79489] = { title = "Gems of Power", description = "You have found a gem that improves your combat capabilities when socketed into a prismatic socket found in your chest or leg armor.\n\nSocket this Chipped Deadly Sapphire into your equipment to increase your Critical Strike chance.", objectives = "[Shift Right Click your chest or leg armor and socket the Chipped Deadly Sapphire.]" }
WordHunterWoW_QuestEN[79504] = { title = "Dripsy Forgot Her Candle", description = "Gather round, tenderfoots, and Granny Scribbles tell you story.\n\nStory of what happen when Dripsy forgot her candle.\n\nDripsy little tenderfoot, like you, who wander away from tribe...", objectives = "Relive Granny Scribbles' story.", progress = "You listen too. Maybe learn something.", completion = "Important not forget candle. Something every little kobold need learn." }
WordHunterWoW_QuestEN[79505] = { title = "Chomps and the Cave-In", description = "Sit down, stop talk, and Granny Scribbles tell you story. Story that maybe save life one day.\n\nAbout what happen when not listen to old, wise kobold. Like me!\n\nStory of Chomps and the cave-in...", objectives = "Relive Granny Scribbles' story.", progress = "Important pay attention. Following along?", completion = "You not too old respect elders, <name>. Even if not kobold." }
WordHunterWoW_QuestEN[79507] = { title = "The Day the Stoneheads Came", description = "What? Want scary story?\n\nYou ask. Granny Scribbles give what want. Maybe then sit still like good tenderfoots.\n\nScariest story Granny know, yes. Story about the day the stoneheads came...", objectives = "Relive Granny Scribbles' story.", progress = "Hope story not too scary for you.", completion = "<Granny Scribbles gestures around to the room.>\n\nNot all stoneheads bad, seems like.\n\nStill, little kobold need know what happen. What can happen." }
WordHunterWoW_QuestEN[79508] = { title = "Mipsy Mole-Rider", description = "Time for happy story. Not all days bad.\n\n<Granny Scribbles gently scratches Ol' Snorler behind his ears.>\n\nTell story of how be friends with moles. Story of Mipsy mole-rider...", objectives = "Relive Granny Scribbles' story.", progress = "You listening?", completion = "Tenderfoots always fan of that one.\n\nWhat you think of mole? Think ride good as Mipsy?" }
WordHunterWoW_QuestEN[79510] = { title = "The Wickless Candle", description = "Now tell story of very far place called \"surface\". New friend from there, yes, so they know what Granny Scribbles talk about.\n\n<Granny Scribbles nods sagely as she points you out.>\n\nStory of how kobold discover it long go, and what find when do. Story of the wickless candle...", objectives = "Relive Granny Scribbles' story.", progress = "Sound like place you know?", completion = "You not bad listener, <name>. Name you honorary tenderfoot, Granny Scribbles thinks.\n\nMaybe next time you tell Granny Scribbles story. Never too old to learn new one." }
WordHunterWoW_QuestEN[79511] = { title = "Identity Crisis", description = "Hey {name}, over here!\n\nI just finished speaking with Emberthal. I'm not sure what, but something is bothering her! \n\nShe had lots of odd questions about visage forms. Could she be ready to choose one? How exciting! I think I saw her head over to the Victorious Visage.\n\nYou should check on her, I bet you could get her to spill the secret!", objectives = "Speak with Emberthal in the Victorious Visage.", completion = "I take it Chromie sent you?" }
WordHunterWoW_QuestEN[79512] = { title = "Who Are You?", description = "Perhaps Cindrethresh is right. \n\nStill, if I'm to pick a visage, I should at least give it some thought.\n\nI just do not fully understand the concept of visage forms.\n\nI have heard that visage is supposed to be ones own expression of self.\n\nHow does one discover what that is?\n\nMaybe some of the individuals here in Valdrakken hold the answers.\n\n{name}, I need you to gather intel. I will remain here. Report back your findings when you are finished.", objectives = "Speak with 9 Valdrakken Visitors in Valdrakken.", progress = "Have you completed your reconnaissance yet?", completion = "Interesting... These are quite the varied answers." }
WordHunterWoW_QuestEN[79513] = { title = "Dragon Isles Adventuring: Being Yourself", description = "I worry about Emberthal. Her mood has grown increasingly dark.\n\nBy sticking to citizens of the city, she is looking for ways she is similar to them, instead of what makes her unique.\n\nPerhaps a broader sample size is in order?\n\nShe needs stories to guide her. There are many such individuals with stories to tell in the Dragon Isles.\n\nGo, and speak with them. \n\nWould that I could go myself, but the duties of a Scalecommander never rest.", objectives = "Speak with 8 residents of the Dragon Isles and listen to their stories.", progress = "Have you spoken with everyone?", completion = "Thank you, <name>. If these do not help Emberthal, I do not think anything can." }
WordHunterWoW_QuestEN[79514] = { title = "Don't Threaten Me With a Good Time", description = "Emberthal seems worried, but I'm sure she'll come back. And when she does, she'll pick a visage form!\n\nChromie told us all about the celebrations dragons used to have for Visage Day.\n\nSo, Kalecgos and I are going to blow stuff up! Fireworks, mostly.\n\nWe'll need some arcane residue to make them, though.\n\nConveniently, there are some arcane elementals just outside the Gardens of Unity that are ripe for the harvest.\n\nThe three of us have some other preparations to make here in Valdrakken.", objectives = "Collect 100 Arcane Residue from Volatile Arcana in The Cascades.", progress = "These volatile elementals make the perfect base for fireworks!", completion = "Now we're talking!" }
WordHunterWoW_QuestEN[79515] = { title = "Gather Your Rosebuds", description = "Emberthal is quite troubled. It reminds me of a certain bronze dragon when she chose her visage form.\n\nNot to worry! Once Emberthal has returned, we shall throw a proper Visage Day celebration.\n\nThe fireworks are to match the colors of the dragonflights.\n\nEach enclave of the city grows special flowers in accordance with that enclave's flight.\n\nThree of each color should be enough for the first batch of fireworks.", objectives = "Collect 3 of each color of Flight Flower in Valdrakken.", progress = "We still require more flowers if we are to provide a celebration worthy of dragons.", completion = "Thank you, <name>. This should be sufficient." }
WordHunterWoW_QuestEN[79521] = { title = "Seizing Evidence", description = "Councilward Merrix has authorized trade goods from the Deeps to be transported through this depot. However, we have received a tip that more than crafting materials are being sent and received here.\n\nDornogal observes strict rules about what we trade and with whom. All commerce must serve the Edicts, not the interests of individuals. We do not abide unsanctioned trading.\n\nWe have started going through the crates here to find smuggled goods, but we haven't found anything--yet. Help us take a look.", objectives = "Collect 3 Seized Shipments.", progress = "The tip we received was from a highly reliable source. There must be something here.", completion = "That is odd... These are very normal trading goods. There is nothing illicit here.\n\nThis is all you found?" }
WordHunterWoW_QuestEN[79522] = { title = "Withheld Information", description = "There has to be something we're missing. The tip we received was from a very reliable source. We have no reason to believe we were being misled.\n\nThe Councilward will want us to get to the bottom of this, and I refuse to disappoint him.\n\nWe haven't been able to get any additional information out of the workers, but maybe you'll have more luck. \n\nSpeak to the ones we have detained here, and see if you can learn anything.", objectives = "Interrogate 5 Line Workers to gather information on the shipments.", progress = "Someone here has to know something.", completion = "Ah-ha! False bottoms in the crates? Very clever.\n\nThat could be enough proof by itself to shut down this depot for good. But for the Councilward's records, we will need a full report of any smuggled goods we find." }
WordHunterWoW_QuestEN[79523] = { title = "Something Hidden", description = "So, they have built extra compartments in the crates to hide extra items, eh? That explains how they have been smuggling goods into and out of Dornogal without our auditors knowing.\n\nExcellent work, {name}! But now the fun part of our job: those crates will have to be broken open and the smuggled goods taken into evidence.\n\nSmash the bottoms out of the crates and bring anything you find back to me.", objectives = "Smash 3 False-Bottomed Crates and gather any hidden evidence you find inside.", progress = "Better luck this time, I hope?", completion = "<Kragad frowns as he looks over the goods you found.>\n\nSome of these goods are from Azj-Kahet... We are specifically forbidden from trading with the nerubians in any capacity. We cannot risk any resources falling into the hands of our enemies.\n\nThe Councilward must be informed." }
WordHunterWoW_QuestEN[79525] = { title = "Report to the Councilward", description = "Those receipts you found... Steelvein is a known smuggler that we've been chasing for a long time. The Councilward will be pleased to finally have solid evidence on his activities, and maybe even on his whereabouts.\n\nBring these receipts to Merrix immediately. He will want to study them in detail. He said he was heading back to his office, so you should be able to find him at the Councilward's Rise.\n\nI'll package up the rest of the evidence to be brought to him later. Good work today.", objectives = "Take Steelvein's receipts to Merrix at the Councilward's Rise in Dornogal.", completion = "<Seems like there is nothing else to do but leave the receipts on Merrix's desk.>" }
WordHunterWoW_QuestEN[79526] = { title = "Sedition", description = "<The poster reads:>\n\nMERRIX is CORRUPT! STEELVEIN is WEAK!\n\nThey cannot protect the earthen! They do not care about them! They spit upon the Edicts!\n\nMerrix was BRIBED to reopen Steelvein's smuggling operation! Steelvein HIDES behind Merrix's authority!\n\nThey are taking from YOUR pockets to line THEIRS!\n\nDO NOT TRUST THEIR LIES!", objectives = "Speak to Merrix at the Councilward's Rise in Dornogal.\n\nProvided item:", completion = "Yes, I am quite aware of the situation.\n\nIt has rather disrupted my morning." }
WordHunterWoW_QuestEN[79527] = { title = "Damage Mitigation", description = "Obstorn has confirmed that Ardgrin, the overseer in charge of my supply line that runs from the Deeps into Dornogal, is the one who tipped off my peacekeepers.\n\nIt is therefore also my opinion that Ardgrin is the one who penned this sedition. He must have sent his workers upstairs to post them around the city.\n\nIt is imperative that we remove them before these rumors spread further. Tear them down for me.", objectives = "Tear down 8 Seditious Posters in Dornogal.", progress = "I would not have these rumors spreading any farther than they already have.", completion = "Very good.\n\nThat will help stem some of the damage Ardgrin is trying to do to my reputation--both of my reputations." }
WordHunterWoW_QuestEN[79528] = { title = "Dispelling Rumors", description = "Many of my peacekeepers have already caught wind of Ardgrin's sedition.\n\nI am told some are losing faith in my integrity as Councilward, believing that I have been taking bribes from smugglers to bolster my own coffers.\n\nI can provide proof that no such transactions have taken place--clearly--but we need to stop them from murmuring amongst themselves and giving the rumors power. Lies become truths through repetition.\n\nIf you find any discussing the matter, kindly disperse them.", objectives = "Disperse 6 Murmuring Peacekeepers in Dornogal.", progress = "I can assuage their fears later.\n\nFor now, we just need to prevent the situation from worsening.", completion = "I am pleased to hear that most of them were reasonable." }
WordHunterWoW_QuestEN[79529] = { title = "Forcing My Hand", description = "I do not know if Ardgrin merely intended to sabotage me or if he wanted to force a confrontation. Either way, a confrontation he will have.\n\nI believe this situation can be rectified peacefully, but I cannot do it as the Councilward. Steelvein has never appeared in the stone, but he must now. I will parlay with Ardgrin in the Deeps and this situation will be concluded.\n\nI would have you accompany me, but there are some things I want you to know before that. Help me prepare and I will speak with you.", objectives = "Help Merrix disguise himself as Steelvein.", completion = "I will have this solved peacefully.\n\nThough if Ardgrin asks for violence, we will answer." }
WordHunterWoW_QuestEN[79530] = { title = "Bad Business", description = "I have not been to the Deeps since their machines shut down. Obstorn will have to guide us to Ardgrin's depot.\n\nOnce there, I will attempt a conversation. If Ardgrin is not amenable, which I suspect will be the case, we will respond with equal force. Our goal is to bring him back into the fold, not to beat him into submission. Ruling by fear only breeds resentment.\n\nWe will meet you in the Deeps. Come swiftly--and, of course, speak of this to no one.", objectives = "Meet Steelvein in the Ringing Deeps near Hallowfall Gate, then confront Overseer Ardgrin.", completion = "Now that Ardgrin is willing to talk, we will talk. And all of this will be settled.\n\nYou have my gratitude, <name>." }
WordHunterWoW_QuestEN[79532] = { title = "Tinker, Tailor, Soldier, Spider", description = "I must thank you again for rescuing little Spindle from her predicament, my morsel. As a reward for your work, I would like to let you take loom and direct the weave of my newest tapestry.\n\nMeesk the Venomtongue threatens my weave-rats. He slanders my Queen. And he lends creedence to Ansurek's campaign of misinformation without a single thought to the consequences.\n\nI believe it is time that I sent Meesk and his ilk a message. Go into the city and find out as much as you can about our 'Venomtongue.'", objectives = "Gather rumors about Meesk the Venomtongue from the denizens of the Umbral Bazaar.", progress = "Mm... Do hurry, my little morsel. I do not want little Meesk to run off before he has the chance to sample the fruits of his labor.", completion = "Kehehe... Indeed? I suppose I should not be surprised that someone as loose-tongued as Meesk holds a fondness for the underground's more banal pleasures.\n\nHe is prideful... And he is gluttonous. That should be more than enough for our purposes, I think." }
WordHunterWoW_QuestEN[79537] = { title = "Jrz Test Currency Quest", description = "{name}, the Primalists have managed to summon fierce Elemental Storms all across the Dragon Isles. \n\nWhen a storm is active go to it and slay the imbued creatures there. \n\nThen collect the Elemental Overflow from the slain foes. Be aware that the stronger the foe, the more Elemental Overflow you will collect.\n\nWe must not let the Primalist elemental corruption grow unchecked.", objectives = "Defeat Elementally Imbued creatures to collect Elemental Overflow while in an Elemental Storm." }
WordHunterWoW_QuestEN[79538] = { title = "Smelly Shrubberies", description = "Jenni here says she's got some creepers attackin' the goblins. I haven't seen any myself, but I do smell opportunity!\n\nWe've got our own anti-creeper perfume. It's the same recipe we use for the incense around town. Rub it on, and everything stays away! I'm sure we can sell some to the goblins.\n\nBut I'm out of materials--smellsage branches, specifically. If you gather some for me, I'll cut you in on the profits!", objectives = "Collect Smellsage bush branches for Rhubarn.", progress = "If you smell feet, you're in the right spot.", completion = "I could smell 'em the moment you came in! Those will work." }
WordHunterWoW_QuestEN[79539] = { title = "Electrifying!", description = "You wanna help the Venture Company? And you don't mind being disposable?\n\nOkay, listen up. When we moved in here, there were no monsters in town. But now we're finding dead workers, chewed up. It's bad for business.\n\nFortunately, I've got a way to make money off this: an electrocution helmet. I call it my Debugger Hat.\n\nTake the latest model for a test run outside town. Kill the bugs. The niffen will see you, see that Debugger Hat at work, and know it's got good reviews.", objectives = "\"Advertise\" the Debugger Hat by hitting Noth swarmites with it outside of Mmarl.", progress = "It oughta just kill 'em, but who knows? You might see other results, too.", completion = "So it had some extra effects? Great! The hype is real! What exposure! The orders will be pouring in!\n\nYou ever consider becoming a walking advertisement? Could have a bright future in making cash for me. For now, here's your wages." }
WordHunterWoW_QuestEN[79540] = { title = "The Party's Over", description = "Nope, nope, nope!\n\nLook, I'm used to dealing with the additives in our swimming hole and keeping things at \"marginally safe\" levels, but spiders emerging to chew us to death? That's a hard pass from me. \n\nThis is OUR place, why are they buggin' us?", objectives = "Investigate the pool area in Mmarl.", completion = "We put an incense beacon in there to keep bugs out. If the goblins changed it..." }
WordHunterWoW_QuestEN[79541] = { title = "Burn It With Fire", description = "So the goblins removed the incense the niffen used to keep those creepy pests out... because it smelled bad?\n\nHonestly, I'm not surprised. Maybe we can show them that they need to work together. Leading by example! Here, I'll lend you a flamethrower. I know mine works, without weird... chicken-like effects.\n\nHead in, clear out the nests, and put the right incense back in there!", objectives = "Burn the Pillar-nest Hearts and replace the incense in the Mmarl cave.", progress = "The cave is just up ahead.", completion = "Okay, that flamethrower. I need it. I guess I'll talk to Gazlowe... but don't tell anyone that I did." }
WordHunterWoW_QuestEN[79542] = { title = "The Councilward's Summons", description = "Councilward Merrix requests your presence in his office.\n\nHe received the documents you left and would like to discuss the Steelvein situation with you further.\n\n<Saradi regards you as if she is unimpressed. She also seems to be an earthen of few words.>", objectives = "Meet Merrix at the Councilward's Rise in Dornogal.", progress = "I am pleased you made it. The suspense was eroding me away.", completion = "Steelvein is a paradox in a city founded upon order and rules.\n\nPerhaps this presents an opportunity." }
WordHunterWoW_QuestEN[79543] = { title = "Dornogal's Benefactor", description = "You are in a unique position, {name}. A position to learn.\n\nYou met those who would bring this \"Bender of Edicts\" to justice, but what of the people of Dornogal? What do the earthen think of this Steelvein fellow? \n\nHumor me. Take the smuggled goods you intercepted and bring them to their intended recipients. Tell them the items are a gift from a \"mutual friend.\"\n\nYou might be surprised to learn who benefits from these... illicit deeds.", objectives = "Distribute smuggled goods around Dornogal.", completion = "Harthan mentioned Ardgrin, you say?\n\nHe is a trade overseer from the Ringing Deeps. If he quarreled with Steelvein, that certainly concerns me." }
WordHunterWoW_QuestEN[79544] = { title = "Security Through Trade", description = "If we're to solve this quarrel between Steelvein and Ardgrin amicably, then we'll need to make some new friends.\n\nOne of Ardgrin's employees, Obstorn, frequents a cinderbrew speakeasy here in Dornogal. Only Machine Speakers may enter it.\n\nEven as Councilward, I am not able to access it. However, there are others in the city who can.\n\nBevrusi, a Gundargaz trader, should be able to give you access. If you can grease her palm, she may be able to supply you access.", objectives = "Convince Bevrusi to give you access to the cinderbrew speakeasy.", progress = "Do I know you?", completion = "So what do you say, surface-runner? \n\nYou polish my back and I'll polish yours. Do we have a deal?" }
WordHunterWoW_QuestEN[79545] = { title = "The Market Reeve of the Forgegrounds", description = "I've heard liquid opal tastes remarkable but no matter how often I peruse the auctions here, it's never for sale. It's quite rare.\n\nLuckily for you, there is one person who can find the stuff. Vokgret, the market reeve of the Forgegrounds. Nothing circulates in the city's flow of trade without her knowledge.\n\nI don't often try to do business with one as... connected as her. But you'll have no qualms about it, I'm sure!\n\nAt this hour, you'll find her over by the inn.", objectives = "Acquire a Vial of Liquid Opal from Vokgret.", progress = "<Vokgret speaks without looking up from her paperwork.>\n\nThe city certainly is a busy place.", completion = "Each corner of the Forgeground works in unison with each other like cogs in a machine.\n\nAll it takes is a single piece to fail to bring it all down.\n\nBut despite the disruptions, you have proven yourself resourceful.\n\nKeep this up and the right people will begin to notice.\n\nIf they have not already.\n\n<Vokgret peers at you over her spectacles and smiles.>" }
WordHunterWoW_QuestEN[79546] = { title = "The Machine Speakeasy", description = "Machine Speakers are odd and secretive units, some prone to paranoia. \n\nEven so, the grievance they have against Steelvein must be smoothed over.\n\nAs you have seen in the Forgegrounds, their quarrel with a single smuggler has put the entire city at risk. As Councilward, I will not stand for it.\n\nLet us go talk to Ardgrin's employee, Obstorn, and see if he can deliver a diplomatic message to his overseer in the Deeps.\n\nI will meet you in the tunnels.", objectives = "Enter the speakeasy in the tunnels below Dornogal then confront Obstorn.", progress = "I would have us exchange words, not blows.", completion = "I abhor violence, <name>.\n\nDissent. Desperation. Distrust. These are the consequences of ruling through fear.\n\n\n\nBut, sometimes, violence brings about clarity--and with it, revelations." }
WordHunterWoW_QuestEN[79552] = { title = "Hot Wax", description = "Oh. Fire bees bit bigger than Janky expect. Look mean.\n\nOther hives meaner, though. This best spot.\n\nYou go grab wax. Janky stay here to...supervise. Yes!", objectives = "Collect 12 Fire Bee Wax from the Cinderwold.", progress = "Is fire bee wax hot enough to melt self?", completion = "Yes! This make good candle, Janky sure." }
WordHunterWoW_QuestEN[79553] = { title = "A Natural Remedy", description = "We stabilized most of the injured. But many of the earthen you saved need more help. Nerubians often fight with corrosive poisons that eats away even our stone bodies.\n\nFungarian flesh has long been used by our healers for its medicinal powers. The fungarian takeover of the quarry is one unexpected boon to our situation, one we will adapt to.\n\n<Adelgonn looks grimly proud.>\n\nOne we will adapt to. As the Unbound always do.\n\nBut I can't leave Ebona's side. Will you help me?", objectives = "Collect 10 Fungarian Chunks in the Orecreg.", progress = "Please, hurry. The nerubian poison will deal irreversible damage given enough time. If it erodes enough of their frame or seeps into their memory gem... Then we may not be able to save them.", completion = "You brought back more than I expected. Thank you. Now, I will make the poultice." }
WordHunterWoW_QuestEN[79554] = { title = "Holy Hydrocarbons", description = "These devotional candles might be of interest to Janky the kobold candlesmith in Gundargaz.", objectives = "Collect Devotional Candles for Janky in Gundargaz.", progress = "What smell like new candle?", completion = "<Janky nibbles on one of the candles.>\n\nMhmm...mmm...fish oil...and touch of...sun blossom?\n\nInteresting technique, yes!" }
WordHunterWoW_QuestEN[79555] = { title = "Deep Wax Galactic", description = "While sourcing it may not be pleasant, this waxy substance seems like it might make a fine candle.\n\nJanky the candlesmith in Gundargaz might be interested in this.", objectives = "Collect Waxy Excretions and bring them to Janky in Gundargaz.", progress = "What bring Janky?", completion = "Good bug wax, <name>! Make fancy bug candle out of this.\n\nScented, too!" }
WordHunterWoW_QuestEN[79556] = { title = "On the Job Training", description = "Stoneheads use steam to run whole place. Have lava, have water, make sense.\n\nRepairs not going well, we hear. No new parts from factory. \"Against rules\" to use scrap, been told. A lot.\n\nHelp get old machines work. We watch, learn. Maybe not get yelled at for helping.", objectives = "Help Steamwarden Hurlt repair the steamworks.", progress = "How go?", completion = "Seem easy enough. Put steam in pipe, try not to cook self.\n\nI get!" }
WordHunterWoW_QuestEN[79558] = { title = "Feathered Fiend", description = "The trinket appears to be a Noblegarden decoration of sorts. You should return this to the festivities at Razor Hill.", objectives = "Bring the Noblegarden Trinket to Sylnaria Fareflame at Razor Hill.", completion = "Well now, how did that go missing? Don't worry, I'll see to it that any stolen decorations are restored!" }
WordHunterWoW_QuestEN[79559] = { title = "The Verdigrease Knight", description = "Think you brave?\n\nBeen looking for brave, but not find much. Not sure you count, look like tenderfoot who run home to granny if scrape knee.\n\nHow about way to prove it? You hit me as hard as can. Try kill me.\n\nIf I not dead, then I get kill you, later.\n\nNot look like it take more than one chop for you.\n\nDeal?", objectives = "Slay the Verdigrease Knight.", progress = "Going to run away?", completion = "Hmm, sound like should have hit him harder. Always going on about knights not being brave enough." }
WordHunterWoW_QuestEN[79561] = { title = "Lord of the Giants", description = "Can tell you not new to questing. Fell many beasts in your time, am sure, like good knight must.\n\nGreasebaddaden, king of giant slimes, lair nearby. Perfect chance to prove valor to court!\n\nHas giant fork jammed in head, can't miss. You know what do.", objectives = "Slay Greasebaddaden, King of the Giants.", progress = "Big, have fork in head. Know him when see him.", completion = "Return triumphant! Valor stick to you like reek of old grease.\n\n<Walkmay pauses, sniffing gingerly.>\n\nThat a lot of valor!" }
WordHunterWoW_QuestEN[79563] = { title = "Lady of the Lake", description = "Shown great bravery. Humbility. Honor.\n\nWould make good Knight of Brown Table.\n\nOnly task left now is most sacred. Beseech Lady of Lake for blessing. She will judge whether worthy or not.\n\nLake in back of cave. More pond, really, but no tell her that. Puddle Lady not have same ring.", objectives = "Gain the Lady of the Lake's blessing.", progress = "Not far, just in back of cave.", completion = "Only finest knights return with Lady's blessing.\n\nMost get lost somehow. Not far, really, so bit odd.\n\nStill, you make great knight, <name>. We sure." }
WordHunterWoW_QuestEN[79564] = { title = "The Verdigrease Knight Returns", description = "Am back, as promise.\n\nHear you now brave knight.\n\nReady fulfill your end of oath? My turn strike YOU down.\n\nKneel.", objectives = "Kneel before the Verdigrease Knight and accept his reprisal.", progress = "Make choice.", completion = "You show great courage today. Be proud." }
WordHunterWoW_QuestEN[79565] = { title = "Janky Candles", description = "With new candle almost ready, now all need is to set up stall! Bring quality candle at good price to people! That Janky guarantee.\n\nOnly problem is not have stall. You talk to Bosh in Gun-dar-ghaz for me? He have everything we need.\n\nMay need barter, but you talk good! Make him give parts.\n\nMeet you down there!", objectives = "Acquire the parts Janky needs to build his stall in Gundargaz.", progress = "Got parts?", completion = "Good talking, <name>. Make great merchant one day.\n\nLike Janky!" }
WordHunterWoW_QuestEN[79573] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[79574] = { title = "The Second Front", description = "Our reinforcements are already inbound. \n\nThese spiders just decided where our next wall will go. Clear a landing zone for General Steelstrike.", objectives = "Signal the landing zone.", completion = "I will NOT risk the nerubians flanking us again. Their ambush is now our staging ground!" }
WordHunterWoW_QuestEN[79575] = { title = "What the Duck?", description = "I cannot work under these conditions! Something has all these silly ducks in an uproar--they nearly upended my precious golden egg!\n\nThese chaotic quackers simply must be dealt with! I can keep them from entering the inn, but will you please help clear out the rest?", objectives = "Scare off 10 ducks using the Horn of Honking.", progress = "Shoo! Shoo! ...have you shooed them all yet?", completion = "Finally, a moment's peace! Thank you, <name>." }
WordHunterWoW_QuestEN[79576] = { title = "A Fowl Concoction", description = "My egg! My precious egg! While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My beautiful golden heirloom was among the items stolen!\n\nEnough is enough. We simply must put an end to this duck invasion.\n\nPlease, {name}. These pilfering poultry must be stopped! Fortunately, I know a mage in Orgrimmar who might just have a solution for us.", objectives = "Speak with Tethris Dewgazer at the Pathfinder's Den in Orgrimmar.", progress = "Have you spoken with Tethris yet?", completion = "Don't worry, I'm sure he'll have a good solution. Wait here, I think I see a portal forming." }
WordHunterWoW_QuestEN[79577] = { title = "Duck Tales", description = "Take this potion, {name}. Drink it, and you should be able to chit chat with those feathery fiends.\n\nOh, but if you happen to experience any... unintended side effects, don't blame me.", objectives = "Use the potion to get information from 5 ducks.", progress = "Have they said anything interesting?", completion = "What? Some of the ducks are druids?\n\nThey won't get away with this!" }
WordHunterWoW_QuestEN[79578] = { title = "Just a Waddle Away", description = "We simply must find out where those ducks are hiding our stolen goods--and my precious egg! Oh, and who this mysterious Daetan is, of course. \n\nI convinced Tethris to give me more of that potion. Take it and bring back my golden heirloom!", objectives = "Discover the duck's hiding spot.", progress = "Where would those ducks be hiding...", completion = "<Sylnaria carefully examines the golden egg.>\n\nUgh! Did a duck gnaw on this? My poor darling, don't you worry--we'll polish you up to a bright shine soon enough!\n\nThank you for your help, <name>." }
WordHunterWoW_QuestEN[79579] = { title = "That Airspace is Mine(d)!", description = "Our advantage is air superiority. The nerubians are threatening that with their mines. \n\nYour mount is more maneuverable than our skiffs. Get in the air and take those mines out.\n\nI will deploy what resources I can to provide you some blessings to improve your capabilities.", objectives = "Fly through 5 nerubian mines while under the effects of Holy Lance.", progress = "Our priests are powerful with the Light but lack the air speed you and your resources can achieve.", completion = "Well done. The right weapon for the right front." }
WordHunterWoW_QuestEN[79580] = { title = "Offensive Counter", description = "I will not yield this ground. \n\nGet out there and kill anything with more than two legs!", objectives = "Slay 12 nerubians.", completion = "Well done." }
WordHunterWoW_QuestEN[79622] = { title = "Warband Test Quest (DNT)", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[79625] = { title = "Not Quite Dead", description = "I am General Anub'azal.\n\nI loathe having little bipeds like you in the Siegehold. However, that is no longer up to me. Zev'kall is pushing me out of my own military stronghold, and collecting overcrawlers to boot! The Queen has deemed him High General, but he is unnatural, warped, and unfit. This will not stand! \n\nI have decided to use you and your kind against Zev'kall. And yes, you will get something out of it.\n\nSearch that rubbish pile there. You will see.", objectives = "Examine the spoils pile in Siegehold.", progress = "Go on, check the pile of rubbish.", completion = "I have plans for the both of you." }
WordHunterWoW_QuestEN[79627] = { title = "Wine and Die", description = "I can see it now, morsel. The pattern of our newest weave is laid bare before my mind.\n\nMeesk is well-guarded. He believes himself to be safe. That is where his weakness lies.\n\nGo to the city. Procure a bottle of his favorite drink and present it to him as a gift from your benefactor. Once he is sufficiently wooed by your affable charms, bring him to the High Hollows for his well-earned reward.\n\nI trust you, {name}. And if you lay our threads out properly, I can guarantee you quite the show.", objectives = "Find a way to charm Meesk the Venomtongue.", completion = "I've heard about you, overcrawler... Skittering about in our fair city and causing all sorts of trouble.\n\nI am glad that your superiors have finally recognized the value of having an ally like me in a place like this." }
WordHunterWoW_QuestEN[79628] = { title = "Emissary of the Council", description = "", objectives = "" }
WordHunterWoW_QuestEN[79630] = { title = "Searching the Web", description = "Oh, thank the hollows! You look like someone that can help.\n\n<The nerubian dabs at her many eyes with a silken handkerchief.>\n\nIt's just horrible! Terrible! A tragedy! My husband has gone missing! We were just wedded yesterday! It was such a wonderful ceremony...\n\nBut when we were to retire for the evening, he disappeared.\n\n<She sniffles dramatically.>\n\nPlease, could you find him and bring him home to me?", objectives = "Locate Arax'ne's husband, Klaskin in the Umbral Bazaar.", progress = "Please, I need help!", completion = "Please help get me home!" }
WordHunterWoW_QuestEN[79631] = { title = "Klaskin's Great Escape", description = "Silken threads, I'm saved!\n\nIt's incredibly important that I make it back home without my wife seeing me.\n\nI took off after our wedding last night, and if she sees me, she's going to kill me! If the guards catch me, they'll surely alert Arax'ne.\n\nWill you help me avoid the guards and get back home?", objectives = "Return Klaskin to Arax'ne in the Umbral Bazaar.", progress = "Please hurry!", completion = "Wonderful! Klaskin, you are such a treat." }
WordHunterWoW_QuestEN[79633] = { title = "The Weaver's Legacy", description = "Oh, this is exciting! A meeting with someone who commands even overcrawlers to do their bidding. I have been waiting for a moment like this.\n\nAh, I won't have to go too far though, will I? I am meant to host some up-and-coming Sureki socialites for dinner later tonight.", objectives = "Bring Meesk the Venomtongue to meet the Weaver.", completion = "Make no mistake, <name>. I care nothing for Meesk's gratuitous proclivities. They were a convenient means of destroying him, but I am in no position to cast aspersions on matters of fickle morality.\n\nWe all scuttle about in the dark in search of that which gives us satisfaction. Meesk invoked Neferess' name for his own gain, and he put one of my weave-rats in danger. For that, he needed to suffer." }
WordHunterWoW_QuestEN[79634] = { title = "DO NOT USE - Renowned with The Assembly of the Deeps", description = "", objectives = "" }
WordHunterWoW_QuestEN[79636] = { title = "Emissary of the Assembly", description = "", objectives = "" }
WordHunterWoW_QuestEN[79641] = { title = "Wipe Away Their Smiles", description = "The kobyss grow bold if they feel they can defile our Veneration Grounds. I think we should collect their teeth to wipe the smiles off their faces.\n\nCome! My brother and I will cleanse our lands from this filth. Try to keep up!", objectives = "Collect kobyss teeth from slain kobyss.", progress = "Let's see them smile now!", completion = "A job well done, I think.\n\nAnd you managed to keep up!" }
WordHunterWoW_QuestEN[79642] = { title = "Stave Them Off", description = "Without their magical weapons, the kobyss casters won't be able to use their foul necromancy.\n\nSteal their staves so we might toss them into the Sacred Flame and be done with them.", objectives = "Collect 5 Darkwater staves.", progress = "Did you find any Darkwater Staves?", completion = "Good job!" }
WordHunterWoW_QuestEN[79643] = { title = "Dreaded Dreadfang", description = "My brother and I have dealt heavy blows to the kobyss, {name}, but you could have done more. \n\nThe most foul kobyss of them all has yet to taste my blade. If we take out their leader, the rest will flee back into the waters from which they came.\n\nLet's take the head of Dreadfang!", objectives = "Kill Dreadfang the Merciless.", progress = "Ready to kill some kobyss?", completion = "No, please! Get up! ... Theleon..." }
WordHunterWoW_QuestEN[79644] = { title = "Go to the Priory", description = "I... I do not have the words. Theleon...\n\nI will take h-his body. They will know what to do at the priory.\n\nOh, brother... It was not supposed to end like this...", objectives = "Meet Sister Etna Blayze at the Priory of the Sacred Flame.", completion = "So young to have been taken from us. So brave and bold. Perhaps too bold." }
WordHunterWoW_QuestEN[79645] = { title = "Sweet-Sting Infestation", description = "Poor Theleon. I gave him some of his first lessons in combat. I'll see him to his final pyre.\n\nBut first, you. \n\nI've been trying to fight back an infestation of sweet-stings harassing our wine-making operations. I need someone else to finish them off while I tend to Theleon's remains.\n\nBe fast and clever and bring me some of their venom as you take care of things. We'll turn that into a poison for the nesting sites and be done with the nuisance.", objectives = "Collect 10 vials of Wasp Venom.", progress = "Did you kill those things?", completion = "Good job! You hardly look stung." }
WordHunterWoW_QuestEN[79646] = { title = "Memorial Wine", description = "Oh, Theleon. He always did follow his big brother into anything. \n\nWhile we prepare Theleon for his final rest, would you please help Brother Abealard with a batch of Memorial Wine for the service?", objectives = "Make Memorial Wine with Brother Abealard.", progress = "Did you help Brother Abealard?", completion = "Such a shame we need to make so much of this wine." }
WordHunterWoW_QuestEN[79647] = { title = "Burning Reflections", description = "Sybaestan could use your support now. His little brother was his best friend. Only death could separate them... and it has. He is not taking it well.\n\nIt is customary to burn written memories of the deceased. By committing them to the flames, we let go our heartache and let the warmth of memory heal us. It is a bittersweet time. You were with Theleon at the end, too. That might help Sybaestan.", objectives = "Help Sybaestan mourn his brother.", progress = "The ritual helps ease the hearts of many.", completion = "It worries me Sybaestan's still in such anger over his grief." }
WordHunterWoW_QuestEN[79648] = { title = "Missing Somebody", description = "Theleon was a good one, but now we must commit his body to the Flames.\n\nSybaestan is in no shape to bear his brother. Would you collect his remains from among those others awaiting their final rest?", objectives = "Collect Theleon's remains.", progress = "You're strong and you have the distance Sybaestan lacks right now.", completion = "Gone? All the bodies are gone?!" }
WordHunterWoW_QuestEN[79649] = { title = "Sacred Flame Inquisition", description = "All the dead are missing? How can that be? They were all laid out in preparation for their pyres. Who would want to move them? Someone must have seen something.\n\nGo ask anyone in the area who might have seen something and I'll go talk to some of the upper clergy. We'll get to the bottom of this and return our dead so they can be properly tended to.", objectives = "Interrogate the local clergy.", progress = "Did you find anything out?", completion = "They attacked you? And said the Prioress is involved? That does not bode well." }
WordHunterWoW_QuestEN[79650] = { title = "Priory of the Sacred Flame: A Brother's Grief", description = "I fear that the Prioress may be behind our missing dead-- and our missing baron. Sybaestan has disappeared as well and I don't believe in coincidences. \n\nShe and Sybaestan have taken our recent losses hard. I fear what their overwhelming grief might be doing to their souls. We must confront them and bring them back to sanity... If we can.\n\nTell General Steelstrike what you have learned. We might need her backup. I'll be waiting for you here.", objectives = "Confront Prioress Haelsey Murrpray inside the Priory of the Sacred Flame.", progress = "We must confront the prioress.", completion = "I wish it could have happened some other way... but at last they are all at peace." }
WordHunterWoW_QuestEN[79651] = { title = "Trade Partners", description = "Have you visited Mmarl? It's a trade town to the southeast of here. \n\nTry some of Corby's barbeque while you're over there!", objectives = "Check out Mmarl.", completion = "Hey there <name>! Thanks for catchin' up with me." }
WordHunterWoW_QuestEN[79655] = { title = "Hallowfall Arathi", description = "", objectives = "" }
WordHunterWoW_QuestEN[79659] = { title = "The Severed Threads", description = "", objectives = "" }
WordHunterWoW_QuestEN[79661] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[79662] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[79663] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[79667] = { title = "It's Elementary", description = "", objectives = "" }
WordHunterWoW_QuestEN[79669] = { title = "I Take Candle!", description = "", objectives = "" }
WordHunterWoW_QuestEN[79679] = { title = "Muddled Mind in the Mine", description = "The workers said they saw Munderut near the back of the mining area. Please find him and tell him that I said he needs to report back in. \n\nHe might not remember me, or that I am his fused. Tell him to look down at his chest, at the medallion he wears. His memory of our time together fades in and out these days, but the medallion tells of our story and bond forever.", objectives = "Look for Munderut in Nibelgaz Mine.", completion = "Who are you? What are you doing here? \n\nActually, what was I doing here? Gathering spines, I suppose. I got distracted by all the elementals. They have made this area quite dangerous. I'm more of an artist than a fighter." }
WordHunterWoW_QuestEN[79680] = { title = "Pipe Patching", description = "Earthquake do number on old pipes. Many start leaking steam everywhere. Especially ones too tall to reach.\n\n<Fourman Grimes points up to the pipes stretching from Gundargaz to the surface.>\n\nStoneheads not have \"approved replacements,\" but we not have time wait.\n\nTake glue and seal leaks with flappy-flying thing. Made of only best bugs, boiled myself. Will do for today.", objectives = "Fly near the leaks in steam pipes above Gundargaz to seal them with kobold-provided glue.", progress = "Try not glue self to pipe, yes?", completion = "See? Not need wait. Need action.\n\nYou understand." }
WordHunterWoW_QuestEN[79681] = { title = "Plumber Power", description = "Not all leaky pipes accessible from outside. Some inside tunnels run all under Gundargaz.\n\nTunnels small for stoneheads, but kobolds love tunnel! Just need someone to show layout. You, someone.\n\nCheck with crew boss if have problems. He help go over maps.", objectives = "Use the Tunnel Access to plot the steam pipe routes through Gundargaz.", progress = "Get lost?", completion = "Job good. On to next." }
WordHunterWoW_QuestEN[79682] = { title = "Critical Pressure!", description = "Pressure still too high! Something else wrong, not just old pipes.\n\nOpen main release before something burst. Not have time for manuals.\n\nConsequences for deal with later!", objectives = "Open the main release valve and deal with whatever happens.", progress = "Find problem?", completion = "Always something, <name>. Maybe old pipes behave now, yes?" }
WordHunterWoW_QuestEN[79683] = { title = "Home Is Where the Candle Is", description = "Exciting to have new place call home, {name}.\n\nNot quite settled, though. We not know Gundargaz. Gundargaz not know us.\n\nTime to fix both! Find out how help here. Teach new friends about us. Kobolds clever and friendly, so should be easy!\n\nStart with help three kobolds.\n\nFourman Grimes want get to work right away. She very task oriented.\n\nGranny Scribbles tell you lot about kobold culture.\n\nAnd Janky want set up new business in town, sell candle to Gundargaz.", objectives = "Assist Fourman Grimes, Janky, and Granny Scribbles.", completion = "Thank you, <name>. Have new home because you. Have future." }
WordHunterWoW_QuestEN[79686] = { title = "Concerning Fungarians", description = "<Abandoned in the dim candlelit chamber, the parchment, wrinkled and worn, bears the traces of hastily scribbled research notes.>\n\nLog Entry: 235-18-7\nDate: Fabrication Quarter Cycle\n\nObservation: Fungarians exhibit accelerated growth and increased territorial aggression. Spore dispersal seems to have quadrupled compared to previous recorded rates.", objectives = "Collect the remaining research notes and return them to their owner in the Freywold Village.", progress = "Did you find something interesting?", completion = "My notes! I was worried my research was lost forever!" }
WordHunterWoW_QuestEN[79691] = { title = "Monsters in the Dark", description = "The local quarry was an active source of clay and ore for us until the fungarians took over some time ago.\n\nWe were worried about the fungarians encroaching upon the village, but there's something more.\n\nMultiple sightings of a creature much larger than our native wildlife have been reported at night.\n\nCombined with villager Modhina's disappearance, I fear this is no coincidence. She visited the quarry recently and hasn't returned.\n\nWe would be in your debt if you searched the tunnels.", objectives = "Slay the Ashen Stonestalker in Gemvein Tunnels.", progress = "You do us a great service by making our lands safe.", completion = "A stonestalker, here? Their habitat resides far beneath the isle's surface. All the recent change must be disturbing them.\n\nRegardless, thank you for slaying it. They are highly territorial and kill for sport.\n\nAs for the tunnels, the area sounds beyond recovery. We'll have to let nature reclaim it." }
WordHunterWoW_QuestEN[79692] = { title = "Buried, Not Forgotten", description = "Several suns ago, my friend Modhina ventured into the quarry cave. She wanted to find rare ore for Hreka, to help her craftsmanship. Modhina was excited, I remember. A rare feeling for earthen.\n\nShe hasn't returned. The fungarians prevent us from searching the area.\n\nIt would mean a great deal to us if you could look for her. I didn't know it was possible to spend so much of the day thinking about what if's.", objectives = "Find Modhina and her belongings in Gemvein Tunnels.", progress = "Be careful. I fear more sinister things lurk in these tunnels.", completion = "You've returned! Did you find Modhina...? What is all that you are carrying?" }
WordHunterWoW_QuestEN[79693] = { title = "Play Hearthstone!", description = "It's time to play Hearthstone! \n\nHere's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play!\n\nOr if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", objectives = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table.", progress = "Like the game so far? Give it a chance and play those cards!", completion = "How did you do? Had some good, clean fun I'm sure!" }
WordHunterWoW_QuestEN[79694] = { title = "Play Hearthstone!", description = "It's time to play Hearthstone! \n\nHere's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play!\n\nOr if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", objectives = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table.", progress = "Like the game so far? Give it a chance and play those cards!", completion = "How did you do? Had some good, clean fun I'm sure!" }
WordHunterWoW_QuestEN[79701] = { title = "The Cavalry is Here", description = "<Baelgrim quakes with fury.>\n\nThese cursed nerubians. Attacking a triage site! So many wounded and defenseless... and yet, it looks like you outlanders are putting up a fight!\n\nLet's grind every last one of the bugs back into the ground.", objectives = "Repel the nerubian attack at the Proscenium.", completion = "<Baelgrim is covered head to toe in nerubian ichor and blood.>\n\nGood work, <name>. Good, gruesome work." }
WordHunterWoW_QuestEN[79703] = { title = "Hope, An Anomaly", description = "<Hreka looks through the things you retrieved, one by one.>\n\nSo you risked your life to find our friend.\n\nModhina is gone, then. Her notes are about the rare ore from the cave. Melted down, it becomes a beautiful glaze for pottery.\n\nWhat can I do? I'm no fighter. I can't avenge her. Besides, her body has already been reclaimed by the earth. That much is certain by the state of her memory gem fragment.\n\nWhat can I do now, but make a pot? Will you help me?", objectives = "Make a piece of pottery with Hreka.", progress = "A lifetime spent making pottery. Is this my titan given fate? Then why do I still wonder?", completion = "Almost done. It needs a bit of time in the fire to set." }
WordHunterWoW_QuestEN[79710] = { title = "A Fin of Every Kind", description = "Oh! My! LEGS!\n\nYou're perfect! Yes! You're a perfect, little, unassuming biped for my work.\n\nAlchemy is my trade, and an alchemist is only as good as their ingredients. See these kobyss below? I've been camped out here for weeks observing them.\n\nThey seem tougher than average kobyss. My conclusion? They must be made of stronger stuff! And I want that stuff! \n\nHere's a sack. Fill it up! Fill it up with their innards! As much as you can carry!", objectives = "Fill up the Kobyss Innards Sack.", progress = "Is that really as much as you can carry?", completion = "Brilliant! Fabulous!\n\nA sack brimming with promise, date, and... arterial goop." }
WordHunterWoW_QuestEN[79711] = { title = "That's Pretty Gross", description = "<You dislodge a familiar-looking appendage from the silt.\n\nIt doesn't seem particularly kobyss, but perhaps a unique specimen will earn you an increased reward from Al'kubian.>", objectives = "Bring the Familiar-Looking Appendage back to Al'kubian.", progress = "Ooooh! What is this?", completion = "You are what you eat.\n\nAnd these kobyss are eating the strongest nerubians ever to Ascend. \n\nDon't mind the marks of moisture on the ground... That's my anxiety sweat." }
WordHunterWoW_QuestEN[79713] = { title = "Moonlight Gutter Swim", description = "An Ascended's leg...\n\nA kobyss tribe feasting one or two dozen trueborns or skitterlings, perhaps even a sageform such as myself... But an Ascended is a different story.\n\nLet us approach this as intellectuals, and use the tools at our disposal to collect more data. What tools do we have? You. You are the tool. An intellectual tool of kobyss disposal.\n\nDive into the lake's depths. Slay the largest of these creatures or their pets.\n\nAnd of course, bring me their innards.", objectives = "Collect Liverseeker's Intestines and Leg Chewer's Stomach.", progress = "Any profits I gain from my work goes directly to scientific and alchemical research.\n\nAs in, I use the profits for myself, and I am an alchemical scientist.", completion = "Ah, I must apologize. I realized I yet had another spare innards sack. It only dawned on me once you were away...\n\nThat aside--Well done. Good job. Impressive labors. So on, so on." }
WordHunterWoW_QuestEN[79714] = { title = "Rescuing the Food", description = "While awaiting your innards-bestowing return, I observed some fascinating activity below. A consistent train of kobyss are dragging the limp bodies of my kin from the lake's waters and westerly into their cavern.\n\nMy conclusion? Nerubians are being hunted and stored in the lake for consumption by these beasts.\n\nIt's not so much for research than it is for civic duty, but I would reward you might be able to save from their fate.", objectives = "Rescue 5 Captive Kaheti.", completion = "Your efforts are appreciated, but I will be rewarding these civic tasks at a... slightly lesser pay tier than your scientific ones.\n\nBlame my stipend." }
WordHunterWoW_QuestEN[79715] = { title = "Grand, Gutsy Solutions", description = "I require one final piece of data.\n\nThese beasts think. They organize. They coordinate. To be characteristically honest, there's nothing worse than an amphibian with an abacus.\n\nMy final task for you: Bring me the brain of the biggest beast. I need it fresh, and preferably non-liquified.\n\nAnd, you know, perhaps it will slow them down as well.", objectives = "Collect the Brain of Grand Gluttony.", progress = "Have you got it? Is it leaking?", completion = "Fabulous! Absolutely fabulous!\n\nUnrelated, the samples you've brought back are disgusting. I'm utterly appalled that you were willing to go without a sack again for the latter portion of our work together.\n\nYou should really wash your hands." }
WordHunterWoW_QuestEN[79716] = { title = "The History Beneath Us", description = "The titan console is a huge find. And look at these ruins! There has tae be more here!\n\nBut goin' out into the site is dangerous. Accordin' to Brinthe, now that the titan vault has been unearthed, elementals have come.\n\nElementals dunnae like order magic, an' titan relics just ooze the stuff. They're on a rampage!\n\nCan ye go out there an' get some relics back from the elementals? We need tae preserve what we can!", objectives = "Collect 20 Shattered Relic Fragments from elementals in Golgrin's Reach.", progress = "Have ye found anythin' yet?", completion = "Look at all these relics! \n\nLook at all this history!\n\nAnd tae think... the elementals were just goin' to destroy it.\n\nI could cry, I could!" }
WordHunterWoW_QuestEN[79717] = { title = "Means of Ingress", description = "Ah, look at you! Just the sort of rogue element I need.\n\nMy name is Ar'syn, and I am something of a connoisseur for the fine arts and histories of our people. It is my intent to enter the Royal Preservatory--that's that large enclave just over there-- and rob it blind.\n\nBut gracious, the guards will never let me get close enough to survey their security! If only I had someone to help me find a somewhat more subtle way into the building.\n\n<Ar'syn looks at you meaningfully.>", objectives = "Survey three potential entryways into the Royal Preservatory.", progress = "Well, what do you think? I think you'll find that even the Preservatory itself is quite the work of art in its own right... Though that does mean it will prove rather vexing to infiltrate.", completion = "Say what you will about our new queen, but she knows how to run a tight ship. They are ferrying their spoils of war into the building at a remarkable rate.\n\nBut then, that may well be your ticket inside." }
WordHunterWoW_QuestEN[79718] = { title = "Skeins Street Irregulars", description = "I would like nothing more than to go in and take a few of these pompous Sureki royalists out. It would make our infiltration that much easier, and it would serve them right for trampling upon our history. But I cannot get close without bringing a whole host of guards down upon the Skeins.\n\nYou, though? No one will bat an eye at wanton violence if it comes from an overcrawler. Why not get in there and thin them out a bit?\n\nOh, don't give me that look. You were going to do it anyway.", objectives = "Slay Sureki agents around the Royal Preservatory.", progress = "You needn't worry about any moral quandaries here. The craven Sureki would do the same to you thrice over.", completion = "I'll be honest, friend. I find brute force somewhat lacking in artistry.\n\nBut goodness, you make it into a performance piece unto itself! Color me impressed. And a bit intimidated." }
WordHunterWoW_QuestEN[79721] = { title = "Fire in the Hole", description = "Who are you? But of course, another outlander! I'm Wenbrandt, tamer of cinderbees and creator of cinderbrew.\n\n<Wenbrandt squares himself up as if you should be impressed.>\n\nI had brought barrels of cinderbrew to help the injured. I thought drinking it would ease their pain, but for most it just caused more... burning... pain...\n\nI refuse to let my brew go to waste. Maybe it can be weaponized. The nerubians are just bugs after all--organic and flammable.\n\nThis burrow here is a perfect test subject.", objectives = "Use cinderbrew to repel the nerubian attack in the Proscenium.", progress = "Go drop a few on the nerubians. Let's see what happens.", completion = "Mountains fall on me, that was incredible! And to think that we've been drinking the stuff..." }
WordHunterWoW_QuestEN[79722] = { title = "Gutter Work", description = "", objectives = "" }
WordHunterWoW_QuestEN[79723] = { title = "Repatriation by Subtraction", description = "Ansurek and her ilk are so short-sighted. They think that by filling our museum with trophies of their recent conquests instead of relics of our own history, we will be less inclined to remember where we came from.\n\nWell, they are probably right--in the long term, at least. History has a habit of bending towards the voice of its teller.\n\nBut that is where we come in, {name}. Those relics that the Sureki forces stole? It's time to steal them back.", objectives = "Loot six Pillaged Trophies from the Royal Repository.", progress = "Well, <name>? I'm sure the place is filled with a queen's ransom.", completion = "<Ar'syn's many eyes sparkle in the cavelight.>\n\nThough my goals today are on the philanthropic side of things, I must profess my appreciation for a good heist well-executed. Look at all of these treasures! I do so look forward to returning them to their rightful homes.\n\n...For a finder's fee, of course. Imagine if Azj-Kahet's legendary legerdemain became some sort of folk hero?! Ugh, the very word sours on my tongue." }
WordHunterWoW_QuestEN[79724] = { title = "A Titanic Expedition!", description = "Our merchant friend told us about some small islands off the northeast coast called \"The Three Shields.\"\n\nApparently, there was a lot of titan activity there long ago. To me, the \"activity\" sounded like titan research and development. Exciting stuff!\n\nTuberros and I are going there to check it out. Tharessa, my new Algari Expedition trainee, is coming along to see true professionals at work.\n\nCare to join us?", objectives = "Meet Rannan at The Three Shields.", completion = "All right, I'm fine. It's just a scratch. \n\nBut it took the three of us to bring down one little gorloc, so it's good you decided to join us." }
WordHunterWoW_QuestEN[79725] = { title = "Not a Heating Pack", description = "Tharessa has done some reconnaissance for us and found the gorlocs are digging up artifacts and... cuddling with them. \n\nI think it means that the artifacts emit heat? Maybe that means some artifacts are still functioning?\n\nImagine--the titans created technology to shape worlds, and now a fish uses it to warm their fins. Hah!\n\nThe gorlocs won't give them up, and I don't want to be a Rannan-kabob either. I hate to ask because they just want to be warm, but could you do something about them?", objectives = "Rannan wants you to kill 12 gorlocs.", progress = "Did you get them? I thought I saw one sneak by a moment ago...", completion = "Wonderful! Now we can focus our attention on what really matters--the artifacts. I wonder what we will discover?" }
WordHunterWoW_QuestEN[79726] = { title = "\"Cataloguing\"", description = "As ya know, we are here to collect some titan shinies, artifacts, whatever!\n\nAnd Rannan thinks the more shinies--er, you know what I mean--the better chance we have figurin' out something about the titans.\n\nThat'll make Rannan happy, but it'll also ensure I have some extras to take to my store back home.\n\nMy wife, Perisimona, is waiting for 'em back in Loamm. I can't go back empty handed!", objectives = "Recover 7 titan artifacts.", progress = "You get some good shinies yet?", completion = "<Tuberros looks at the titan artifacts.>\n\nThis one smells very acidic--and it's broken. I can take it to the store... Rannan would like to see that one... Oh yeah, these are great. Thank you for bringing them to me." }
WordHunterWoW_QuestEN[79727] = { title = "Because It's Shiny", description = "While these two were ordering you around, I thought I would do something useful and make sure the gorlocs were not going to surprise us here on the beach.\n\nNone of them seemed interested in us, but then I saw one huge gorloc.\n\nIt killed off some smaller gorlocs then took off. It had something glowing in its claw though!\n\nIt had to be an artifact. And it looked like it was working! We've got to get it back.\n\nBy \"we\" I mean \"you.\" Larger-than-average gorlocs are above my Dragonscale pay grade.", objectives = "Retrieve the artifact from the huge gorloc.", progress = "Were you able to get the artifact?", completion = "I can hear it humming from here. Ow. It irritates my ears.\n\nLet's see if our two \"professionals,\" Rannan and Tuberros, know what this artifact is." }
WordHunterWoW_QuestEN[79728] = { title = "It's Probably Nothing", description = "You found a buzz orb! \n\n...Er, that's what the niffen call it. I just kind of went with it. \n\nIt's still in a good condition. Still buzzing, humming, and warm to the touch! I haven't seen one since we were in Zaralek Cavern!\n\n{name}, you should see if we can get it to work. I will stand back here, just in case it is, um, not friendly. \n\nNothing to worry about, I'm sure.", objectives = "Interact with the titan orb.", progress = "Yes, yes! It will be very exciting to hear what you have discovered.", completion = "Alpha site? Defense grid?\n\nI don't like the sound of that.\n\nWe should get going. I don't want to be here if its friends come back with it.\n\nThat's not a reunion party I want to be a part of.\n\nHopefully it won't hone in on Tharessa... Nah, probably not. Anyway, we should get going. Like now.\n\nCatch you later, <name>. Thanks for your... um, help? I guess?" }
WordHunterWoW_QuestEN[79729] = { title = "Educate Yourself", description = "The Relics of Founding have always been the centerpieces of the Preservatory's collection. Together, those four artifacts tell our most reverent tale--that of the founding of Azj-Kahet, and of our people's rejection of our Old Masters.\n\nWith luck, they will still be inside the Preservatory. Once you are inside, I want you to tamper with the shadecasters in front of each of the relics. Make sure that their messages are heard by anyone nearby--whether they wish to listen or not.", objectives = "Tamper with the shadecasters in front of each of the four Founding Relics.", completion = "And there we have it. A brilliant calling card to suit our schemes, and an excellent distraction to cover our escape. All in one convenient, educational package!\n\n...Would that it were all good news, however. Our exit strategy has grown complicated." }
WordHunterWoW_QuestEN[79730] = { title = "Dogged Pursuit", description = "But of course, simply stealing the relics isn't enough. We need to teach the Queen's pet burrow-worms a lesson in futility, or they will simply start the whole process again!\n\nThat shouting buffoon near the central passage is Rez'kal, a member of Ansurek's personal academic entourage. He's... not very bright, but he makes up for it with enough strength to send either of us through a wall.\n\nI'm not inclined to go toe to toe with the big oaf today. Would you mind overmuch doing one last favor for me?", objectives = "Defeat Royal Broker Rez'kal.", progress = "Be careful, <name>. What Rez'kal lacks in acuity he makes up for in scarab-headed stubbornness.", completion = "Ah! There you are. Fine job back there with the lummox. He may have been a buffoon, but he was a buffoon with very sharp blades on his arms.\n\nNow, with relics in hand, it is time for me to make my grand exit. I've a great many pilfered riches to re-appropriate, after all! I've truly enjoyed our time working together, though. Perhaps, with luck, our paths will cross again soon." }
WordHunterWoW_QuestEN[79944] = { title = "Raging Rifts", description = "The elementals are coming from inside that cave. We only made it part of the way in before needing to retreat. \n\nI could see some flickering within, some strange glowing thing that looked almost like a tear in space from which the elementals poured forth! We managed to close one of these portals, but there are more.\n\nI need to stay with Nanthaz. It is up to you now, if you can manage. Destroy the rifts and find their source. I suspect it lies deeper within the cave.", objectives = "Destroy 4 rifts and find their source within the cave.", progress = "Destroy what rifts you come across, but above all, find their source! I suspect you will find it deep inside the nearby cave.\n\nThe miners you rescued spoke of breaking through to a crystal-filled room, and of the elementals pouring forth from within.", completion = "You return with good news, I hope? \n\n<You tell her about Urthgrafr Riftcaller.>\n\nWith Urthgrafr's defeat, we should have no problem cleaning up the rest of the elementals and rifts ourselves. We are lucky that you came along when you did.\n\nThank you for your help, friend. Do not worry about me or Nanthaz. We will make our way back to the refinery once he has caught his breath. Gratitude, outlander. And may all earthen Awaken one day." }
WordHunterWoW_QuestEN[79954] = { title = "Spiders!", description = "Why, hello there, little {race}. You seem like you might be able to assist me.\n\nYou see, my dear mate Ami'thax fell onto a sharp dagger. Her body was taken to Pillar-nest Xesh, just below where we stand. Xesh is used to dispose of all sorts of bodies that we never speak of again.\n\nUnfortunately I have need to speak of Ami'thax, because she had the key to my new High Hollows burrow on her when she died. Dreadful timing, really. Would you go and fetch it? \n\nDo beware of the spiders, I need my key.", objectives = "Find Ag'thax's missing key in Pillar-nest Xesh.", progress = "Don't let the spiders eat you before you escape with my key.", completion = "I don't want to hear about where you found it, I have no need for the details.\n\nI am very excited to move into my High Hollows burrow!" }
WordHunterWoW_QuestEN[79955] = { title = "...And Now I'm Arachnophobic", description = "Who is there? Someone? Did I imagine you?\n\nI am Albert. I was a Pathfinder once. Now that I'm blind, I see no path. It seems wrong to call myself Pathfinder Henson. I can hear, though. I can hear them eating. They eat the fresh parts.\n\nMy eyes. My insides.\n\nIt hurts all the time. They do not want my rotten pieces. The decayed parts are all I have left. The worst of me. \n\nI wasn't alone here, I had fellow Pathfinders. I keep hearing sobbing from the walls. Do you hear them too?", objectives = "Locate Albert's friends in the walls.", completion = "They are dead, then..." }
WordHunterWoW_QuestEN[79956] = { title = "Legs in the Ceiling", description = "I don't require vengeance on my behalf, but I would like vengeance for all of my friends that were eaten. I didn't think the Horror of Xesh was real, but she is. Xishirra. A shadow of a nightmare, making a brood of monsters while she stays out of reach.\n\nThe horror is ancient, and beyond us, but we can still make her pay! Pull hard on a web strand if you need to, and deal with whatever comes. We'll escape after some justice is had!", objectives = "Pull on the spider thread if the spiders are not already attacking, and kill whatever comes.", completion = "<Albert's eyes were already dark, but any spark of life has faded from the rest of him, as well.>" }
WordHunterWoW_QuestEN[79957] = { title = "Maggots in your Eyes", description = "<Albert is no longer alive. All that remains is his head, still full of maggots.\n\nTaking him back to the Pathfinders seems like the right thing to do.>", objectives = "Take Albert's head to the Pathfinders in Faerin's Advance.", progress = "Whose head is that?", completion = "This eyeless, mostly eaten, maggot-infested head is...\n\nAlbert! Oh no, what happened?!\n\nWe didn't know where his team had gone, just that they'd taken a mission near the city.  I can't imagine the trauma he endured, or what you had to do to bring his remains to us. We'll take it from here. Thank you for bringing him back.\n\nAnd I hope the nightmares that could come from this don't linger for you, friend." }
WordHunterWoW_QuestEN[79958] = { title = "Worm Sign, Sealed, Delivered", description = "", objectives = "" }
WordHunterWoW_QuestEN[79959] = { title = "Wormcraft Rumble", description = "", objectives = "" }
WordHunterWoW_QuestEN[79960] = { title = "Taking it To Go", description = "", objectives = "" }
WordHunterWoW_QuestEN[79965] = { title = "Learn the Ropes or Walk the Plank", description = "", objectives = "" }
WordHunterWoW_QuestEN[79966] = { title = "Test Quest", description = "Test", objectives = "Test" }
WordHunterWoW_QuestEN[79989] = { title = "An Ancient Awakening", description = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks.\n\nThat amount of unstable energy being released could be catastrophic. \n\nShall we continue?", objectives = "Empower the Waygate.", completion = "Now that we, and by we I mean you, have figured out what these things are fer there's no tellin' how many more are out there!\n\nKeep yer eyes open, <name>. No tellin' what we might find around the Isles." }
WordHunterWoW_QuestEN[79998] = { title = "Mite Not Right", description = "This not good. Fancy fire bees have mites!\n\nJanky seen this before. Hive get infested, good bugs get sucked dry. End bad. Need do something!\n\nBlast bees with smoke. Makes bees sleepy but mites hate!\n\nWhen jump off, you squish before they bite bees again.", objectives = "Cleanse fire bees of their infestation with Janky's scented smoke and kill the offending mites.", progress = "Many mites left?", completion = "Only good mite, dead mite. Good job." }
WordHunterWoW_QuestEN[79999] = { title = "Igniting Hope", description = "One dawntower has fallen, but a faint glimmer of hope remains with the smaller keyflame atop the wall. \n\nThe shattered remnants needed to sustain that light were taken by the nerubians.\n\nGather the remnants from nerubians you slay, and help ignite a beacon of hope!", objectives = "Gather 5 Shattered Remnants and use them to empower the Aegis keyflame.", progress = "An empowered keyflame will be a great help.", completion = "With the light of the flame I see hope that we will drive the nerubians back!" }
WordHunterWoW_QuestEN[80000] = { title = "Beebiter", description = "Mites kill fire bees. No good!\n\nJanky hate mites. Bite you when not even stealing wax. Not even make wax!\n\nGive bees chance. Kill biggest, bite-iest mite before eats more bees.", objectives = "Slay Beebiter.", progress = "How feel about being on fire? Good?", completion = "Fire bees safe now. Be here when come back later for more wax." }
WordHunterWoW_QuestEN[80004] = { title = "Crab Grab", description = "<The arrival of the kobyss has kept the Arathi from working these shores. Delivering a cage full of fresh crabs could aid citizens in need of food.>", objectives = "Collect 12 Shadowtide crabs from the waters off the Faded Shore.", completion = "Thank you <name>, this is an unexpected surprise!" }
WordHunterWoW_QuestEN[80005] = { title = "Crab Grab - Activate", description = "", objectives = "" }
WordHunterWoW_QuestEN[80012] = { title = "Skyriding", description = "This land is more vast than I remember. However, a good scholar always prepares for contingencies.\n\nTwo of the most airborne dragons have agreed to aid our cause. They will provide a winged mount so you may cover more ground.\n\nI will send you to Lord Andestrasz. He shall instruct you further.", objectives = "Take Moratari's portal to Lord Andestrasz.", progress = "All things come with practice.", completion = "Let us get started.\n\nDo not worry, the fancy maneuvers will come later." }
WordHunterWoW_QuestEN[80013] = { title = "How to Glide with Your Dragon", description = "Let us start with the basics.\n\nIf you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding.\n\nFirst, call upon your drake, or our Red Drake friend here can give you a lift.\n\nThen, fly through the rings and land at the target location.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Summon your dragonriding mount, or mount the Red Drake. Then glide through the rings and land in the target area.", progress = "Well done, <name>.", completion = "Excellent work!" }
WordHunterWoW_QuestEN[80015] = { title = "How to Dive with Your Dragon", description = "Gliding will get you to where you want to go. But what if you want to get there faster?\n\nDiving after jumping from somewhere high will give you a speed boost. As long as you fly well, you can conserve your momentum and gain some height after a dive.\n\nFly through the rings to the target location.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Dive then glide through the rings and land in the target area.", progress = "Well done, <name>.", completion = "See? That was much better.\n\nIf you start your flights with a dive you will get to where you want to go so much faster." }
WordHunterWoW_QuestEN[80016] = { title = "The Need For Higher Velocities", description = "Sometimes you'll need to travel longer distances.\n\nIf you don't need to travel up and over any obstacles, using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky.\n\nFollow the rings again to your destination and use Surge Forward when prompted to maintain your speed.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Fly through the rings and land in the target area.", progress = "Well done, <name>.", completion = "Well done. The rest is now a matter of practice." }
WordHunterWoW_QuestEN[80017] = { title = "The Need For Higher Altitudes", description = "To gain height, use Skyward Ascent.\n\nFollow the rings again to your destination, using Skyward Ascent when you need upward momentum.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Fly through the rings and land in the target area.", progress = "Well done, <name>.", completion = "Ever upward you shall go." }
WordHunterWoW_QuestEN[80018] = { title = "Fashionable Flying", description = "You have learned all I can teach you.\n\nBut flying isn't just about getting to your destination--it's about getting there in style!\n\nUse the Rostrum of Transformation behind you to customize your drake's appearance.", objectives = "Use the Rostrum of Transformation.", progress = "How do you like your look?", completion = "Now you are ready to fly.\n\nOff you go, best of luck on your journey!" }
WordHunterWoW_QuestEN[80022] = { title = "Calling the Stormriders", description = "I know the Unbound can repair and unblock the Coreway expediently--but I also know the nerubians. If they see an opportunity for an ambush, they will take it.\n\nWith our backs turned and our focus on the Coreway, we are prime targets.\n\nI need to rally my Stormriders and form a perimeter around Dornogal in case of an attack from within or from without.\n\nMeet me outside of the Stormperch. I will call upon my troops there.", objectives = "Meet Baelgrim outside the Stormperch, then speak with him to follow him into The Rookery.\n\nThis challenge may be completed solo or with up to 3 party members.", progress = "Baelgrim is right. We need to defend the Unbound while they work on the Coreway.", completion = "The entire Rookery?\n\nI see.\n\nAt least the source is destroyed. I lament the loss of so many Stormriders but...\n\nIf the corruption had spread to Dornogal..." }
WordHunterWoW_QuestEN[80023] = { title = "Cloning Conundrum [DNT]", description = "My twin Miner Mobbi has somehow found a way to clone me accidentally. \n\nAnd they are taking over the mine! Please help!", objectives = "Kill 1 cloned Blacksmith Bobbi in the Opalcreg mine." }
WordHunterWoW_QuestEN[80049] = { title = "The Flame Still Burns", description = "That was too close.\n\nThis attack took a toll on all of us. We have many injured, and many shaken. \n\nCan you check in with people? See how they are doing?", objectives = "Check in with Arathi Survivors in the Veneration Grounds in Hallowfall.", progress = "How's it looking out there?", completion = "The Arathi spirit can never be broken!" }
WordHunterWoW_QuestEN[80058] = { title = "Kobold Kleanup", description = "New home little shabby. Not good, full of fun stuff and good bits shabby. Old, everybody died and now it fall apart shabby.\n\nWe help! Lots of kobolds, now, so we make place presentable for stonehead friends. Make feel like home.\n\nYou help, too. Grab broom, get going!", objectives = "Clean up Gundargaz.", progress = "How go?", completion = "Much better. Lizards tasty, but not want running all over nice rugs." }
WordHunterWoW_QuestEN[80062] = { title = "Basic Kill Quest [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[80069] = { title = "Tears of Teldrassil", description = "I have carried this weight long enough. It has finally come time to put my family to rest. Even if I never found my sister...\n\n<Kelestra wipes away tears and takes a deep breath.>\n\nI must gather barrowstones to place at their final resting place. But I simply cannot carry that many stones.\n\nMaybe I ask too much of a stranger, but would you assist me? I know having someone beside me will make this more endurable.", objectives = "Follow Kelestra and collect barrowstones to help her memorialize her family.", progress = "<Kelestra looks distraught, and her hands are shaking.>\n\nI can not parse my feelings. My sister is alive, but a traitor.\n\nAnd what did he mean she deserved her fate?\n\nPlease Koroleth, let this finally be our time to reunite.", completion = "<Kelestra takes a deep breath and tries to calm herself.>\n \nKoroleth... what have you done? Why? I must find out why!" }
WordHunterWoW_QuestEN[80071] = { title = "Fact Finding", description = "I must speak with the Primalists. I don't understand why she would turn her back on us.\n \nKoroleth saved my life at Teldrassil. I owe it to her to find out the truth.\n \n{name}, I realize this might be awkward, but will you help me? I can no longer bear this alone.", objectives = "Meet Kelestra at the Twilight Watchtower.", completion = "Thank you for coming <name>." }
WordHunterWoW_QuestEN[80072] = { title = "A Primalist Point of View", description = "Warden Malathra has granted us permission to speak with the Primalists. They might have switched sides, but the wardens are keeping a close eye on them.\n \n<Kelestra begins to look distressed.>\n \nI'm going to talk to the Warden more. Could you handle the Primalists? All of this about Koroleth is just happening so suddenly. I feel we should gather as much information as we can.", objectives = "Speak to the reformed Primalists about Koroleth.", progress = "I want to talk to them, but I don't even know where to begin.", completion = "What were you able to find out?\n \n<Kelestra listens as you explain what you learned.>\n \nI can understand why my sister would want nothing more than the Horde destroyed. I and many others felt the same way for a time. And Koroleth always had a single-minded focus in getting what she wanted.\n \nBut I also believe that had she known about Amirdrassil, she would have defected immediately." }
WordHunterWoW_QuestEN[80073] = { title = "Bones of a Bygone Battle", description = "After speaking with the warden, I learned the Battle of the Barrier where my sister fell took place east of here, on the shores of the Ohn'ahran Plains. \n \nI understand her body was washed out to sea and never recovered.\n \nIt's possible the tide brought her remains back to shore at some point. Will you help me look for her? \n\nEach member of my family has a necklace with this distinct design. It will identify Koroleth's body.\n\nI would like to lay her to rest with the family she loved.", objectives = "Search the shoreline of the Ancient Bough for Koroleth's remains.", progress = "Is this the necklace you found?", completion = "Oh Koroleth...\n \n<Kelestra looks at the remains and weeps softly.>" }
WordHunterWoW_QuestEN[80075] = { title = "A Barrow Den Burial", description = "All that is left to do is to gather my sister's remains and bring them to the barrow den. \n \nPlease meet me there, {name}. I could use a friend.", objectives = "Meet Kelestra outside the barrow den at the Fields of Reverie.", completion = "<Kelestra is on the verge of tears.>\n\nThey refuse to let me in. After all we have done. They deny my sister peace!" }
WordHunterWoW_QuestEN[80077] = { title = "Sins of the Sister", description = "This druid is trying to convince Malfurion not to let me bury my sister here with the rest of my family. He won't even let me get a word in.\n \n<Kelestra tightly clutches the straps of her backpack holding her sister's remains.>\n \nI know I have asked a lot of you already. Could you talk to them? Perhaps they might listen to you?", objectives = "Speak with Malfurion Stormrage about Koroleth's remains.", progress = "<Malfurion is deep in thought.>", completion = "That was no easy decision to make. But I believe it was the correct one.\n \nThank you for assisting Kelestra in this matter. Despite the circumstances, let us hope that finding her sister may give her some measure of closure." }
WordHunterWoW_QuestEN[80079] = { title = "A Wrench in the Works", description = "Looks like the High Speaker is addressing his workers.  It seems something has finally shaken them from their complacency, and their time away from the Awakening Machine is affecting them.\n\n<Moira pauses to brush a bit of dust off her robe.>\n\nPerhaps this would be a good opportunity for everyone to hear what they have to say?\n\nWe should convince a few of these Machine Speakers to speak up.", objectives = "Encourage members of the crowd to air their grievances.", progress = "Recalcitrant lot, aren't they?", completion = "Excellent, now we're starting to make some progress." }
WordHunterWoW_QuestEN[80081] = { title = "Captain's Orders: Flood and Plunder", description = "", objectives = "" }
WordHunterWoW_QuestEN[80082] = { title = "Back to Gundargaz", description = "We may not have overthrown the Candle King, but our work here has surely relieved some of the pressure facing Gundargaz. And it's made us more than a few new allies, as well.\n\nOur new friends will not be forgotten, on my word as Speaker. There is a...regrettable amount of available housing in Gundargaz as of late. It will be nice to feel the city come to life again, and we can certainly use the manpower.\n\nShall we bring them home, {name}?", objectives = "Return to Gundargaz.", completion = "I'm glad to be back, but this gathering is... troubling.\n\nLooks like discontent is growing." }
WordHunterWoW_QuestEN[80096] = { title = "The Shovel in the Stone", description = "Now, friend, we quest for blade of legend! Whoever pull from stone it stuck in destined for greatness.\n\nOnly problem is that it very stuck. In very big rock. No idea how even get there, really.\n\nCome! We try you hand at fate!", objectives = "Recover the legendary kobold shovel Excavator.", progress = "Pull with knees, not with back.", completion = "You destined for great things, <name>. Shovel is proof!" }
WordHunterWoW_QuestEN[80110] = { title = "Daily Doubloons", description = "", objectives = "" }
WordHunterWoW_QuestEN[80144] = { title = "The Holey Grail", description = "Holey Grail, one of very best relics, lost for long time, {name}. Very old, very powerful.\n\nWould mean a lot if could find.\n\nSet you grand quest for to search for Holey Grail!\n\nTry start with Fishcan. He old as dirt, might know something. Seek him by pools to north-east.", objectives = "Find the Holey Grail.", progress = "Got Grail?", completion = "Even hole-ier than remembered. More fish goo, too." }
WordHunterWoW_QuestEN[80145] = { title = "The Motherlode", description = "<Zee-Zee's internals begin to hum softly as their projector reaches the appropriate operating temperature.>", objectives = "Activate the remaining crushers in the Shadowvein cave.", progress = "<Zee-Zee looks up at you.>", completion = "<Zee-Zee looks ready to head back to the Deepforge Golemworks.>" }
WordHunterWoW_QuestEN[80175] = { title = "The Last Mage", description = "I want you to check in on someone. He's a mage... the only one of us who is. All the others died in the crash.\n\nHe's trying to make a portal to the Empire, so we can get reinforcements and have a way to and from home. \n\nWe all know it's a lost cause, but he still hasn't given up. \n\nMaybe meeting a seasoned traveler like you will give him the reality check he needs. Check on him, will you?", objectives = "Find Wenren Althal in Beledar's Bounty.", completion = "What? Who sent you? \n\nIt doesn't matter, listen! I'm so close to a breakthrough I can taste it!" }
WordHunterWoW_QuestEN[80176] = { title = "Arcane Trickles", description = "I've almost got it!\n\nI'm making a new kind of teleportation spell to get us back home to the Empire.\n\nThese crabs might just be the key. They're practically radiating arcane teleportation magic!\n\nI need more samples to study. \n\nTake this focus, it will let you see traces of the arcane. There aren't many other arcane sources around here, so any you see should lead you straight to the affected crabs!", objectives = "Obtain 5 Arcane-Suffused Organs from Shore Crawlers near Mereldar.", progress = "Have you found the crabs? They'll be near water. That focus should let you see the trails of arcane dust they leave behind.", completion = "Yes, these are perfect!" }
WordHunterWoW_QuestEN[80177] = { title = "Arcane Experiments", description = "This is it! The energy crackling from these crabs is charged with teleportation magic! I just need to extract it and adjust the formula--\n\nI can do this, my new friend! I just need another hand. Help me test this?", objectives = "Help Wenren with his experiments.", completion = "<Wenren's lifeless eyes stare up at you.>" }
WordHunterWoW_QuestEN[80178] = { title = "A Murder Most Foul", description = "<Somebody didn't want Wenren to finish his spell.\n\nFind out who.>", objectives = "Investigate Wenren's murder.", progress = "<The body is still warm.>", completion = "<You carefully consider the clues you have gathered.>" }
WordHunterWoW_QuestEN[80179] = { title = "Finding Justice", description = "<The pieces fit together to form a simple, but dark picture.\n\nThe Order of Night did not want Wenren to create a portal back to the Empire. No doubt reinforcements and supplies would hinder their mission. \n\nSo, someone stabbed him, burned his research, and smashed his tools. \n\nBut with this arcane focus in hand, you can see a faint trail of arcane residue. Did some arcane dust get on the perpetrator? \n\nFollow the trail and find out.>", objectives = "Track down Wenren's killer.", completion = "<Steelstrike listens to your story with growing concern.>\n\nNo! Dead?!" }
WordHunterWoW_QuestEN[80183] = { title = "Pieces of Hate", description = "", objectives = "" }
WordHunterWoW_QuestEN[80184] = { title = "Preserving in Battle", description = "There is much to learn on the battlefield, even in lesser coordinated environments. Go ahead and give it a try.", objectives = "Obtain Honor in Random Battlegrounds.", progress = "You haven't finished quite yet.", completion = "See, it wasn't so bad. Take this for your time." }
WordHunterWoW_QuestEN[80185] = { title = "Preserving Solo", description = "Battling on your own will build strength and courage. Display your solo capabilities in small battles, then return to me.", objectives = "Complete 12 rounds of Solo Shuffle.", progress = "Finish off what you set to do then return.", completion = "Your nobility and strength is clear. Take these." }
WordHunterWoW_QuestEN[80186] = { title = "Preserving in War", description = "Partaking in large-scale conflicts will hone your ability to look at the larger picture. Go off and garner that experience, then come back to see me.", objectives = "Obtain Honor in Epic Battlegrounds.", progress = "Complete what you have set off to do.", completion = "I knew you would succeed. Here, take this." }
WordHunterWoW_QuestEN[80187] = { title = "Preserving in Skirmishes", description = "Part of training is repetition. I am told there are others out there like yourself that partake in small-scale skirmishes. Go off and find training partners to battle against, then return to me.\n\nLet us see what you can prove, then return to me.", objectives = "Obtain Honor from Arena Skirmishes.", progress = "Practice makes perfect. Finish off the tasks then return.", completion = "Excellent practice! Here's something for your time." }
WordHunterWoW_QuestEN[80188] = { title = "Preserving in Arenas", description = "Fast paced and coordinated combat is a mighty test for the strongest combatants. Find others to battle alongside you to fight worthy opponents in the arena.", objectives = "Obtain Honor in Rated Arenas while in a Party.", progress = "You have not finished what you set off to do yet.", completion = "Very impressive - take these as your reward." }
WordHunterWoW_QuestEN[80189] = { title = "Preserving Teamwork", description = "The ability to strategize with others to take objectives is key to becoming a strong warrior. Go onto the battlefield, then return to me.", objectives = "Obtain Honor in Rated Battleground Blitz or in Rated Battlegrounds.", progress = "Finish off what you set to do then come back.", completion = "Great work! You have earned these." }
WordHunterWoW_QuestEN[80190] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[80196] = { title = "Extract a Gem", description = "Any gem can be removed from your equipment using the Extract Gem ability.\n\nThe gem will not be destroyed.\n\nExtract a gem now.", objectives = "Extract the Chipped Deadly Sapphire from your equipment." }
WordHunterWoW_QuestEN[80197] = { title = "Combine Gems", description = "Prismatic gems can be combined to create a more powerful gem.\n\nCombine three Deadly Chipped Sapphires to create a Flawed Deadly Sapphire that grants additional Critical Strike when socketed.", objectives = "Use three Deadly Chipped Sapphires to combine them into a Flawed Deadly Sapphire.", completion = "As you find additional gems of the same type, you can continue to combine them to increase your combat capabilities." }
WordHunterWoW_QuestEN[80202] = { title = "Hot Pollenate-o", description = "Important to make sure not take too much. Make sure hive healthy so can come back.\n\nBees eat pollen, yes? So fire bees eat fire pollen? Yes.\n\nBring fire pollen to bees. Grow strong. Bee productive.\n\nCheck edge of hive for flowers bees not get to yet. When catch fire, you got good one.", objectives = "Gather pollen from Pollen Rich Cinderblooms and return it to nearby bees before it goes out.", progress = "Just a little bit on fire. You tough, you be okay.", completion = "Good. Healthy hive make happy wax." }
WordHunterWoW_QuestEN[80203] = { title = "Social Clues", description = "<The nerubian keeps her voice low, a careful eye on the guards behind you.>\n\nThe Weaver sent you, yes? I arrived to petition the Magistrate's approval for Ascension--to infiltrate high society, of course.\n\nBut he's missing. A rather large inconvenience.\n\nI need to ask around. You're just what I've been waiting for! You may pretend to be my... servant. Pet? Whatever makes it more palatable to you.\n\nI so rarely get to work alongside a friend. We will have fun together, fellow spy.", objectives = "Help Orator Tx'itk ask around to find the Magistrate.", progress = "I have a few old friends who recently Ascended. Surely, one of them has heard something they would be willing to share. For old time's sake.\n\nAnd if not, maybe jealousy in seeing my fashionable new pet will inspire them to offer up what they know.", completion = "I knew Ascension changed people, but... They were my friends. And now, they don't even want to be seen with me.\n\nIt makes me wonder... if I succeed in all this, will I even still be myself?\n\n<Tx'itk shakes her head.>\n\nIt doesn't matter. I'll do what needs to be done." }
WordHunterWoW_QuestEN[80204] = { title = "Espionage and Ventriloquism", description = "The Puppetmaster is our best lead for finding the Magistrate.\n\nBut is it just me, or did those puppets seem... horrifically lifelike? If this artist is behind the Magistrate's disappearance, he certainly isn't just off to see a puppet show.\n\nWe should investigate the Puppetmaster's workshop. Question him, or at least ransack his things. Just a bit. Until we find something useful.\n\nYou'll have to keep playing your rather undignified role in this charade. But it will pay off for us.", objectives = "Investigate the Puppetmaster's Workshop.", progress = "<Orator Tx'itk lowers her voice.>\n\nSomething isn't right here. Play along just a while longer. Let's see what else we can find.", completion = "The Magistrate is definitely in danger. We must act quickly before I lose my chance at Ascension." }
WordHunterWoW_QuestEN[80205] = { title = "Pulling Strings", description = "Just think of it! Overcrawlers, war prisoners, civilians, fellow nerubians, important nobility being kidnapped and turned into puppets right under the Magistrate's nose.\n\nIt's horrific--and exactly what I needed! If we save the Magistrate from this fate, he'll owe me. Not just for saving his life, but to keep quiet about all this.\n\nWe're off to the theater, then. If you can keep the Puppetmaster occupied, I'll free High Elevator Etak'kaht from his grasp.\n\nHopefully he's not part of the show yet.", objectives = "Confront the Puppetmaster to rescue High Elevator Etak'kaht.", completion = "I'm thrilled. There couldn't have been a more perfect opportunity to get the Magistrate's attention. And the Weaver will be pleased to hear we have him in our pocket indefinitely, with this blackmail situation.\n\nNow, I suppose I'm off to the Transformatory.\n\n<Tx'itk shudders subtly.>\n\nI... I must not let my resolve falter now. The Weaver has asked this of me. I will be her eyes." }
WordHunterWoW_QuestEN[80206] = { title = "Marionette Mercy", description = "It's perfect! The Puppetmaster is so interested in adding you to his collection, he literally invited us to go rescue the Magistrate.\n\nI don't want to imply I've been using you as bait this entire time, but... Let's just say certain calculated risks have paid off.\n\nEven such a skilled artist must have a way to correct potential errors. There has to be an antitoxin of sorts for that paralytic around here somewhere!\n\nFind it. And perhaps we test it before we go use it on the Magistrate. Just in case.", objectives = "Find the Puppetmaster's Antiparalytic Serum.", progress = "I would worry we're taking too long, but considering how dramatic that Puppetmaster is, I can't imagine he'll start the show without us.\n\nWe should be prepared for something... rather unpleasant at that theater.", completion = "Just what we were looking for.\n\nAnd about using you as bait... You know it's not personal in our line of work, friend.\n\nI was open from the start of all this that you were the status symbol I needed to navigate this area and socially manipulate the Ascended.\n\nAnd if there's one thing I know to bet on, it's the ability of the Ascended to covet power flaunted over others." }
WordHunterWoW_QuestEN[80207] = { title = "How Scandalous!", description = "Did you see anything?\n\nI was just at the Forgegrounds picking up a jewelry commission and all of a sudden everyone was shouting like the Coreway was under attack--again.\n\nBut it was not that...\n\nSome peacekeepers were heading towards the depot--where crafting shipments are sent up from the Deeps. I bet it's something to do with the machine speakers!\n\nThe peacekeepers ushered everyone away before I could see what had happened. But maybe you can sneak a glimpse?", objectives = "Investigate the disturbance near the Forgegrounds in Dornogal.", completion = "Move along. This is an ongoing--Oh, <name>, my apologies.\n\nWe may actually need your assistance." }
WordHunterWoW_QuestEN[80208] = { title = "Digging into Trouble", description = "", objectives = "" }
WordHunterWoW_QuestEN[80209] = { title = "An Oddball in Dornogal", description = "We have received reports that an eccentric Arathi is accosting our citizens. We have little experience with outsiders and my superiors are wary of a diplomatic incident.\n\nI have been tasked with finding this \"Lamplighter\" and resolving his concerns. You have worked with the Arathi before - can you assist me?\n\nI have a list of earthen who have reported the Lamplighter. You can interview half the list. Between us, we can hopefully locate the Arathi before he troubles more citizens.", objectives = "Interview Concerned Dornogal Citizens to locate the Arathi Lamplighter.", completion = "This is not quite what I was expecting.\n\nHe is certainly odd but a troublemaker? I think not." }
WordHunterWoW_QuestEN[80210] = { title = "Found Around the Unbound", description = "This Lamplighter is looking for his fellow Arathi. The foreman says he directed an Arathi shipwright to Freywold Village.\n\nMy superiors insist that Peacekeepers do not leave Dornogal... but per their orders, I must assist Kaerter. And to do that, I have no choice but to leave the city.\n\n<Leif quickly hides a smile.>\n\nIt is decided then. If you are willing, please meet us at Freywold Village. Your continued aid would be appreciated.", objectives = "Meet Peacekeeper Leif outside Freywold Village.", completion = "It seems the locals have taken issue with our foreign companion. I am attempting to defuse the situation as best I can.\n\nBut we have more pressing problems." }
WordHunterWoW_QuestEN[80211] = { title = "The Pillage of Freywold Village", description = "The Arathi shipwright was here but has moved on with most of her entourage. She had left a few Arathi behind but...\n\nSoon after the shipwright left, earthen started disappearing. The villagers suspected the Arathi but had no proof. Then one day, the remaining Arathi left town in the middle of the night.\n\nThe locals said the Arathi stayed at the inn. Can you look there for any clues as to where the Arathi are now?\n\nGiven the villagers' hostility, the Lamplighter and I shall remain here for the moment.", objectives = "Search for clues as to where the Arathi went.", progress = "I am attempting to convince the villagers that the Lamplighter is not involved in these disappearances.\n\nDid you find anything useful?", completion = "If I understand correctly, the Arathi are abducting earthen?\n\nAnd they are also killing each other?\n\nWhat madness is this?" }
WordHunterWoW_QuestEN[80212] = { title = "The Abductors' Obstructors", description = "The Order of Night is clearly interested in our resources. They have abducted earthen to harvest for them and may continue taking others. We must stop them.\n\nThe next largest earthen settlement is Rambleshire. If the Order needs more workers, they might have gone there to get them.\n\nGo on ahead {name}. I must first speak with Kaerter about why the Arathi are doing this.", objectives = "Meet Peacekeeper Leif at Rambleshire.", completion = "While we have not yet seen any Arathi, there is an uneasiness about the town.\n\nKaerter believes the Order is here. He says they are simply waiting for a moment to strike." }
WordHunterWoW_QuestEN[80213] = { title = "Holy Fire in Rambleshire", description = "I'm certain there are still Order folks sneaking around here. Now they might be carrying messages on them, just like the clues you found in Freywold. \n\nYou and I are gonna find out.\n\nHere, take these thuribles. They might look like tiny incense burners, but I've enchanted them with Sacred Flame. \n\nJust throw one down and you'll get a big bang with a bright flash! Should be enough to stun anyone sneaking around. \n\nJust don't throw one at me! Got it?", objectives = "Use Flashfire Thuribles to reveal Order of Night forces in Rambleshire, eliminate them, and search them for clues.", progress = "Alright, I'll admit it, the little Pebble is pretty useful. He knows more about the earthen and the surface than I ever will. \n\nAnyway, did you find anything?", completion = "\"New friends\" huh?\n\nGuess I'm not the only one...\n\n<Kaerter freezes when he realizes what he's just said and suddenly points a finger at you.>\n\nYou didn't hear me say nothing, got it?" }
WordHunterWoW_QuestEN[80214] = { title = "A Time to Kill at the Lumber Mill", description = "Alright, let me see if I get all of this. The shipwright brings an entourage up here to get lumber for airships. \n\nBut the shipwright is actually Order of Night, along with most of her group. So they murder the loyal Arathi, kidnap earthen, and force them to run the lumber mill up here.\n\nAnd now we gotta deal with the Order AND whoever their new friends are.\n\n<Kaerter swears and shakes his head.>\n\nC'mon, let's head to the mill. We got a lot of bad guys to kill and time's wastin'.", objectives = "Meet Lamplighter Kaerter outside of Skolzgal Mill.", completion = "Nerubians. Lots and lots of nerubians.\n\nBy Beledar's Light do I hate nerubians." }
WordHunterWoW_QuestEN[80215] = { title = "Ungirthin' the Earthen", description = "While I do enjoy beating the black blood out of nerubians, we must save the earthen prisoners first.\n\nI saw they're being held by Arathi ball and chain. Someone like you should be able to shatter them pretty quick. Just... do that thing you do!\n\nOh, and we should split up to cover more ground. Yeah Leif's gonna complain, but he's always complaining anyway.", objectives = "Free 8 Abducted Lumberjacks.", completion = "Well done. I will lead the few I was able to rescue to safety." }
WordHunterWoW_QuestEN[80216] = { title = "Concealed in the Weald", description = "The nerubians seem to be in league with the Arathi. Many of them are guarding the mill, but I am sure there are more than we can see.\n\nWe cannot allow such a large enemy force to operate unimpeded this close to Rambleshire.\n\nThe nerubians attacked and destroyed large sections of Dornogal not too long ago. The Order of Night Arathi are abducting and enslaving our people.\n\nWe must eliminate as many of them as we can. Preferably all of them.", objectives = "Eliminate Shadowsilk forces at the Skolzgal Mill.", progress = "The more enemies we eliminate, the safer we will all be.", completion = "That should disrupt their operation. Let us hope it is enough for now." }
WordHunterWoW_QuestEN[80217] = { title = "A Lamplight for the Shipwright", description = "Where is Kaerter now? Did he go off on his own again?\n\n<Leif sighs.>\n\nWe've rescued the earthen and eliminated many hostile forces, but our task is not yet complete.\n\nShortly before you arrived, we spotted a group of Arathi traveling up this hill. One of them was identified as the Arathi shipwright.\n\nThe shipwright is the leader here. Losing her will cripple their efforts to utilize the mill.\n\nHead up the hill and find her before she can escape.", objectives = "Confront the Arathi shipwright.", completion = "Kaerter is injured. He will not be an effective fighter until he heals." }
WordHunterWoW_QuestEN[80218] = { title = "Up to No Good Down in Silkwood", description = "The Order is moving the wood through the nerubians. Leif said he saw the shipwright leave the cave and head down to the beach. \n\nThe nerubian tunnel must be down there. You're going to have to seal that Flameforsaken passage.\n\nWhile slinking around, I noticed the Order brought explosive barrels with them. Find a few and use them to blow the tunnel.\n\nGet going {name}. I'll be right behind you.", objectives = "Collect Silkwood Explosive Barrels, then destroy the nerubian tunnel at Silkwood Grotto.", progress = "Did you take out the tunnel?", completion = "Good stuff <name>. That should put a dent in their plans!\n\nWith that tunnel gone, ain't no way for them to send that wood to Hallowfall now. That makes the mill all but worthless.\n\nPhew! Order stopped, earthen saved, nerubians killed. Job well done if you ask me!\n\nI don't know 'bout you, but I could use a vacation." }
