WordHunterWoW_QuestEN[80295] = { title = "Rocks, Water and Elemental Fodder", description = "", objectives = "" }
WordHunterWoW_QuestEN[80310] = { title = "Setting Sun Garrison", description = "Might you be willing to find Anji at the Setting Sun Garrison to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", completion = "You I can work with. Let's show these trainees a thing or two about how a real <class> fights." }
WordHunterWoW_QuestEN[80311] = { title = "Order of the Cloud Serpent", description = "Widing toortles is da best!\n\nBut widing cloud serpents is even better!\n\nThere's some peepos at da Arboweetum who wide cloud serpents and can teach you how!", objectives = "Speak to Elder Anli at The Arboretum.", completion = "Ah, another student of the skies. Welcome to the Arboretum." }
WordHunterWoW_QuestEN[80312] = { title = "Gasping Plea", description = "<A gasping, pathetic-looking fish taken from the corpse of a kobyss flops weakly in your hand. Its beady eye twitches, and you suddenly hear a breathless voice in the recesses of your mind.>\n\nThe water. Take me to the water. Away from these kobyss wretches. Away from the sky.", objectives = "Put the strange fish in safe waters near the kobyss camp at Sunless Strand.", completion = "<The fish gulps down saltwater to regain its breath and then turns to look at you with intelligent eyes.>\n\nI live, thanks to you. The shade of these rocks suits me nicely for the work to be done. \n\nAllow me to repay your selfless gesture." }
WordHunterWoW_QuestEN[80313] = { title = "Tidal Charms", description = "<When the fish speaks, its lips do not move. You hear its voice in your head.>\n\nNo doubt you have found that your senses cannot be trusted when dealing with the kobyss. A tremendous power, is it not? It is only fair that you show them the power they wield is not theirs alone.\n\nI will show you how to craft a tool to lure and destroy them. You will find their kind carry shards taken from the deep. Bring them to me.", objectives = "Collect 12 Sunless Shards from the kobyss at Sunless Strand.", progress = "Bring the materials. Only then can we continue.", completion = "Glinting abyssal shards and strands of coral. Bound with words of power and worn around the neck, I will show you how to trick the senses of your enemies." }
WordHunterWoW_QuestEN[80314] = { title = "Voices from the Deep", description = "To deceive the senses of these kobyss is one matter. To know what will captivate them is another. They champ and drool at the thought of devouring your kind. But it is the voices of the deep that transfix them and lower their guard. It's then that you will strike.\n\nSearch their shrines to gain an insight for what these wretches hold sacred. See how they have twisted the bellowing truths that lie below.", objectives = "Study three ritual sites for insights on the kobyss.", progress = "What have you learned?", completion = "You see now what the kobyss revere. It is time to put that dark knowledge to use." }
WordHunterWoW_QuestEN[80315] = { title = "Alluring Offer", description = "It is done. Take this tidal charm, cloak your form in the darkness of the sea, and unmake the kobyss. Their strongest warriors gather and scheme against your kind upon that central island. With the lure, they will not see you for what you are. Use that advantage to become their end.\n\nBut understand, as the kobyss fail to, this is a power you borrow. It belongs to the sea.", objectives = "Lure and assassinate Gillcarver and his Kobyss Tidemarshals on the island off the Sunless Strand.", progress = "Isolate them. Destroy them.", completion = "With this, the lesson has been given. They will think twice before considering my kind as meat.\n\nYou kill well, land-walker. But the power of the deep must be returned. Our time together nears its end." }
WordHunterWoW_QuestEN[80316] = { title = "Return to the Sea", description = "I remain weakened by my time so near the searing Light of the surface. I ask that you take me to deeper waters, away from these kobyss, where I can return to my kind.", objectives = "Take the Peculiar Fish to deeper waters.", completion = "<A warbling cry emanates from the fish. It casts its song into the ocean depths.>\n\nI expected an ignoble end at the hands of the kobyss for my folly. Never could I have believed a land-dweller would be my savior. I will remember you. Now, let the facade be at its end. My kind will be expecting me.\n\n<The fish's form begins to shift and unwind. You realize its guise as a fish has been yet another illusion.>" }
WordHunterWoW_QuestEN[80320] = { title = "Aid the Klaxxi", description = "", objectives = "Lend us your aid, Wakener, and the mantid empire will grow.", progress = "Lend us your aid, Wakener, and the mantid empire will grow.", completion = "Yes, good." }
WordHunterWoW_QuestEN[80321] = { title = "Departure", description = "Best if we split up here. I'll guide everyone to safety and see about getting them evacuated.\n\nIn the meantime, you should search for Khadgar. I'm sure he could use your aid as well.\n\nYou'll find another exit further ahead that should lead back to the surface.", objectives = "Find Khadgar back on the surface.", completion = "<The portal flickers and twists, making it impossible to see through to the other side.>" }
WordHunterWoW_QuestEN[80323] = { title = "Foggy Faceoff", description = "", objectives = "" }
WordHunterWoW_QuestEN[80334] = { title = "Shattered Spires", description = "With nothing to contain their arcane power, Dalaran's spires are crumbling.\n\nIf we let their energies continue to bleed out unchecked, that power could destabilize and destroy what is left of our forces.\n\nFind Aethas! He will know what to do.", objectives = "Find Aethas at the Tranquil Strand.", completion = "Jaina yet lives?\n\nThank the Sunwell!\n\nThough none of us will survive long if we do not contain the energies of the spires." }
WordHunterWoW_QuestEN[80349] = { title = "Time to Return", description = "You'd best be on your way now. That portal should take you back to the village.", objectives = "Return to Moratari.", completion = "Excellent. I hope this expedites our research." }
WordHunterWoW_QuestEN[80378] = { title = "A Light of the Dark", description = "The image of a purple candle, burning with glorious power springs unbidden to your mind as you contemplate the decaying filth before you, followed by a faint whisper echoing through your mind: \"One candle to rule them all, and in its brightness bind them.\"\n\nBring Janky the candlesmith in Gundargaz enough Coagulated Black Blood to forge a most unfortunate candle.", objectives = "Collect Coagulated Black Blood and bring it to Janky the kobold candlesmith in Gundargaz.", progress = "<Janky shivers as you approach.>\n\nAh!", completion = "Oh...Janky not normally turn down new candle, but you sure?" }
WordHunterWoW_QuestEN[80380] = { title = "Cloak and Needle", description = "Once you don your cloak, you will be able to find threads on any enemy.\n\nThe cloak will naturally absorb those threads, permanently increasing your power.\n\nTry collecting a thread from the nearby Infinite Ravagers.", objectives = "Equip your Cloak of Infinite Potential and collect a Thread of Power from an Infinite Ravager.", progress = "You need not be a tailor. The cloak will weave threads for you.", completion = "You will find similar threads everywhere, from slain foes to looted treasures." }
WordHunterWoW_QuestEN[80382] = { title = "Eggs in One Basket", description = "<This work order remains unfilled. Aliya Hillhelm would be quite happy if you helped complete the order.>", objectives = "Collect 10 Hillhelm Eggs to place in this basket.", progress = "Inform Aliya that the work order is complete.", completion = "Thank you very much! We've been short-handed since Aunt Gerta left us. Every bit of help is appreciated." }
WordHunterWoW_QuestEN[80384] = { title = "A Keg-Stamped Package", description = "<A note, attached to a small and crumpled package, is shoved into your hands by a nondescript figure. Just as quickly, they disappear into the crowd. The letters on the note are scrawled crudely, as if by a dagger dipped in ink.>\n\nHere's yer share of the plunder.\n\nSent the mates to the inn.\n\n<You look around to see if there is anything else on the note. There is a picture of a keg at the bottom.\n\nYou shake the package gently and hear the telltale sound of coins.>", objectives = "Bring the Keg-Stamped Note to Da'kash Grimledger at the Roasted Ram Inn in Valdrakken.", completion = "Got sent a package from Keg Leg, did ya? \n\nWell I can't say I really understand how you're involved in what we're doing, but it's not up to me to question the captain.\n\nTake a look at what I've plundered from around here. I'll give you some good stuff for those coins." }
WordHunterWoW_QuestEN[80385] = { title = "Last Hurrah: Dragon Isles", description = "You've become quite popular with our allies, {name}!\n\nTo the south the Iskaara Tuskarr need your help with their community feast.\n\nTo the west the Maruuks have requested your aid with their hunts.\n\nTo the north the Obsidian Outcasts request your help reclaiming Dragonbane Keep.\n\nSounds like you have a full day ahead of you! Best of luck.", objectives = "Assist the Tuskarr with their community feast, the Maruuk with their Hunt, and help reclaim Dragonbane Keep.", progress = "We're lucky to have you on our side, <name>.", completion = "Thanks to your efforts the Dragon Isles have been made all the safer.\n\nPlease accept this token of our appreciation." }
WordHunterWoW_QuestEN[80386] = { title = "Last Hurrah: Zaralek Caverns and Time Rifts", description = "Our allies are once again requesting your aid, {name}.\n\nIn the Zaralek caverns the Dragonscale Expedition needs you to protect their researchers.\n\nWe're also concerned with the Zaqali invasions in the Ohn'ahran Plains and Azure Span.\n\nMeanwhile, the Bronze Dragonflight has asked for you to help them deal with temporal anomalies to the east of Valdrakken.\n\nHurry {name}, time is of the essence.", objectives = "Protect the Researchers under Fire, loot a Secured Shipment from a Suffusion Camp, and assist Soridormi in dispelling a Time Rift.", progress = "Do you bring news of your success?", completion = "I've heard great news from those you've helped, <name>.\n\nPlease accept this gift." }
WordHunterWoW_QuestEN[80388] = { title = "Last Hurrah: Emerald Dream", description = "The druids call for aid!\n\nEnergy from the Emerald Dream is spreading across the Dragon Isles, please help them investigate it.\n\nThey also ask you travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom.\n\nSome of the druids also wish for you to plant Dreamseeds in the Emerald Dream.\n\nPlease help them, {name}.", objectives = "Gather one hundred Dreamsurge Coalescence across the Dragon isles, assist Sprucecrown in creating a Superbloom, and plant 3 Dreamseeds of any quality in the Emerald Dream. Dreamseeds can be acquired from most activities in the Emerald Dream.", progress = "How are the druids doing?", completion = "My, the work you've done with the Emerald Dream is sure to help Azeroth heal.\n\nPlease accept this humble gift, along with our gratitude." }
WordHunterWoW_QuestEN[80389] = { title = "Last Hurrah", description = "", objectives = "" }
WordHunterWoW_QuestEN[80392] = { title = "The Caretaker of Brunwin's Terrace", description = "Greetings, outlander. You must be the problem solver I've heard about! I'm Caretaker Batzvara. I tend to earthen who have gone into stasis, like our friend here.\n\nI often patrol Brunwin's Terrace to honor my fellow earthen with an offering of cinderbrew. Recently, however, I've drawn the attention of a local species of moles. They have a nose for sweets, and greedy claws for all else.\n\nYou look like you can defend yourself. Will you accompany me to pay respect to those who have gone into stasis?", objectives = "Offer cinderbrew to 6 inert earthen and kill 10 Sweetsnufflers.", completion = "Gratitude expressed. Your reputation as a stalwart ally is well-deserved." }
WordHunterWoW_QuestEN[80394] = { title = "Along for the Ride", description = "", objectives = "" }
WordHunterWoW_QuestEN[80395] = { title = "Elemental Excavation", description = "", objectives = "" }
WordHunterWoW_QuestEN[80397] = { title = "Sweets Seekers", description = "Earthen cinderbrew is a potent drink. It's dangerous to those who lack our constitution. Even worse, it has a sweet aroma that draws the attention of a vicious species of mole. They'll do anything to get their claws on it!\n\nAs I honor the earthen of Brunwin's Terrace with a sweet libation, my potent potable will draw their attention. If you're anywhere near me, be on your guard, so you can put down any who pop up.", objectives = "Kill 12 sweetsnufflers." }
WordHunterWoW_QuestEN[80399] = { title = "Rations and Revelations", description = "We found these prisoners fleeing a nearby nerubian military base.\n\nThe circumstances of their escape are... unclear, even to them. As if someone else created the opening they needed to escape.\n\nThey need rest, but we need to find out what happened in there.\n\nFood first. Maybe once they've regained some of their strength, they'll remember something.", objectives = "Hand out 3 Arathi Rations.", progress = "We managed to throw together a simple stew of sorts. It's not the tastiest, but it has to be better than whatever they had to eat in spider prison.", completion = "These people have been through so much. Civilians--not even soldiers. Most of them didn't sign up for this. And yet they became prisoners of war.\n\nIf anything back at the nerubian base could give us an advantage, we have to take it." }
WordHunterWoW_QuestEN[80400] = { title = "Item Collection [DNT]", description = "Kill Collect", objectives = "Collect 5 of Y" }
WordHunterWoW_QuestEN[80401] = { title = "A Perfect Sponge", description = "Welcome, stalwart colleague, to Shimmermist Falls! It's always damp here--a thriving paradise for green, living things. Unfortunately, it's also the perfect climate for moss to grow on my inert earthen charges. \n\nWe'll need to gather a few supplies for removing the moss. First, we need a sponge to wash their surfaces. It needs to be soft enough to not damage them but strong enough to hold up to an earthen's rough stone skin. \n\nThe caps from the lashrooms down below are perfect!", objectives = "Collect one perfect lashroom cap.", progress = "These lashroom caps make for perfect sponges!", completion = "Task complete! This one is perfect! And your performance is optimal, of course." }
WordHunterWoW_QuestEN[80402] = { title = "Buckets and Blooms", description = "Down among the creeping lashrooms grows an orange flower. When mixed with water, its blooms make a caustic solvent that is perfect for removing moss from earthen skin.\n\nI also left a bucket next to this earthen the last time I was here, which I use to make the solvent. Something seems to have made off with it.\n\nCould I delegate the task of gathering these to you? I'll wait here. The moles from the terrace have given me enough excitement for one day.", objectives = "Collect 8 caustic blooms and find the missing bucket.", progress = "The acidity from the plants is strong enough to remove the moss but gentle enough not to harm the earthen. Plus it has a pleasing smell to it. Almost like sulfur.", completion = "Ah, I can smell the sulfur from here! Thank you for gathering the bucket and blooms.\n\nNot everyone shares my taste, but I enjoy a bowl of lightly seared magma in an igneous bowl, especially when the fumes are particularly sulfurous. \n\nWhat? You've never tried it? To each their own." }
WordHunterWoW_QuestEN[80404] = { title = "Mossy Earthen", description = "Excellent work gathering everything together. I've mixed the solvent for you. \n\nNow all that's left is to gently clean off our mossy friends down there.", objectives = "Tend to 4 mossy earthen.", progress = "Let's get these folks cleaned up.", completion = "That's much better! Earthen should be firm stone, not soft fuzz." }
WordHunterWoW_QuestEN[80405] = { title = "Too Much Drip", description = "This is Ausgazur. His hand is usually full of a selection of his favorite gems. We don't really know what it's like when we go into stasis, but he wanted to spend his last moments contemplating the natural beauty of Azeroth and her bounty.\n\nI am afraid someone or something has made off with the jewels he usually holds. Let's look around. See if you can find any clues where they may have gone off to.", objectives = "Examine Ausgazur for clues.", progress = "Ausgazur will never forgive me if his gems go missing. This is very upsetting. Who would steal from an earthen in stasis?", completion = "Kobolds made off with his gems? This is unacceptable! We must recover the rest of Ausgazur's jewels!" }
WordHunterWoW_QuestEN[80406] = { title = "Seeking Ausgazur's Gems", description = "So it was kobolds who made off with Ausgazur's gems. I did not realize the Waterworks was under attack. Our timing is lucky for the defenders down below! \n\nWe must get those jewels back! I'll stay here and guard the remaining gems, but I implore you to complete a critical task: go down into the Waterworks and retrieve the rest.", objectives = "Recover 4 of Ausgazur's gems.", progress = "We need to find the rest of Ausgazur's gems! Critical priority!", completion = "Excellent work! Though they're not worth much monetarily, these gems meant a great deal to Ausgazur. I am glad he will not be parted from them any longer." }
WordHunterWoW_QuestEN[80407] = { title = "Glintwick the Gem Grabber", description = "The kobold mentioned Glintwick, did he? It sounds like she's the driving force behind these gem thieves. I'll bet my beard she's got Ausgazur's last gem!\n\nLook for her in the Waterworks and see if she has the final gem. She may also be behind the attack that's happening, so taking her out will help the defenders.", objectives = "Kill Glintwick.", progress = "Glintwick will not get away with this thievery!", completion = "You did it! You found the last gem! I'm glad that Glintwick will no longer be after Ausgazur's gems.\n\nThis particular gem was his favorite. It's not faceted, like the rest. Ausgazur could always find the beauty in flawed things. He would show me this one and marvel at its hue and potential. He never wanted it buffed or shined.\n\n<She's silent a moment, then looks at the gray earthen beside her.>\n\nAh, Ausgazur. You never cared what I looked like either. You saw my potential. I miss you, friend." }
WordHunterWoW_QuestEN[80408] = { title = "Shimmermist Falls", description = "West of Gundargaz is another green space - a lovely area with waterfalls and more terraces. My schedule takes me in that direction next, and I would be very glad of your company to help deal with the wildlife there as well. \n\nIf your other duties are not pressing, let us meet there.", objectives = "Meet Batzvara in Shimmermist Falls.", completion = "You made it! Let us get to work." }
WordHunterWoW_QuestEN[80409] = { title = "Polarized", description = "", objectives = "" }
WordHunterWoW_QuestEN[80412] = { title = "Fending off Darkness", description = "", objectives = "" }
WordHunterWoW_QuestEN[80426] = { title = "Aid the Shado-Pan", description = "", objectives = "The Shado-Pan would appreciate any aid you can provide to our cause.", progress = "The Shado-Pan would appreciate any aid you can provide to our cause.", completion = "You are not only a skilled fighter, but generous! Thank you, <name>." }
WordHunterWoW_QuestEN[80427] = { title = "Aid the Golden Lotus", description = "", objectives = "Have you come to aid us?", progress = "Have you come to aid us?", completion = "Great! Keep up your training and we'll be ready for anything!" }
WordHunterWoW_QuestEN[80429] = { title = "Aid the August Celestials", description = "", objectives = "The sha force us to consider what is worth fighting for. What will you give for the future of Pandaria?", progress = "The sha force us to consider what is worth fighting for. What will you give for the future of Pandaria?", completion = "You are brave and honorable." }
WordHunterWoW_QuestEN[80430] = { title = "Aid the August Celestials", description = "", objectives = "Have you offerings for the mighty Black Ox?", progress = "Have you offerings for the mighty Black Ox?", completion = "Stand proud and fight swiftly." }
WordHunterWoW_QuestEN[80431] = { title = "Aid the August Celestials", description = "", objectives = "Greetings, challenger. I will accept your donations to my temple.", progress = "Greetings, challenger. I will accept your donations to my temple.", completion = "Fight with strength and honor." }
WordHunterWoW_QuestEN[80433] = { title = "Aid the August Celestials", description = "", objectives = "To practice is to improve oneself. To give is to improve one's community.", progress = "To practice is to improve oneself. To give is to improve one's community.", completion = "You bring honor." }
WordHunterWoW_QuestEN[80434] = { title = "Into the Deeps", description = "Onward and downward it is, then. We'd best follow after Speaker Brinthe and see what state the nerubians have left her home in.\n\nMagni, Dagran, and I will accompany you down in due time. Would you mind roving ahead and making sure there's a warm welcome awaiting us?", objectives = "Find Speaker Brinthe at the bottom of the Coreway.", completion = "By the Titans! It looks like the nerubians did a number on our station... but I see no spidery fiends here. Only struggling Machine Speakers..." }
WordHunterWoW_QuestEN[80438] = { title = "Aid the Horde", description = "", objectives = "Lok-tar, <name>. What aid do you bring?", progress = "Lok-tar, <name>. What aid do you bring?", completion = "For the Horde!" }
WordHunterWoW_QuestEN[80439] = { title = "Aid the Alliance", description = "", objectives = "King Varian requests your aid, <name>. Have you any supplies?", progress = "King Varian requests your aid, <name>. Have you any supplies?", completion = "A soldier's duty is never done." }
WordHunterWoW_QuestEN[80441] = { title = "Aid the Order of the Cloud Serpent", description = "", objectives = "The Cloud Serpents rely on favorable winds. Have you any fortune for us?", progress = "The Cloud Serpents rely on favorable winds. Have you any fortune for us?", completion = "Excellent. May you ride fair winds on your journey." }
WordHunterWoW_QuestEN[80442] = { title = "Aid the Sunreavers Onslaught", description = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", objectives = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", progress = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", completion = "Very good, we shall ready a counterattack." }
WordHunterWoW_QuestEN[80443] = { title = "Aid the Kirin Tor Offensive", description = "There will be no victory without bloodshed. Have you brought aid, {class}?", objectives = "There will be no victory without bloodshed. Have you brought aid, <class>?", progress = "There will be no victory without bloodshed. Have you brought aid, <class>?", completion = "I will add these to the coffers." }
WordHunterWoW_QuestEN[80444] = { title = "Aid the Anglers", description = "", objectives = "Hey buddy! Fish up any charms recently? The locals say they bring luck to the waters.", progress = "Hey buddy! Fish up any charms recently? The locals say they bring luck to the waters.", completion = "Thanks a million! We're sure to catch a great haul with this!" }
WordHunterWoW_QuestEN[80446] = { title = "Looking for Group", description = "There's my favorite champion!\n\nIf you are in need of a mark to hunt, I know a few dungeons worth exploring.", objectives = "Defeat 3 dungeon bosses.", progress = "How goes the dungeon delving?", completion = "I knew you could do it!" }
WordHunterWoW_QuestEN[80447] = { title = "Looking for More", description = "You think you're tough?\n\nI'll believe it when you take on a real challenge.\n\nDefeat the most powerful foes on Pandaria and we'll see how tough you really are.", objectives = "Defeat 2 raid bosses.", progress = "The real challenge is finding enough other puny elf to team up with.", completion = "I guess you're pretty tough after all!" }
WordHunterWoW_QuestEN[80448] = { title = "A Fresh Scene", description = "Uh-uh honey, I'm not gonna let you spend all day in stuffy dungeons where no one can see your getup!\n\nPut on your going-out look and let's get you somewhere fresh!", objectives = "Complete a scenario.", progress = "You wouldn't catch me dead in a dungeon, nuh-uh. You know what's down there? Mud! Cobwebs! People wearing those shoulderpads way too big for 'em.\n\nNo sir, I'll stay right here, thank you.", completion = "Ooh honey, I can tell you've been somewhere good.\n\nTell me all about it!" }
WordHunterWoW_QuestEN[80456] = { title = "A Sassy Arathi", description = "I had heard that an Arathi was making trouble in the city. It sounds like he is butting heads with the peacekeepers.\n\nYou've worked with the Arathi before, haven't you? Maybe you'd be able to smooth over any ruffled feathers.", objectives = "Speak to Peacekeeper Leif in Dornogal.", completion = "Yes, how can I help you?" }
WordHunterWoW_QuestEN[80457] = { title = "Serving the Queen", description = "", objectives = "" }
WordHunterWoW_QuestEN[80500] = { title = "The Bronzebeard Family", description = "<Moira takes a deep, centering breath.>\n\nWe need to let Brann and my son Dagran know what happened. They're at Dalaran's visitor center.\n\nCould ye go get them for me? Father needs his family right now.", objectives = "Head to Brann and Dagran in the Dalaran Visitor Center to inform them of what has happened to Magni.", progress = "My son always has been the scholarly sort. Takes after his father in that way...\n\nWe're all quite proud of him.", completion = "It's good for us to all be in one room together, even if the reason is so dire. My father hasn't really been a... part of Dagran's life. But I mean to change that, you have my word.\n\nThank ye, <name>." }
WordHunterWoW_QuestEN[80502] = { title = "Don't Cry for Me, Azj-Kahet", description = "<You find a crumpled page of journal paper wrapped around a small key.>\n\nI always suspected Arax'ne was a traditionalist, but I didn't think she'd go this far. I don't know where I'm going, but I just have to get away from her.\n\nTo whoever finds this, it means the worst has come to pass. This key unlocks a chest that contains all my worldly possessions. They are yours.\n\nAll I ask is that you avenge me by slaying Arax'ne.", objectives = "Avenge Klaskin and kill Arax'ne in the Umbral Bazaar.", progress = "The key glints silver in the light of Azj-Kahet.", completion = "The contents of this chest now belong to you.\n\n--Klaskin" }
WordHunterWoW_QuestEN[80508] = { title = "Dread in the Den", description = "You kobold friend, yes? Need help. Bad things happening in the Chittering Den. \n\nGlumtooth Gang setting up camp. Cronies of Candle King, want war with earthen.\n\nCan't stop them alone. Meet me at camp.", objectives = "Meet Scrit at her camp in the Chittering Den.", completion = "You came. Good. Much to do. Much to protect." }
WordHunterWoW_QuestEN[80509] = { title = "A Suit of Slime", description = "Glumtooth Gang no let you into camp looking like that. Need disguise. Make you look like bug, then we walk right in.\n\nFirst, need wax. Plenty here. Take from slime beasts or scrape off hoppers. \n\nThen we stick wax on you. Stick bug bits to wax. Perfect disguise.", objectives = "Collect 20 Sticky Wax from Waxy Runoffs and Wax-addled Hoppers.", progress = "With right disguise, no one know you not bug.", completion = "That everything. Soon you look just like bug." }
WordHunterWoW_QuestEN[80510] = { title = "Healing the Headwaters", description = "Glumtooth Gang so wasteful! They leave much scrap in the water. Bad for water. Bad for scrap. Go clean it up.", objectives = "Remove 6 Waxy Scrap.", completion = "Much better. Make no sense to let scrap rot in pool." }
WordHunterWoW_QuestEN[80511] = { title = "Casing the Camp", description = "Now we take you to camp. You see what Boss Whiskerlash do. Put on bug disguise when we close to camp. Let me do talking.", objectives = "Investigate the Glumtooth Gang camp.", progress = "Can no let this camp stand. Too much to lose for kobold and earthen.", completion = "You see what Glumtooth Gang do? Even have earthen prisoner!" }
WordHunterWoW_QuestEN[80512] = { title = "Beat the Best", description = "If Glumtooth Gang succeed, this earthen first captive of many. We need free him.\n\nHe prize. Every kobold here want fight him. Must earn our place.\n\nYou beat up strong bugs, they think me strong trainer. Then they let you into ring.\n\nMay best bug win.", objectives = "Defeat the bug-trainers.", progress = "Beat other three contenders and we can rescue the earthen.", completion = "Nice work! You really fight like bug." }
WordHunterWoW_QuestEN[80513] = { title = "Snouty Sabotage", description = "You need good distraction to get earthen out. I need Glumtooth Gang stopped. Have perfect thing for both.\n\nSome fool mix Cinderbrew with candle wax in the Warrens. Candles burn normal at first, then boom. Big boom. Place around camp. Explosions good distraction for escape.\n\nWhile you at it, loosen some bug leashes. Let Glumtooth Gang see how scary bugs are.", objectives = "Place Cinder-Flash Candles and loosen bug leashes.", progress = "Boss Whiskerlash regret day he help turn kobolds to war.", completion = "Perfect, you have good distraction when time come. Can't wait." }
WordHunterWoW_QuestEN[80514] = { title = "Break out Berrund!", description = "You work good. Now they let you into ring to \"fight\" earthen. You go to ring when ready. Cinder-flash candles could go off any moment.\n\nI head back to camp. Wait for you and earthen there.\n\nYou good one. No get killed.", objectives = "Escort Berrund from the camp.", completion = "Captured? No, I was just gathering information. And I've got bad news." }
WordHunterWoW_QuestEN[80515] = { title = "Put the Shine On", description = "Hate to admit, but loud earthen right. Boss Whiskerlash have strongest bugs. But everything have weakness.\n\nSpiders afraid of light, and our friend very shiny. If we make him shinier, no spider want to fight.\n\nGlumtooth Gang been capturing candleflies. Free them and rub off some glow dust. We make big earthen big shiny!", objectives = "Free Candleflies and collect their luminescence.", progress = "This better not go to his head.", completion = "Yes, this perfect. With this he really gleam!" }
WordHunterWoW_QuestEN[80516] = { title = "Bump off the Boss", description = "That kobold knows her stuff. Scrit says Boss Whiskerlash has his own cadre of spiders in a cave nearby. Don't worry, I'll lead the charge. \n\nCome on, we've got a boss to take down.", objectives = "Slay Boss Whiskerlash.", completion = "You back! Berrund came back alone. Scrit worried.\n\nIt done then? Good. Glumtooth Gang no last long without leader." }
WordHunterWoW_QuestEN[80517] = { title = "Back to Where it Began", description = "<Zee-Zee is ready to head back to the Deepforge Golemworks.>", objectives = "Meet up with Brinthe and Dagran outside the Deepforge Golemworks.", completion = "Good, you're here. I hope you're ready, <name>." }
WordHunterWoW_QuestEN[80558] = { title = "Nothing Ventured", description = "These niffen have been down here a long time--long enough to build a village and set up trade with the nerubians. Some of them are even able to trade in that big nerubian city!\n\nThe goblins, though? They're from the Venture Company. No wonder General Anub'azal was skeptical of me, if he's used to dealing with them.\n\nWhat are they doing all the way down here? Let's try to learn what led them to this place.", objectives = "Learn what you can from the goblins in Mmarl.", progress = "Take a good look around for loose-lipped goblins.", completion = "At least they're willing to talk to you, even if they are rude. Maybe you can convince them working together is mutually beneficial.\n\nTry something a little... transactional. They'll appreciate that." }
WordHunterWoW_QuestEN[80562] = { title = "Blossoming Delight", description = "Few followers of the light would dare to attempt the dish I plan to make. A mix of traditional Imperial spices combined with the forbidden harvest of the nearby fungal blooms.\n\nThis dish will delight the palate and remind one of the adventurous spirit that founded the Hallowfall expedition.\n\nPlease journey to the Mycomancer Cavern nearby and harvest the blooms I require.", objectives = "Collect 20 Ever-Blossoming Fungi from Mycromancer Cavern.", progress = "Have you found all of the ingredients?", completion = "Now the magic happens. Please sample this creation for yourself." }
WordHunterWoW_QuestEN[80563] = { title = "Tool of Attunement", description = "The nerubians must have some means of cleansing themselves after Black Blood exposure. If they did not, they would not have been so successful in their harvesting operation.\n\nIf necessary, I can pick up on the harmony of this world with ease to restore my mind to this reality. But for your sake and Hannan's, we should probably obtain whatever it is they use.\n\nAlthough we can spare the trouble... if you don't mind the threat of forever splitting your consciousness between two realities.", objectives = "Find a Tuning Crystal.", progress = "The nerubians must have something on them to cleanse their minds after such direct proximity to the Black Blood.", completion = "A tuning crystal? Fascinating.\n\nThough I cannot say I'm too impressed with the solution. They brought this problem upon themselves, after all." }
WordHunterWoW_QuestEN[80564] = { title = "Field Research", description = "The nerubians are harvesting Black Blood nearby.\n\nIf allowed to persist, the corruption caused by excavating the veins may spread. It will continue until it consumes everything.\n\nI have no intention of sitting and waiting for it to taint the roots. I am trying to learn and understand their methods... so that I may strike at the heart of the operation.\n\nYou're welcome to join me.\n\nIf, of course, you would also prefer your world not to drown in oozing pools of Black Blood.", objectives = "Investigate the Black Blood harvesting site.", progress = "These disgusting pustules, the veins of corruption... this is only the beginning of the damage this horrific operation could cause.", completion = "Here in the center of all of this corruption, I hear something calling to me. It pounds in my head like a drum.\n\nI cannot just ignore it." }
WordHunterWoW_QuestEN[80565] = { title = "Resounding Repercussions", description = "I did not mean for...\n\n<Orweyna's eyes narrow.>\n\nFetch him, {name}. You were exposed to the Black Blood, too. But Hannan took most of it.\n\nHe has entered the Unseeming, his mind shifted to a realm beyond our eyes through exposure to the Black Blood. You may need to join him, however far in he ventured, to retrieve him.\n\nI will activate the nerubian cleansing instrument for when you return.\n\nDo not lose yourself in that altered state.", objectives = "Retrieve Hannan from the Abandoned Harvest Site inside the cave.", progress = "Is this real? Am I imagining the monsters?", completion = "My head... It hurts. Everything feels so cloudy and... Help, please!" }
WordHunterWoW_QuestEN[80566] = { title = "Enemies Abound", description = "<Hannan is barely responsive and less corporeal than he should be, lost deeper in the Unseeming than you.>\n\nSome of the canisters exploded... Then the spiders appeared.\n\nKill the--kill the spiders!", objectives = "Find and kill the spiders.", completion = "Hmm. I have noticed you seem good at surviving challenging tasks. I will remember this about you." }
WordHunterWoW_QuestEN[80567] = { title = "Song of Restoring", description = "<Orweyna looks relieved at the sight of Hannan, but does not seem dissuaded from her task.>\n\nI cannot say I am surprised at what you found in that cave. Nerubians stuck in the Unseeming, trapped in a realm of monsters and madness...\n\nI would pity them, but they sought this out.\n\nYou, however, need to shift back before the influence of the Black Blood becomes too strong on your mind.", objectives = "Use the Harmonizing Instrument.", progress = "It is a relief that the tuning crystal we found worked on this strange instrument. For once we should be grateful for the ingenuity of the nerubians.\n\nIf this device had not worked, we may have been stuck in the Unseeming forever. Like the nerubians in the cave.", completion = "She can't keep running off like this! The rest of us followed her here--against our better judgement I might add--but we never agreed to...\n\n<Hannan sighs.>\n\nNo, we knew exactly what we were getting into with her. And the... consequences." }
WordHunterWoW_QuestEN[80568] = { title = "Leave No Trace", description = "I need to go make sure she's all right. What I saw in that cave... If she's more sensitive to this...\n\n<Hannan nearly growls.>\n\nBut she's making a mess out here, drawing attention and leaving a trail leading outsiders right to her! Right to us.\n\nWe're supposed to be subtle. Unseen. Keep to the brush, hide in our other forms as much as possible.\n\nI hate to ask this of you, but can you use my scythe to take care of the evidence while I check on her?", objectives = "Collect 10 Magic Traces into Hannan's Scythe.", completion = "It's forbidden for me to talk to outsiders, but... you have been helpful.\n\nThank you for aiding me with this burden." }
WordHunterWoW_QuestEN[80569] = { title = "Harmonious Approach", description = "I know I cannot stop Orweyna from going down there and drawing attention to our presence.\n\nBut... perhaps we could stop word of our presence from spreading.\n\nFind whoever is in charge of this harvest site. And... do what is needed to ensure they can't spread the word.", objectives = "Kill Harvest Warden Izk'tilak.", progress = "I'm not going to leave her down here alone. But we have to be cautious. We must deal with anyone who sees us.", completion = "I will admit, I am glad to have had you with us through all of this." }
WordHunterWoW_QuestEN[80570] = { title = "Staunch the Flow", description = "Do they even understand what they are doing?\n\n<Orweyna bares her teeth, practically growling.>\n\nDestroy as many of those extractors as you can. Shatter the bulbs, snap the limbs, burn the wreckage.\n\nWe cannot stop them all, not today. But a bit of destruction may temper my rage.", objectives = "Destroy 8 Extractors.", completion = "They have already done so much damage. The creatures that once lived here, the earth that once thrived...\n\nIf we cannot stop them, we will take vengeance for that which they've destroyed beyond repair." }
WordHunterWoW_QuestEN[80571] = { title = "Decipher the Cacophony", description = "This is far worse than I thought. It's as if they're feeding the corruption. Encouraging it. The dissonance growing louder and louder...\n\n<Orweyna seems shaken, but not deterred.>\n\nI can hardly hear anything else. My head is pounding. I... I need to see how far gone this land truly is.\n\n{name}. Bring me something from the Unseeming.", objectives = "Collect 10 Discordant Essence from Discordant enemies in the Unseeming.", progress = "What have the nerubians done to this place?", completion = "This is wrong. This is all wrong." }
WordHunterWoW_QuestEN[80572] = { title = "Discordant Measures", description = "I cannot stand to look at this any longer. I must act.\n\n{name}. You have survived the Unseeming before. Now we must go there together. I must see it for myself if I am to believe this vile place truly cannot be cleansed.\n\nWe will kill what we can and search for some sliver of hope that we can still restore this land.", objectives = "Acquire 50 stacks of Unseeming Shift and collect 3 samples from elite enemies lost in the Unseeming.\n\nIn addition to destroying extractors, you can also acquire Unseeming Shift by standing in pools of Black Blood. However, be careful as you will gain stacks quickly by doing so.", progress = "Hannan's concerns are not unfounded.\n\nBut I cannot simply witness this corruption and make no attempt to root it out.", completion = "<Orweyna's voice is low with rage, but you see it is heartbreak shining in her eyes.>\n\nThis place is truly too far gone. There is no fixing what they have done here." }
WordHunterWoW_QuestEN[80573] = { title = "Dropping Eaves: Spoils of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[80576] = { title = "Listener Lost", description = "Blast it all! \n\nBrennok and I were on our way to Shadowvein Point to conduct a recitation ceremony. We were attacked by scorpids. Now the hauler has a scorpid stinger lodged in its gears, and Brennok wandered off.\n\nHe said he was going to stretch his legs while I fixed the hauler, but that was a while ago. I need to get the bot moving again, can you look for him?", objectives = "Find Brennok.", completion = "You don't understand, I was going to leave the Ringing Deeps. But I can't now, not without my book!" }
WordHunterWoW_QuestEN[80577] = { title = "Readying the Recitation", description = "Once a year, Brennok and I take the long road through The Ringing Deeps. \n\nWe stop at each outpost, and Brennok tells the residents a story from their past. One they entrusted to him to remember, even when they forget. \n\nIt's my duty to ready the ceremony site. Would you come with me? I could use the help.", objectives = "Prepare the recitation site.", progress = "Brennok usually seems more excited for a recitation.", completion = "Thank you. I hope you'll join us for the recitation when the time comes." }
WordHunterWoW_QuestEN[80578] = { title = "The Common Costume", description = "I'll slip away after the recitation. It's easy to vanish in a crowd of earthen enjoying a keg of cinderbrew.\n\nHowever, I can't be recognized when I leave town. I don't want anyone to stop me. Or worse, to think I'm abandoning my oath. Better to just disappear.\n\nIf you find me a spare set of Miner's Clothes, I'll be able to get away without being noticed.", objectives = "Find a spare set of Miner's Clothes.", progress = "Did you find them yet?", completion = "Thank you. No one should recognize me in these." }
WordHunterWoW_QuestEN[80592] = { title = "Forge a Pact", description = "Let us renew your Pact.\n\nRemember, you may only enter a Pact with one of the Severed Threads at a time. These contracts are temporary, though, so you will have many opportunities to prove yourself to all three.", objectives = "Choose a Severed Threads Pact.", completion = "May your chosen patron favor you, as you have them." }
WordHunterWoW_QuestEN[80593] = { title = "A Sip of Cinder", description = "Now there's one last thing we need. It wouldn't be a proper recitation ceremony without mead. \n\nHowever, Hearthkeeper Zirc tells me the last couple deliveries of cinderbrew haven't arrived. It seems the local flayers in the Rumbling Wastes have a taste for it and raid the shipments.\n\nHere, take a spare keg. See what you can recover from the flayers.", objectives = "Fill a keg with Cinderbrew Mead.", progress = "Careful out there, flayers are already dangerous enough. I wouldn't want to meet one that's been guzzling cinderbrew.", completion = "Thank you, the miners will appreciate this. I hope the flayers weren't too much trouble." }
WordHunterWoW_QuestEN[80670] = { title = "Eyes of the Weaver", description = "The Weaver's many eyes lurk throughout the city, learning as much as they can about Ansurek's machinations.\n\nStill, intelligence enough will not be sufficient to turn the tide against the Sureki forces. The Weaver requires someone willing to get their hands dirty.\n\nLucky you, I suppose.", objectives = "Continue your efforts in aiding the Weaver in Azj-Kahet.", progress = "Chk-chaah! You return at least. What news of the city do you bring me, hrm?", completion = "You have big talent for causing good trouble! Good good!\n\nTake these!" }
WordHunterWoW_QuestEN[80671] = { title = "Blade of the General", description = "Even now, General Anub'azal's forces work tirelessly to ensure the security of Azj-Kahet.\n\nAnsurek's reach extends to every corner of her domain. The General seeks to undermine her military authority. If we stretch her resources thin, then we may find new opportunities to strike.", objectives = "Continue your efforts in aiding the General in Azj-Kahet.", progress = "Hrmph. It is about time that you've returned. What news?", completion = "You have returned alive, and the enemies of Anub'azal have not. \n\nThat is cause enough for recognition!" }
WordHunterWoW_QuestEN[80672] = { title = "Hand of the Vizier", description = "The Vizier works even now to spread our conspiracy's influence amongst the well-to-do of Azj-Kahet's elite. Given his position, though, he can offer little in the way of direct support.\n\nThat is where you come in. Your growing reputation precedes you; you can move in ways that the Vizier cannot. Just take care not to get eaten, hrm?", objectives = "Continue your efforts in aiding the Vizier in Azj-Kahet.", progress = "I fear that our task grows more arduous with each passing day. I hope you are not wasting time.", completion = "Thanks to your efforts, the Vizier is one step closer to parity with the enemy. \n\nFor that, thanks are necessary." }
WordHunterWoW_QuestEN[80673] = { title = "Runway Scare-a-way", description = "'Lo there.\n\nMe and Mags are generally in charge of clearing the sky in this area during our Lamplighting route. If we don't cull the moths in the area, they start spreading up towards the skydocks and start laying eggs in the machinery of our ships.\n\nUnfortunately we're not as spry as we used to be. Could you lend a helping hand? They're pretty frail so they'll squish easily to any high velocity flight. Or you could just smack 'em the old-fashioned way.", objectives = "Kill 25 moths either by flying through them or killing them normally.", progress = "Nasty critters...", completion = "Kill one of 'em and four more somehow pop up. Well, this will help. We can take care of the rest." }
WordHunterWoW_QuestEN[80676] = { title = "Defragmenting Memory", description = "My oath is to be a compiler. I collect and tell the stories of our people.\n\n<Brennok sighs.>\n\nIs there wisdom in stories told by someone who never lived them? I've never had an adventure. I was afraid to overwrite the stories entrusted to me.\n\nSo I started transcribing them into a book I hid here. Each time we returned to Shadowvein Point, I added more.\n\nI was going to leave and pass on the book, but scorpids ransacked it. Please, find the missing pages before they stuff them into their nests.", objectives = "Collect 100 Missing Pages of Brennok's book.", progress = "Thousands of stories, now they're probably lining some animal's den...", completion = "By the Titans, thank you! I don't know what I would have done if I'd lost these. \n\nI can finally leave without failing my oath." }
WordHunterWoW_QuestEN[80677] = { title = "Torching Lights", description = "No matter how many moths we swat, if we don't take care of the eggs they'll just continue to be a problem. \n\nTake this firearm, use it to torch some of the eggs on the top of the mire's canopy.", objectives = "Torch 15 moth eggs.", progress = "Watch the torch trigger, it's an older piece.", completion = "You would think they would learn to stay away from here. Yet they always come back." }
WordHunterWoW_QuestEN[80678] = { title = "Time Lost", description = "Now that the job's done -- one thing I've always done on this route is muck around for some of the valuables that fall from the docks. As things get moved onto ships small items can fall off. Sometimes people chuck 'em for luck or in rage, and the like.\n\nBut some of those items have memories in 'em. Things so precious that losing it might as well be losing part of your heart. If you could help me look I'd be grateful.", objectives = "Find 6 lost mementos.", progress = "What'd you find?", completion = "That's quite a haul. Take a few of these with you. Mayhaps you can find the owner of 'em." }
WordHunterWoW_QuestEN[80679] = { title = "Stuffed Lynx Toy", description = "That item in your pack looks familiar...", objectives = "That item in your pack looks familiar...", progress = "That item in your pack looks familiar...", completion = "Mr. Skinny! I thought you were lost forever!" }
WordHunterWoW_QuestEN[80680] = { title = "Tarnished Compass", description = "<The name on the compass from the Stagnant Mire matches one engraved in the epitaph of the community gravestone.>", objectives = "<The name on the compass from the Stagnant Mire matches one engraved in the epitaph of the community gravestone.>", progress = "<The name on the compass from the Stagnant Mire matches one engraved in the epitaph of the community gravestone.>", completion = "<The world is silent save for the distant hum of airships. \n\nDespite the damage left by time and nature, the needle still points towards Beledar.>" }
WordHunterWoW_QuestEN[80681] = { title = "Broken Bracelet", description = "What is it you have there?", objectives = "What is it you have there?", progress = "What is it you have there?", completion = "That is... \n\n<Keyrra carefully places the bracelet in her palm.>\n\nI can't believe it." }
WordHunterWoW_QuestEN[80682] = { title = "One Last Story", description = "Well, it's time. I'll be holding the recitation at the mine entrance. I'll see you there, though don't feel obligated to stay the whole time.\n\nI'll leave my book for Haimaz to find. She'll take care of it.\n\nAfter the ceremony, I would like to say goodbye properly. Meet me by the bridge outside of town. I'll head there after the recitation.", objectives = "Attend the recitation.", completion = "I knew Brennok was acting odd. Then one of the miners mentioned you'd borrowed a spare set of clothes. That and his strange mood, well, it wasn't hard to guess that he planned to leave.\n\nI expected him to come this way, though. Have you seen him?" }
WordHunterWoW_QuestEN[80684] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[80685] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[80687] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[80689] = { title = "Tending to Ausgazur", description = "Assigned tasks complete! I'll check back on these folks on my next scheduled patrol.\n\nThere is one more earthen I must tend to today. He was... he is very special to me.\n\nYou've been an especially considerate colleague, so I'd like for you to see him. Let us travel west a bit, closer to the falls.", objectives = "Meet Batzvara in Shimmermist Falls.", completion = "You made it! \n\n<She looks at the outstretched hand of the earthen next to her and sighs.>\n\nI admit that I am quite disturbed by what I've found here. Your presence is a comfort." }
