WordHunterWoW_QuestEN[81510] = { title = "Ship It!", description = "What a haul! I was able tae give a bit of what we found tae Dagran so he could finish off one of his projects. He should be here any minute. \n\nAh, I can't hold back. Surprise! It's a gift tae help you get around.", objectives = "Speak with Brann Bronzebeard", progress = "Wait 'till ye see what Dagran has cooked up.", completion = "You'll be able tae use this machine tae move around Khaz Algar. We'll let ye know when we have more parts for it!\n\nNow that we've got that out of the way, we got some delves tae explore!" }
WordHunterWoW_QuestEN[81512] = { title = "Props and Incense", description = "", objectives = "" }
WordHunterWoW_QuestEN[81514] = { title = "Bountiful Delves", description = "We're going tae need lots of resources to fight off Xal'atath. Lucky for you, we've uncovered a source!\n\nSome delves we've found are \"bountiful\" on account of the baddies there hoardin' more treasure. This treasure can only be unlocked with special keys found throughout Khaz Algar.\n\nKeys and key fragments can be found all about the world. Hunt them down and dive into a bountiful delve!", objectives = "Complete Special Assignment World Quests, World Activities, or Weekly Quests to recover a Restored Coffer Key or Coffer Key Shards to unlock a chest within a Bountiful Delve.", progress = "Did ye find the key yet?", completion = "That was quite the haul! Up for a little more fun?" }
WordHunterWoW_QuestEN[81555] = { title = "Wet Work: Tithe to Kill", description = "", objectives = "" }
WordHunterWoW_QuestEN[81556] = { title = "Foreign Fog", description = "Pleasure to meet you, adventurer. I wonder if you might be willing to help me with some research?\n\nI'm sure you've noticed the fog beasts that have recently started encroaching upon this area. \n\nPeople see them as a bad omen, they always seem to show up during periods of ecological imbalance. I disagree with this assertion. \n\nStill as an expert in all vapor-based magics, I've been hired to find out where they're coming from so they can be cut off at the source.", objectives = "Place the fog collector and collect fog samples from different areas occupied by fog beasts.", progress = "Have you collected the fog samples?", completion = "Excellent! I'll start evaluating these samples right away." }
WordHunterWoW_QuestEN[81557] = { title = "Fog Tags", description = "While I analyze these fog samples, I have another task for you.\n\nMy employers have asked me to figure out where these fog beasts are coming from. I've developed these trackers. If you could, please attach them to an assortment of fog beasts.   \n\nYou'll have to get close, so... be careful. Hopefully they don't mind it too much!", objectives = "Attach trackers to fog beasts in and around Taelloch.", progress = "Have you attached all the trackers?", completion = "You've attached the trackers? Perfect! Did they attack you? No? Interesting... This is all so interesting..." }
WordHunterWoW_QuestEN[81558] = { title = "Unnatural Predators", description = "It would be no use tagging fog beasts to study if they all were to die, would it? \n\nCould you clear out some of the aggressive deepflayers that have flocked to feast on the fog beasts?\n\nThey'll ruin my data if left unchecked, I'm sure of it.", objectives = "Kill Deepflayer Hunters.", progress = "Have you taken out the deepflayers?", completion = "Thank you. A researcher's duty is  to not interfere with nature, but... I only have so many trackers. \n\nI can't risk losing them to a bored, murderous deepflayer. No other reasons certainty. Hehe!" }
WordHunterWoW_QuestEN[81559] = { title = "Fog Follower", description = "With the trackers attached, we should be able to find out where the fog beasts are coming from. The trackers leave a residue in the air. It's invisible to the naked eye, but I can use the mists to reveal it in places where there's a high enough concentration.\n\nTheoretically, this should lead us to the places they most frequent. Maybe a nest! That I'll then have to report to my employer... hm.\n\nAnyway. Let's see what we can find.", objectives = "Help Noli find the source of the fog beasts with her mist tracking ability.", progress = "I know we'll be able to find them. Let's keep looking!", completion = "Wow. I mean, wow! We learned so much in so little time! But now, I'm supposed to report this to people who want them gone?\n\nI think people are wrong about the fog beasts. They don't attack unless threatened. And even when we entered their nest, they teleported us away safely. \n\nWe haven't even had time to talk about the fact that they can do that kind of magic! Amazing!" }
WordHunterWoW_QuestEN[81560] = { title = "Winter's Presents", description = "I hear Greatfather Winter has put presents for everyone under the tree in Ironforge.\n\nYou should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.", objectives = "Speak with Greatfather Winter. He is located near the Smokywood Pastures vendor area in Ironforge.", completion = "Oh, ho hello there! You can only be here for one reason: to open your Winter Veil presents.\n\nNow, don't you worry, Greatfather Winter hasn't forgotten about his favorite <race> <class>. Look under the tree and you'll find your gifts.\n\nDuring this season of giving, perhaps your friends would also enjoy receiving some of Smokywood Pasture's excellent products?" }
WordHunterWoW_QuestEN[81561] = { title = "Winter's Presents", description = "I hear Great-father Winter has put presents for everyone under the tree in Orgrimmar.\n\nYou should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.", objectives = "Speak with Great-father Winter. He is located near the Smokywood Pastures vendor area in Orgrimmar.", completion = "Oh, ho hello there! You can only be here for one reason: to open your Winter Veil presents.\n\nNow, don't you worry, Great-father Winter hasn't forgotten about his favorite <race> <class>. Look under the tree and you'll find your gifts.\n\nDuring this season of giving, perhaps your friends would also enjoy receiving some of Smokywood Pastures' excellent products?" }
WordHunterWoW_QuestEN[81564] = { title = "The Story of Noodles", description = "Ah, being here again makes me hungry. Have I ever told you about the time I learned to cook from Sungshin Ironpaw?\n\nPerhaps you can experience it for yourself. Say the word and I will take you to a version of this timeline where you--yes YOU--ran your own noodle stand!\n\nIt all began with the Lin family's secret recipe...", objectives = "Talk to Grandmaster Jakkus to complete the scenario Finding the Secret Ingredient.", progress = "Mmm, noodles...", completion = "So you see <name>, the secret ingredient wasn't in the food at all--it was the service that made those noodles special.\n\nLet me know when you want to talk noodles again." }
WordHunterWoW_QuestEN[81565] = { title = "Another Round of Noodles", description = "Back again for more noodles?\n\nVery well, say the word and I will take you back to a version of history where you ran your own noodle stand.", objectives = "Talk to Grandmaster Jakkus to complete the scenario Noodle Time.", progress = "Perhaps I should have stayed a cook and not done so much other training...", completion = "Delicious work, <name>! You're a noodle natural!" }
WordHunterWoW_QuestEN[81568] = { title = "Release the Beasts", description = "", objectives = "" }
WordHunterWoW_QuestEN[81574] = { title = "Sporadic Growth", description = "Fungal growths are still spreading unchecked from the nearby Mycomancers' cavern. The latest surge has sent all my recruits fleeing in fear.\n\nI urgently need your skills in eliminating one troublesome fungal growth.\n\nTake my Patrol Torch and eradicate Gloomsprout and the surrounding growths that sprouts from it. The torch should handle the smaller stuff, but Gloomsprout will require a more direct approach", objectives = "Slay Gloomsprout and 15 Gloomgrowth using the Patrol Torch.", progress = "Have you eliminated the threat?", completion = "Excellent work, have you considered the possibility of a career in the Arathi Military?" }
WordHunterWoW_QuestEN[81587] = { title = "Noodle Time: Bonus", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[81593] = { title = "Maximum Potential", description = "We've got plenty tae do in delves. We'll have tae get stronger if we're going to tackle everything that's in there!", objectives = "Help Brann Bronzebeard reach level 10.", completion = "I'm feelin' stronger already!" }
WordHunterWoW_QuestEN[81595] = { title = "Seasonal Start", description = "We've uncovered loads of new treasures tae find in delves! \n\nThere's no time tae wait. Let's get ye set up with the basics so you can get out there!", objectives = "Review rewards offered by Reno Jackson, Sir Finley Mrrgglton, and the Delver's Guide.", completion = "Nothing like some good treasure hunting! We're going tae need it.\n\nEh? Looks like someone is coming over in a rush." }
WordHunterWoW_QuestEN[81596] = { title = "Delve Hunter", description = "A few of our explorer's have come back battered and bruised from delves. They speak of a terrible monster called Zekvir. \n\nPerhaps you've heard of this creature? Allow me to tell you more of what we've learned.", objectives = "Discover more about Zekvir, Hand of the Harbinger.", completion = "This Zekvir sounds like bad news. We'd better prepare ourselves." }
WordHunterWoW_QuestEN[81609] = { title = "What About the Children?", description = "Greetings {name}. As I'm sure you're aware, there are many children across Azeroth without families to look after them. Children's week is a time to recognize their plight and give hope to those children. Will you go to them?", objectives = "Talk to Orphan Matron Nightingale in Stormwind or Ullna in Dornogal.", completion = "Welcome, <class>. Are you here to help the children?" }
WordHunterWoW_QuestEN[81610] = { title = "What About the Children?", description = "Greetings {name}. As I'm sure you're aware, there are many children across Azeroth without families to look after them. Children's week is a time to recognize their plight and give hope to those children. Will you go to them?", objectives = "Talk to Orphan Matron Battlewail in Orgrimmar or Ullna in Dornogal.", completion = "Welcome, <class>. Are you here to help the children?" }
WordHunterWoW_QuestEN[81613] = { title = "Let's Not Worry Her", description = "Right, we better get back to Haimaz before she gets suspicious.\n\nPlease, don't tell her about any of this. Her duty is to guide and guard me in my role as compiler. \n\nIf she knew I was planning to leave... I don't know what she would do.", objectives = "Return to Haimaz in Shadowvein Point.", completion = "Thank you for bringing him back. He always acts strange when we come to Shadowvein Point, but he seems more out of sorts than usual." }
