WordHunterWoW_QuestEN[81632] = { title = "Lizard Looters", description = "Despite the punishment of our posting here, life isn't entirely unpleasant. Captain Lancekat left us a generous supply of provisions. \n\nWell, at least she did until recently. A sizable lizard has made off with our camp supplies!\n\nCould you recover our camp supplies and deal with the pilfering thief?", objectives = "Slay Reekscale and recover 8 Camp Supplies.", progress = "Did you find the supplies?", completion = "Fine work, we'll drink to your success as we feast on these supplies." }
WordHunterWoW_QuestEN[81638] = { title = "Home Is Where the Hearthstone Is", description = "", objectives = "Welcome to our humble village.\n\nI can give you a hearthstone to return here if you ever need a place to rest." }
