WordHunterWoW_QuestEN[81640] = { title = "Tenir and the Order of Night", description = "<A script for an epic stage play. Stage Manager Huberta on the Isle of Dorn may have interest in this.>", objectives = "Deliver this to Stage Manager Huberta on the Isle of Dorn.\n\nProvided item:", completion = "Very interesting, I will add this to my collection of unread submissions." }
