WordHunterWoW_QuestEN[81748] = { title = "Aid the Sunreavers Onslaught", description = "", objectives = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", progress = "My scouts report enemy activity. Have you any supplies to bring fortune to our troops?", completion = "Very good, we shall ready a counterattack." }
WordHunterWoW_QuestEN[81749] = { title = "Aid the Kirin Tor Offensive", description = "", objectives = "There will be no victory without bloodshed. Have you brought aid, <class>?", progress = "There will be no victory without bloodshed. Have you brought aid, <class>?", completion = "I will add these to the coffers." }
WordHunterWoW_QuestEN[81750] = { title = "Cloud Farming", description = "", objectives = "" }
WordHunterWoW_QuestEN[81751] = { title = "Fire and Gemstone", description = "What's this? A tinderbox? \n\nI've heard tell of these Arathi contraptions, but have never held one in my hands. It's smaller than I would have thought...\n\nUpgraded, you say? Ha! We can do that. The next time we're Awakening the Machine, keep an eye out for an Awakened Cog and Ringing Gemstone.", objectives = "Acquire an Awakened Cog and a Ringing Gemstone from Awakening the Machine.", progress = "Have those items for me?", completion = "You've got them! Cogs be praised and gears be ground, let's see what we can do with this magical little doodad of yours." }
WordHunterWoW_QuestEN[81767] = { title = "Scrounge that Scrap!", description = "", objectives = "" }
WordHunterWoW_QuestEN[81793] = { title = "Sparks of War: Isle of Dorn", description = "Powerful creatures are causing havoc across the Isle of Dorn. \n\nGet out there and clear things up!", objectives = "Collect 100 Sparks of War in Isle of Dorn, while in War Mode.", progress = "Best time to start is now.", completion = "Our watch can finally continue without obstruction. Many thanks." }
WordHunterWoW_QuestEN[81794] = { title = "Sparks of War: The Ringing Deeps", description = "Unseen forces have overrun multiple Earthen outposts. \n\nSeek them out and cleanse the deeps.", objectives = "Collect 100 Sparks of War in The Ringing Deeps, while in War Mode.", progress = "How goes the recovery?", completion = "You survived the deep well!" }
WordHunterWoW_QuestEN[81795] = { title = "Sparks of War: Hallowfall", description = "The light beneath is fickle, but it will save you from the dark if you master it.\n\nGo. Travel to Hallowfall, and lend your strength to the Arathi.", objectives = "Collect 100 Sparks of War in Hallowfall, while in War Mode.", progress = "Be wary of the dark.", completion = "The Arathi people now have a moment of peace, thanks to you." }
WordHunterWoW_QuestEN[81796] = { title = "Sparks of War: Azj-Kahet", description = "We've received strange readings coming Azj-Kahet.. Investigate these locations, but stay vigilant.", objectives = "Collect 100 Sparks of War in Azj-Kahet, while in War Mode.", progress = "Go off and complete your investigation.", completion = "YOU SURVIVED? And with all your limbs no less. Well done." }
WordHunterWoW_QuestEN[81797] = { title = "Targeted Recon", description = "If you've spent much time in Hallowfall, no doubt by now you've run across the foul magic of the kobyss. Reports that their illusions have been evolving are fiercely debated within the Arathi Army.\n\nYour outside perspective is just what I'm looking for. Venture to the Sunless Strand, slay a few of their illusory assassins, and then report your findings. You'll likely find them hiding in the shadows.", objectives = "Slay three Kobyss Shadeshapers in Sunless Strand.", completion = "Their illusory projections of Arathi civilians sound convincing as ever. I struggle to understand how such vicious and undiplomatic creatures can emulate Arathi mannerisms so well.\n\nNonetheless, this is all in line with our current understanding of the kobyss. Your report shall be put to good use. Thank you, outsider." }
WordHunterWoW_QuestEN[81798] = { title = "Return to Moira", description = "Speaker Brinthe's impulsiveness is getting the better of her. \n\nYou'd best return to your comrades and let them know of her intentions!", objectives = "Return to Moira in the Earthenworks.", completion = "<name>! You're back. Let us end this charade." }
