WordHunterWoW_QuestEN[81869] = { title = "Can Catch More Fires with Honey", description = "Crafting with flame demands a fuel that burns pure and has sustainable power. Among these, the honey created by Cinderwold bees stands out! A source of elemental fire, organic and untainted.\n\nI've longed for a supply of this honey, yet never had the chance to procure it. \n\nTake my harvesting device and gather a quantity for our purpose. We shall infuse it into your tinderbox. Exercise caution, for some of the earthen revere these bees as sacred creatures.", objectives = "Collect 10 Pure Fire Honey from the Overladen Drones in Cinderwold.", progress = "Have you acquired the honey?", completion = "So sweet and the flame jumps from it even now. This should make an excellent fuel for your tinderbox!" }
WordHunterWoW_QuestEN[81886] = { title = "For the Alliance", description = "For the first time in our history, the outside world is ours to explore and experience.\n\nAn off-island faction known as the Alliance came to the aid of our kin. Valiant and wise, the stalwart Alliance has extended an open hand to our people.\n\nWill you be among the first to accept and visit their lands, learn their histories and walk amongst their people?\n\nIf that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", completion = "Well, here we are! Another <race> from... Khaz Algar, is it?\n\nA couple of Wildhammers sent word that some of your people might be coming to visit.\n\nWell, make yourself at home here in town. The Alliance welcomes all of its new friends with open arms. \n\nWelcome to Stormwind!" }
WordHunterWoW_QuestEN[81887] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who appreciates fine stonework! We have many impressive stone buildings and walls.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "Talk to Chromie in Stormwind City.", progress = "Greetings, <name>.", completion = "Welcome to Stormwind. Acclimate yourself and learn all you can.\n\nOur experiences will be invaluable to the Archives back in Dornogal." }
WordHunterWoW_QuestEN[81888] = { title = "For the Horde", description = "For the first time in our history, the outside world is ours to explore and experience.\n\nAn off-island faction known as the Horde came to the aid of our kin. Spiritual and mighty, the honorable Horde has opened their hand to our people.\n\nWill you be among the first to go where no earthen has ever gone? To walk their lands, hear their songs and learn from their people?\n\nIf that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", objectives = "Meet with Ambassador Blackguard at the Orgrimmar Embassy.", completion = "What's this then? An... <race>? I heard we might be seeing some of your people here.\n\nWell, make yourself at home if you can. \n\nWe have plenty of rocks in this sweltering place, so I guess if that's your thing...you'll do just fine.\n\nJust...don't eat the rocks. Do you even eat rocks?\n\nEither way, welcome to Orgrimmar." }
WordHunterWoW_QuestEN[81889] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "Talk to Chromie.", progress = "Greetings, <name>.", completion = "Welcome to Orgrimmar. Acclimate yourself and learn all you can.\n\nOur experiences will be invaluable to the Archives back in Dornogal." }
WordHunterWoW_QuestEN[81890] = { title = "Unfulfilled Requests", description = "I have heard the citizens of the Silken Ward are having trouble with a group of Ascended called the Pale Weavelashers.\n\nThe new ward is supposed to be a fresh start for citizens of the capital, at least that is the way the Queen tells it. In actuality it is a way for her to tighten her grip on those she distrust. \n\nMeet with my assistant Sum'latha. I sent her there ahead of time to gather information. She can fill you in on any details.", objectives = "Meet with Sum'latha at the Silken Ward.", completion = "You must be the help the Vizier sent. Welcome to the Silken Ward." }
WordHunterWoW_QuestEN[81896] = { title = "New and Improved", description = "I've completed the modifications. I must say, this is some of my finest work! \n\nDespite its modest design, a bit of cog grease and elbow dust has transformed it into a device that even the surliest of the flame worshippers could appreciate.\n\nIf any of them want to know how it's done, send them my way.", objectives = "Accept the new improved Tinderbox from Kuldas.", completion = "The fire of this tinderbox will now burn brighter than ever!" }
WordHunterWoW_QuestEN[81906] = { title = "Whispers from the Web", description = "Hey! Hey!\n\n<The girl waves her arms to get your attention, a scrap of paper clutched in one hand.> \n\nYou won't believe me, but I found the cutest, fuzziest puppy! With a bell! Around its neck!\n\nIt gave me this to give to you. Take it, I gotta go catch that puppy!\n\n<The missive is written in elegant script, calling you to Azj-Kahet.>", objectives = "Meet with Ct'nak in the Burrows of Azj-Kahet.", completion = "I see my message reached you. You are... not quite as imposing as I had imagined, but rumor has it that your skills are unmatched." }
WordHunterWoW_QuestEN[81908] = { title = "A Flame in the Dark", description = "Contained within the Underkeep lies a tinderbox, once belonging to the late Aelric Leid.\n\nThis item reeks of powerful, corruptive energy. Its close proximity has leeched out to touch many nerubians.\n\nYour task is to retrieve that box and deliver it to me. To be safe, gather any tinderboxes you may find--we'll destroy them all, just in case.", objectives = "Search various containers inside the Underkeep for 8 Unidentified Tinderboxes and Aelric's Corrupted Tinderbox.", progress = "Did you find the tinderboxes?", completion = "Quickly, give it to me--we should not allow it to be seen in public!" }
WordHunterWoW_QuestEN[81909] = { title = "Absolute Power", description = "The dark allure of this item surpasses my initial expectations. I can sense a surge of power coursing through me. \n\nWe must delve deeper into its mysteries.\n\nHowever, it is unwise to discuss this matter openly. Follow me inside, where we may deliberate further.", objectives = "Discuss the tinderbox's destruction with Ct'nak.", progress = "What's that you have there?", completion = "This is most unexpected. Where on earth did you find it?" }
WordHunterWoW_QuestEN[81910] = { title = "A Great Responsibility", description = "To witness such corruption is deeply unsettling. \n\nDespite the dark energies intertwined with this tinderbox, there remains a flicker of the Sacred Flame, struggling to escape. I will not destroy that flicker, champion. \n\nYet I dare not hold onto it any longer. \n\nPerhaps your purity of spirit can withstand the darkness it holds. Please, {name}, carry it with you. Protect that small spark of purity, and help it break free of the dark magic that ensnares it.", objectives = "Accept the tinderbox.", completion = "I place in your care this small ember of hope, along with the weighty responsibility to safeguard it." }
WordHunterWoW_QuestEN[81912] = { title = "Flight Training 102", description = "Dunnae think I had nae noticed those rooks spittin' lightnin'. Sure beats tossin' hammers. But it won't mean nothin' if the Stormriders can't hit what they're fightin'.\n\nLet's test their aim. Got some gnomish contraptions here that'll project easy targets for practice. Take Shraubendre back out there an' show them how it's done!", objectives = "Help Kurdran train recruits in aerial targeting.", progress = "Flyin' takes a firm hand. An' boy do these earthen have that!", completion = "Now, that's the stuff! Did a real number on those projectors. But what we really need is a movin' target." }
WordHunterWoW_QuestEN[81913] = { title = "Flight Training 103", description = "These recruits seem tae be up for a challenge. Let's find them somethin' with a little bite!\n\nI saw a poor giant just off shore bein' pestered by a swarm of flying devils. Let's see if these rooks can shoot the wings off 'em an' provide some relief.\n\nYou and Shraubendre are settin' a good example for the rest. Keep it up!", objectives = "Help Kurdran train recruits in aerial combat.", completion = "The training went well, did it? I'm sorry I wasn't there for it. There was just something I had to do." }
WordHunterWoW_QuestEN[81914] = { title = "Dhar Oztan", description = "I love the stormrooks. Taking care of them was my directive, so they're all I've ever known. But even so, there are questions about them that even I don't have answers to.\n\nBaelgrim--Stormward Baelgrim--he was the expert. I'd pester him about them at every opportunity. And he shared what he could.\n\nHe told me once about summoning rooks at Dhar Oztan. It's an old Stormrider outpost that predates the Stormperch. If you want to know more about stormrooks, that's where we need to go.", objectives = "Travel to Dhar Oztan.", completion = "So Baelgrim is gone. And now others have come. You mean to summon more rooks, don't you?" }
WordHunterWoW_QuestEN[81915] = { title = "Home to Roost", description = "You've already done us a great service here, {name}. We will carry on by the example you have set.\n\nYou should return to Dhar Oztan and see to these new Stormriders you've recruited. They will undoubtedly benefit from the same diligence you have shown here.\n\nAnd, you can get away from these two and their posturing. I envy you, {name}...", objectives = "Return to Dhar Oztan.", completion = "It's good to have you back. Did all go well with the ground forces?\n\nWe're just about ready to start flight training here." }
WordHunterWoW_QuestEN[81928] = { title = "The Voice of the People", description = "As you might have heard, things haven't gone as intended for the citizens of the Silken Ward. The Pale Weavelashers have been keeping a tight grasp on the citizens. \n\nI wasn't able to find much before an Ascended kicked me out for snooping around. You are a fresh face, go around the Silken Ward and speak to the citizens, see if you can find a way to help them.\n\nAlso seek out Alchemist Talbax. I heard his name spoken a few times. He could be a useful contact.", objectives = "Speak with 3 Silken Ward citizens.", progress = "The Silken Ward was supposed to be a new start for these people. Let's see what we can do to help.", completion = "Ah so you have heard about my recent troubles, friend. You may be able to help." }
WordHunterWoW_QuestEN[81929] = { title = "Here's the Plan", description = "{name}, the time has come to deal with the nerubian army. General Zev'kall is massing a sizeable force to the east. He intends to breach the wall and invade Hallowfall. There isn't much time.\n\nWe do not have the strength for an all-out assault. To that end, the Weaver has sent Gazlowe here to assist us. I'm willing to do what it takes to save my people.\n\nAnd as fate would have it, I have a personal matter to attend to while we are there.", objectives = "Help Faerin prepare while she explains her plan.", progress = "I'm learning not all nerubians are bad or the same. I just hope the three of us are enough.", completion = "I think the three of us will be enough for this. Lean and mean, right?" }
WordHunterWoW_QuestEN[81930] = { title = "The War Within", description = "People are experiencing visions of a \"Radiant Song\" all across Azeroth. We have reason to believe it's a warning of some kind.\n\nMeet me in Silithus. Perhaps Azeroth's Speaker can shed some light on what this warning might mean.", objectives = "Go to Silithus to talk with Jaina about the visions spreading across Azeroth.", progress = "These visions grow stronger by the day.", completion = "We're all here. Good. Let's find out what the Radiant Song is trying to tell us." }
WordHunterWoW_QuestEN[81945] = { title = "To Arathi's End", description = "We will regroup on the outskirts of Arathi's End to the east.\n\nTheir forces are nearly ready and there isn't much time, {name}.", objectives = "Regroup with Faerin and Gazlowe at Arathi's End.", completion = "You made it. Now let's see if we can make a dent in these nerubians and save Hallowfall.\n\nI can already taste the rewards!" }
WordHunterWoW_QuestEN[81950] = { title = "BOOM Treats!", description = "If we're gonna stop this invasion, we need to take out their big guns. In this case, big guns equals ballistae.\n\nRemember how I had ya pick up them Betelsnax? Yeah, I didn't do that for no good reason. See, the nerubians here have their beetles haul their bombs. And those haulers love them some snacks. I mean, who doesn't?\n\nYou place the snacks next to a ballista, then a bomb beetle walks up, and BOOM!", objectives = "Place Betelsnax to lure bomb-laden beetles into destroying Nerubian Ballistae.", progress = "Those ballista ain't gonna destroy themselves, ya know?!", completion = "Couldn't have done it better myself. Well, maybe. Actually, probably.\n\nBut still, we got the job done and at the low-low price of an over-inflated bag of processed junk that who knows what's in it?" }
WordHunterWoW_QuestEN[81959] = { title = "Collecting a Concoction", description = "The Pale Weavelashers did indeed throw my alchemical supply down the cliffside. The potions will give the citizens of the Silken Ward the edge they need to rise up.\n\nI need someone to go down the Whispering Cliffs and collect any bottles that haven't broken open. I would go myself but the kobyss have made the area a hunting ground and I'm no fighter.\n\nThis would be a simple task for one such as yourself, eh?", objectives = "Collect 8 Brightshade Potions in the Whispering Cliffs.", progress = "The kobyss are beyond a nuisance. I need to get my Brightshade Potions back.", completion = "I hope you got my Brightshade Potions, eh? Without them I've got nothing left." }
WordHunterWoW_QuestEN[81962] = { title = "A Nudge in the Right Direction", description = "Wonderful, wonderful! Now that we have recovered my Brightshade Potions, I want you to go around the Silken Ward and show them off!\n\nThis will draw the ire of the Pale Weavelashers, I'm sure, but I want to show the populace that we don't need to live under their thumb. With a little aggressive motivation we can strike out on our own.\n\nYes, yes, this will do! Go around the Silken Ward and kill Pale Weavelashers. My potions will provide an extra kick the citizens will certainly love.", objectives = "Kill 10 Pale Weavelashers around the Silken Ward.", progress = "Be wary of any side effects the potions might have so I can document them.", completion = "The potions work wonders, don't they?" }
WordHunterWoW_QuestEN[81963] = { title = "The Fruits of Our Labor", description = "You put on quite the show, yes? The orders are already coming in. The citizens can't wait to get their mandibles on the potions.\n\nI have one final task for you. I want you to take these latest orders and deliver them. You will accept, yes? \n\nThe citizens are stirring. Now is the time to show the Pale Weavelashers what we can do. If any try and stop you, you know what to do.", objectives = "Deliver 3 Brightshade Potions to Silken Ward citizens.", progress = "The time is now, friend. The Pale Weavelashers aren't unstoppable.", completion = "Well done, friend. The citizens have all they need to overcome the Pale Weavelashers." }
WordHunterWoW_QuestEN[81964] = { title = "The Blacksmith's Fate", description = "While we're here, I must find out what happened to my old friend, Ryton Blackholme. He was Hallowfall's finest blacksmith--and he was taken in a surprise nerubian attack. I could not save him.\n\nI searched for him, but found nothing except for his bloodied helm. I'd given up hope. But recently, I heard rumor about a blacksmith from a survivor who'd been pulled down off the Aegis Wall.\n\nCould it be Ryton? Will you help me, {name}?", objectives = "Assist Faerin Lothar to uncover the fate of Ryton Blackholme.", progress = "Thank you for your help with this, <name>.", completion = "I can't believe Ryton is really gone, but it means the world to finally know what happened to my dear friend.\n\nWe will honor him as soon as we've dealt with Zev'kall's monstrosity." }
WordHunterWoW_QuestEN[81965] = { title = "Invasion Disruption", description = "While we cannot eliminate the nerubian threat here, we can disrupt their invasion plans.\n\nThere are any number of opportunities to accomplish our goal. Let's see what kind of damage we can do.", objectives = "Disrupt the nerubian invasion efforts at Arathi's End.", progress = "The more we can accomplish here, the safer we make things for Hallowfall.", completion = "That's enough for now. We'll need to periodically return to weaken their forces until there's another solution." }
WordHunterWoW_QuestEN[81966] = { title = "Slept Like a Rock", description = "Champion, Da's awake. Please return to Dalaran.", objectives = "Return to Dalaran.", completion = "Welcome back Champion." }
WordHunterWoW_QuestEN[81969] = { title = "An End to the End", description = "I want to honor my friend. But first, we need to deal the killing blow to this Light-forsaken place.\n\nIt's known that General Zev'kall has been overseeing the creation of a monstrosity... a void-corrupted, malformed nerubian. The scouting report pinpointed the location at the top of the canyon.\n\nWe're going to deprive him of his horrific pet. That should put an end to his plans to invade Hallowfall. At least for a little while longer.", objectives = "Work with Faerin and Gazlowe to take down the monstrosity known as Surek'tak the Sundered.", completion = "Thank you, <name>. The people of Hallowfall are in your debt.\n\nI have one last thing to ask if you're willing." }
WordHunterWoW_QuestEN[81976] = { title = "Bazaar, Isn't It?", description = "", objectives = "Got any Bronze? Come spend it at the bazaar!\n\nThis will get you there. First one's free!" }
WordHunterWoW_QuestEN[81981] = { title = "What Army?", description = "", objectives = "" }
WordHunterWoW_QuestEN[81984] = { title = "Push Back the Dark", description = "Now that you're done with the level up campaign, you can help test the max level faction feature for Hallowfall, Push Back the Dark!\n\nOnce you accept my gossip, you will be teleported to a farm in desperate need of help. It is falling to the darkness, and could use your help putting this to rights again. Relight the keyflames and help the farmers... if you dare!\n\n(Accepting the gossip will level you to 80 and teleport you.)", objectives = "Talk to Captain Placeholder and accept his challenge." }
WordHunterWoW_QuestEN[81985] = { title = "Worldsoul Memory: The Worldcarvers", description = "", objectives = "" }
WordHunterWoW_QuestEN[81990] = { title = "The Light's Call", description = "Attention, residents of Hallowfall!\n\nUrgent assistance is needed to reclaim the shadowed outskirts.\n\nAs darkness grips countless family farms, your aid is needed to ignite the sacred flame and restore safety to our lands.", objectives = "Report to Keyrra Flamestonge for further service.", completion = "We are glad to have your support. Anything you can do to help re-ignite these keyflames will help!" }
WordHunterWoW_QuestEN[81993] = { title = "The Stormrider's Bond", description = "This beauty is no ordinary gryphon. It's got the storm within it. I've been trying all day tae calm it down.\n\nIt reminds me of an ol' Wildhammer myth. Stormrooks, they were called. Only able to be bonded by gryphon riders of great renown.\n\nIf we can show ye got the spirit of the storm, maybe it'll open up tae ye. Try proving yerself in battle.", objectives = "Collect 50 Storm Spirits by slaying powerful creatures of the Dragon Isles.", progress = "I've never met such a stubborn gryphon before!", completion = "Look at that! I think it likes ye.\n\nHere, I found some gear in the stormrook's saddle. Looks perfect fer ye! And ye certainly deserve to wear something befitting a noble gryphon rider such as yerself." }
WordHunterWoW_QuestEN[81994] = { title = "A Sacred Connection", description = "Aye, the stormrook is beginning to take a liking to us. But the bond between rider and gryphon is forged over many trials.\n\nYe may have the spirit of the storm, but let's show how ye mastered it. Time to really prove yer mettle in battle.", objectives = "Collect 500 Storm Spirits by slaying powerful creatures of the Dragon Isles.", progress = "I think I'm starting tae get this one to trust me.", completion = "Well, would you look at that! Ye truly have learned to master the storm within ye. A splendid gryphon rider if I ever did see one.\n\nAnd that's not all. I see the armor I gave ye is bristling with the heart of the storm now! Interesting..." }
WordHunterWoW_QuestEN[81999] = { title = "New Home, New Candle!", description = "Janky hears there are giant fire bees on surface.\n\nFire bees make fire beeswax, yes? What if make candle from fire bee wax? What that be like?\n\nJanky must know!", objectives = "Meet Janky in the Cinderwold.", progress = "What wait for?", completion = "Now just need way get wax without die..." }
WordHunterWoW_QuestEN[82006] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[82007] = { title = "Tale of Tails", description = "The newborn lynx have wandered off again!\n\nThose rascally cats are always up to mischief, darting off without a care. With Peevish missing and only Vesper and I to hold this position, your assistance would be a boon!\n\nI reckon those pesky felines are somewhere nearby. See if you can bring them back.\n\nI would use a light and search the cave, the spider-infested area to the south, and the coast to the north.", objectives = "Locate Beans, Beef, Thunder, and Cap'n Elaena. Then return them to Attica Whiskervale.", progress = "Have you found all the cats?", completion = "If these cat could talk they'd have quite the story to tell!\n\nIt looks as if one has taken a liking to you. I think you might have a new friend." }
WordHunterWoW_QuestEN[82041] = { title = "Beledar's Blessing", description = "", objectives = "" }
WordHunterWoW_QuestEN[82042] = { title = "The Better Part of Valorstones", description = "Dornogal! A fascinating new place to everyone--not just the dracthyr!\n\nAnd fascinating new places have fascinating new reagents to find and study. Like Valorstones!\n\nI've seen similar objects all over Azeroth used to upgrade weapons and armor. I hypothesize these will work the same way.\n\nHelp my research by bringing me any Valorstones you collect. I'll upgrade a piece of your gear in return!", objectives = "Collect 50 Valorstones while adventuring in Khaz Algar, then return to Cuzolth and upgrade a piece of Season 1 equipment.", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! You are truly a supportive breeze in flight. Please take these tokens of thanks." }
WordHunterWoW_QuestEN[82050] = { title = "The Harbinger of Crests", description = "Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here.\n\nValorstones can only go so far, as I'm sure you know. You need these... Harbinger Crests to upgrade powerful adventuring gear. Much like Valorstones, these Crests are rewarded through many different activities. Harbinger Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Weathered Harbinger Crests, and we can help you upgrade some gear further.", objectives = "Acquire 15 Weathered Harbinger Crests by defeating unique creatures, conquering raids, completing world activities, or by looting caches. Then return to Vaskarn in Dornogal.", progress = "If you're having a hard time finding Weathered Harbinger Crests, you can search for hidden treasures around Khaz Algar or those underground areas I've heard about. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power! And to advance my research, of course. But yes, your power growth!" }
WordHunterWoW_QuestEN[82059] = { title = "Transmutation Station", description = "My friend, these Crests are magnificent. It seems they can be transformed into different levels of Crest!\n\nIf you find yourself with a multitude of a lower-strength crest, you can upgrade it for a more powerful one! I think. I'm still working on that. I'll let you know when I figure it out. But we can transmute to weaker Crests right now!\n\nSee for yourself. Here's a few Carved Harbinger Crests. Speak to me and I can transform them into Weathered Harbinger Crests, all without excess energy or entropy!", objectives = "Bring 15 Carved Harbinger Crests to Vaskarn in Dornogal, then trade them for a Pouch of Weathered Harbinger Crests.", progress = "If you lose those Carved Harbinger Crests, you can find more from powerful creatures around Khaz Algar. I've heard there's quite a variety of them!", completion = "See? Isn't it remarkable?\n\nI will let you know soon as I figure out how to turn Weathered Harbinger Crests into Carved Harbinger Crests. If my experience with other Crests is any guide, it will takes more of the Weathered Harbinger Crests to go that direction. But weakening Crests? That's easy!" }
WordHunterWoW_QuestEN[82080] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you are timed and have a LOT more braziers to hit.\n\nReady?", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!" }
WordHunterWoW_QuestEN[82087] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nStand near the bonfire and you'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers, then come back here... for your next lesson.", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up..." }
WordHunterWoW_QuestEN[82088] = { title = "Kobyss Kibosh", description = "", objectives = "" }
WordHunterWoW_QuestEN[82105] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nAs you approach the bonfire you'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers then come back here... for your next lesson.", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up..." }
WordHunterWoW_QuestEN[82109] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!" }
WordHunterWoW_QuestEN[82120] = { title = "Pool Cleaner", description = "", objectives = "" }
WordHunterWoW_QuestEN[82121] = { title = "Demand Satisfaction", description = "We have worked together for some time now, {name}. I hope you have come to respect my vision as it pertains to the art of warfare. There are, as ever, rules that must be followed. Lines that must not be crossed.\n\nZev'kall has to die, and I have to be the one to do it. Every day that Ascended ruffian tramples upon the ideals of war tarnishes the legacy of our kingdom.\n\nPlease, do this last thing for me. Travel to the enemy stronghold and plant this flag on its steps. We will do this the correct way.", objectives = "Plant Anub'azal's Standard inside the Siegehold in Azj-Kahet.", progress = "Make haste. I would see this tale end sooner rather than later.", completion = "Even Zev'kall would not dare to dismiss a formal challenge.\n\nGood." }
WordHunterWoW_QuestEN[82122] = { title = "Duel of the Fates", description = "I am no hapless rube, {name}. I do not expect Zev'kall to honor the nature of this challenge in even the most nominal sense.\n\nWe are in the enemy's fortress, and we are surrounded by his teeming sycophants. There will be interference.\n\nI have two orders for you, soldier. First, you will ward off any malcontents who wish to interrupt the duel. Second and more importantly, you will bring neither sword nor spell to bear against Zev'kall himself.\n\nHe will fall by my claws.", objectives = "Defend Anub'azal from Zev'kall's minions.", completion = "It is done." }
WordHunterWoW_QuestEN[82123] = { title = "The General's Conviction", description = "<Anub'azal retches roughly. Ichor spews from his disjointed maw.>\n\nMy cohort's obligation to the Severed Threads yet remains. You would do well to report what happened here to the Weaver. Vexing as she is, she will have some idea of how to proceed from here.", objectives = "Inform Widow Arak'nai of what transpired.", completion = "So, that is what happened.\n\nDamnable fool. What was he thinking? Still... Zev'kall's death is a mighty blow to the loyalist forces. Chitin-headed as he is, I cannot question Anub'azal's strength.\n\nHis scions will take up his work for the Threads, and he will be remembered as a fine general." }
WordHunterWoW_QuestEN[82124] = { title = "The Beginning of the End", description = "Queen Ansurek has been busy since the assassination attempt. Her grip is tightening on Azj-Kahet and her ever loyal nobles attend to her darkest whims. \n\nOn behest of the Queen, her two most loyal nobles Skeinspinner Takazj and Anub'arash, have locked down the Umbral Bazaar. \n\nTakazj's insufferable propaganda machinations and Anub'arash's increased military presence have painted a clear picture, ascend or die.\n\nI need you to go to the Umbral Bazaar and disrupt their hold.", objectives = "Cause disruption in the Umbral Bazaar.", progress = "How disappointing that Queen Ansurek continues to lead us to darkness.", completion = "The Queen's grip loosens and Skeinspinner Takazj and Anub'arash look worse in her eyes. Two flies, one thread." }
WordHunterWoW_QuestEN[82125] = { title = "A Spy Like Us", description = "Distressing news comes from the Burrows, a sinister plan is unfolding in the gutters below. Citizens of the ward have been disappearing at an alarming rate. \n\nSkeinspinner Takazj and Anub'arash have all the subtlety of a hammer. I doubt it is their work. This is the hand of someone more subtle.\n\nI have a contact in the Burrows. His name is Gut'usul. Meet with him in the Burrows and find out what is going on down below.", objectives = "Meet with Gut'usul in the Burrows.", completion = "It's about time someone showed up to help. You are the one the Vizier sent, yes?" }
WordHunterWoW_QuestEN[82126] = { title = "Defense of the People", description = "The Vizier no doubt filled you in on some of the details. Citizens in the Burrows are missing, that much you know. \n\nBut whispers on the wind tell a bigger story. Our citizens are being taken to the Transformatory and never returned!\n\nWe must stop this at all costs. More have been taken but it's not too late for them yet. They are still being kept in the Burrows. Find them and free them.", objectives = "Free 5 citizens in the Burrows.", progress = "Act swiftly, we may not have long before they are beyond our grasp.", completion = "The citizens of the Burrows are in your debt. Good work." }
WordHunterWoW_QuestEN[82127] = { title = "Make Them Prey", description = "These abductors are rounding up citizens and no one in the Burrows can stop them. I think it is about time somebody did something. \n\nThey stalk the Burrows thinking they are unseen but I can see them, we can all see them. It's just nobody here can oppose them. That is where you come in.\n\nHunt these abductors down and show them who is really the prey.", objectives = "Kill 8 Abductors in the Burrows.", progress = "Hit the abductors extra hard for me.", completion = "I hope they squirmed in their last moments. I have no sympathy for those that turn on their own." }
WordHunterWoW_QuestEN[82130] = { title = "A Shot at the Top", description = "While you have been out, I've been keeping busy as well. \n\nYour exploits in the Burrows drew the attention of someone much higher up. A strange being wrapped in bandages, with a scent like despair.\n\nFortunately, this unusual monster is paying a visit all the way down in the Burrows to find out why their abductors are missing. Now is our chance to strike, and take down this whole operation.", objectives = "Kill the Master Abductor.", progress = "Soon the Burrows will be free.", completion = "The word of your exploits has reached all the way up here. A sign of a good job." }
WordHunterWoW_QuestEN[82133] = { title = "Documenting: Field Manual Edition", description = "", objectives = "" }
WordHunterWoW_QuestEN[82141] = { title = "To Kill a Queen", description = "Tightening her grip on the citizens is something I expected of the Queen but forcefully ascending the population of the Burrows is too far. \n\nQueen Ansurek has fallen far greater than I ever expected. I can't sit idly by and watch her lead our people to ruin.\n\nThe time is now. We must kill Queen Ansurek and lead the people to a brighter future. Otherwise who knows how far she will fall.", objectives = "Kill Queen Ansurek.", progress = "It fills me with sorrow that it has come to this.", completion = "I take no pleasure in regicide but it had to be done." }
WordHunterWoW_QuestEN[82143] = { title = "The Path of Dissonance", description = "Hannan is correct only in that my presence here is not... strictly allowed.\n\nBut this corruption echoes in my mind, like a disruptive chord in the otherwise pure song of the world. Like a cry for help.\n\nI must heed that call. I must follow the dissonance to its source and find the heart of it, so that I may discover how to cleanse it.\n\nJoin me.", objectives = "Meet Orweyna and Hannan outside the Salien Gutters cave.", progress = "You have proven to be formidable. I am sure we can find a way to eliminate what extractors we come across.", completion = "<Orweyna gives a concerned glance toward the cave.>\n\nWhen he agreed to come with me... I was supposed to watch over him. Make sure nothing bad happened." }
WordHunterWoW_QuestEN[82144] = { title = "On the Road", description = "This is the only road to the elevator, he should have been here by now. \n\nUnless... he didn't take the road! He wouldn't want to be seen. \n\nHe has no idea how dangerous the deeps can be. We have to find him!", objectives = "Find Brennok.", completion = "If he'd only told me sooner... stone-headed oaf. But if he's set on leaving, he'll need a guide. Not sure he knows how to put one foot in front of the other on his own.\n\nHis chronicle is already on a rook headed to Gundargaz. They'll take care of his stories. At least until he's had his fill of his own.\n\nMy oath is, and always was, to care for him. I can't do that if I keep him down here.\n\nThank you for helping him." }
WordHunterWoW_QuestEN[82145] = { title = "The Lost Mosswool", description = "", objectives = "" }
WordHunterWoW_QuestEN[82146] = { title = "Special Assignment: Cinderbee Surge", description = "", objectives = "" }
WordHunterWoW_QuestEN[82153] = { title = "Embassies and Envoys", description = "We sailed for what seemed like an eternity. I must admit there were times when I worried we would arrive too late.\n\nBut seeing all of you, united and strong, has rekindled my hope.\n\nBefore we begin planning, we must set up a base of operations here in Dornogal.", objectives = "Set up your faction's embassy in Dornogal.", completion = "Ye mean tae tell me ye have been an interior decorator this whole time an ye have been holdin' out on me?\n\nWell done, <name>.\n\nYe are rearrangin' me chambers when we get home, ye are." }
WordHunterWoW_QuestEN[82154] = { title = "Special Assignment: Titanic Resurgence", description = "", objectives = "" }
WordHunterWoW_QuestEN[82155] = { title = "Special Assignment: Shadows Below", description = "", objectives = "" }
