WordHunterWoW_QuestEN[82248] = { title = "Advance to Faerin", description = "I have a little morsel all wrapped up from a corner of my web. Shall I share it with you? It's sure to mean your doom, little {race}.\n\nVery well... I can smell your eager impatience. I've sent that little green blob of a goblin you call Gazlowe off to the northeast. He tells me the queen and high general are marshalling their elite shock troops. No doubt they are readying to invade Hallowfall.\n\nScurry off to your Lamplighter friend. I'm certain she will want to smash everything in sight.", objectives = "Speak with Faerin Lothar at Faerin's Advance.", completion = "The Weaver sent you directly? Somehow I'm now even more concerned." }
WordHunterWoW_QuestEN[82254] = { title = "Aquacalypse", description = "", objectives = "" }
WordHunterWoW_QuestEN[82256] = { title = "Capturing the Cataract's Creatures", description = "", objectives = "" }
