WordHunterWoW_QuestEN[82266] = { title = "Tower Washing Simulator", description = "", objectives = "" }
WordHunterWoW_QuestEN[82268] = { title = "The Sorrowful Journey Home", description = "I intend to burn Ryton's breastplate and Sir Ashrealm's tinderbox at Mereldar. I would be honored if you would join me.\n\nWould you carry the breastplate there?", objectives = "Do Faerin the honor of delivering Ryton Blackholme's Breastplate to Mereldar in Hallowfall.", progress = "Thank you for that, <name>.", completion = "You have done the Arathi a great service this day. Please stay and help us pay our respects to Ryton and Sir Ashrealm." }
WordHunterWoW_QuestEN[82284] = { title = "Remembrance for the Fallen", description = "It is our custom to pay homage to the fallen by burning whatever we can recover of their belongings. Usually, it is their tinderboxes as those are easier to carry. We then return those items to the flame.\n\nWhile we were able to retrieve Sir Ashrealm's tinderbox, Ryton's breastplate will serve to honor his memory.\n\nYou have placed your life in danger not only for me, but also for Hallowfall. I would be honored if you would assist me this one last time in remembering our fallen.", objectives = "Place the Breastplate and Tinderbox in the forge at Mereldar.", progress = "Thank you, <name>.", completion = "It is done. It feels both odd and somehow comforting to finally know my dear friend's fate with certainty.\n\nThank you for everything, <name>." }
