WordHunterWoW_QuestEN[82296] = { title = "The Power of Creation", description = "", objectives = "Ah, the Catalyst. It's a marvel that even words struggle to capture. \n\nPicture this, young one. Long before our city's foundations were laid, Titans roamed this land. Masters of the innovation, they forged wonders beyond imagination. And amidst their great works, they crafted the Catalyst.\n\nAnd now its very power belongs to you." }
