WordHunterWoW_QuestEN[82371] = { title = "A Flickering Candle", description = "", objectives = "So helpful! Kobolds thank you. Earthen thank you. The Assembly thanks you! \n\nCandle for you! No better reward than that!\n\nYes, this candle made from my own earwax. You? Special. And \"you're welcome.\" Maybe next time, I can have some of your earwax? No pressure. Think about it! I'll wait." }
