WordHunterWoW_QuestEN[82452] = { title = "Worldsoul: World Quests", description = "There so much to be done and so little time to do it!\n\nBrinthe and I have been gathering word of the people that need the most aid throughout all of Khaz Algar. There's too many to count!\n\nGo out and help them. With your aid, will can bring all our people closer together... so we may all grow stronger.", objectives = "Complete World Quests in Khaz Algar.", progress = "Strange, these notes that come from Azj-kahet. I am.. hesitant to send any aid to the nerubians. Not after what they've done to my people.\n\nBut between your reports and those from our scouts... perhaps we can use their... disagreements to our advantage. And perhaps some are truly in need of aid. Of kindness. \n\nI do not want my eyes to be clouded by hate. And yet... \n\n<Faerin sighs.> \n\nWho knows. All I do know I won't regret a kindness.", completion = "Ah! I've had so many scouts and letters already! You've done so well. I hope you know you are appreciated." }
WordHunterWoW_QuestEN[82453] = { title = "Worldsoul: Encore!", description = "Have you seen the fliers around? They're staging some earthen plays in the Proscenium!\n\nI can't remember the last time I've seen a play, but I've got my hands full, as usual. You'll go, right?\n\nI'm sure everyone here could use their spirits raised. A play might be just the thing everyone needs. Make sure it's a night to remember!", objectives = "Participate in the Theater Troupe event and complete World Quests in Khaz Algar", progress = "Once, when I was a kid, I decided to put a play on for my family!\n\n<Faerin grimaces.> \n\nIt didn't... it didn't go well.", completion = "Did you see the play? Was it good? Tell me everything." }
WordHunterWoW_QuestEN[82454] = { title = "Firebath Tuning", description = "", objectives = "" }
WordHunterWoW_QuestEN[82455] = { title = "No More Bread", description = "", objectives = "" }
WordHunterWoW_QuestEN[82456] = { title = "Chew On This", description = "", objectives = "" }
WordHunterWoW_QuestEN[82465] = { title = "Precious Gems", description = "So, all they gave us was a location and a garbled riddle...\n\nBut I guess we know where to start.\n\nI can picture it now. Once I have Basalteous's knowledge, I will have nobles and merchants lining up outside my house. No, my mansion! \n\nThe earthen did say southwest, right? I will find the cave and meet you there. Quickly now!", objectives = "Meet Natalia by Basalteous's cave.", completion = "Look at the walls of this cave. Look at all these gems! I can't believe it. The story must be real! \n\nI am going to be so, so rich. And influential. And powerful.\n\nI need to sit down for a moment and catch my breath." }
WordHunterWoW_QuestEN[82466] = { title = "What We Do For Gems", description = "According to the earthen, we have to lure the spirit. Or disturb it. Or something.\n\nThe four standing stones they mentioned have depleted elemental cores laying around them. There are igneous elementals outside and on the beach to the north. Are you thinking what I'm thinking? \n\nCould you get me elemental cores? Maybe just a few? We're so close, so we might as well try...", objectives = "Collect 4 elemental cores from the Igneous Sand elementals.", progress = "Do you have the cores?", completion = "Four cores for four standing stones. \n\nI am ready when you are." }
WordHunterWoW_QuestEN[82467] = { title = "Gems Are Forever", description = "I am so close, I can feel it in my bones.\n\nPlace the cores next to each standing stone. It is time to summon Basalteous.", objectives = "Lure out Basalteous by placing a core by each standing stone.", progress = "This is it. I can feel it.", completion = "That was almost effortless! For me, at least. \n\nCan you imagine what I can do with this knowledge? Can you imagine my name spoken in Stormwind? Gilneas? Maybe even Orgrimmar! \n\nI will be able to do and achieve everything I wanted. Everyone will finally look up to me. I will have all the gold for all I can find and create!" }
WordHunterWoW_QuestEN[82468] = { title = "Let Them Win", description = "", objectives = "" }
WordHunterWoW_QuestEN[82470] = { title = "Arcane Riddles", description = "", objectives = "" }
WordHunterWoW_QuestEN[82477] = { title = "A Helping Farmhand", description = "Greetings, {name}, name's Orren. We've got a whole mess of Jawcrawlers that came up from underground attacking the crops. Something a {class} like yourself could really help out with!\n\nHunger is never far away in Hallowfall, so saving these crops is my priority.\n\nBut if you'd be willing to drive them off for me, I'll be able to focus on my long-term plan to feed people more effectively.\n\nMeet me over by the shed! And bring any food that's not too chewed up.", objectives = "Recover 8 Slightly Chewed Harvest Bounty from Gluttonous Jawcrawlers.", progress = "This'll keep our crops safe in the future. And perhaps the leftovers can go... in a stew.", completion = "Good work, <name>, that looks... edible. And when you're on the wall, worried about nerubians killing you, I doubt anyone will mind. \n\nI was able to get a lot of ELIZA's decision sprockets properly aligned while you were doing that, so thanks!" }
WordHunterWoW_QuestEN[82478] = { title = "Regularly Scheduled Maintenance", description = "I've got another problem that's a bit more... personal, {name}.\n\nMy girlfriend, Aemyra, is a Lamplighter. I thought she'd be back from her last mission, to Velhan's Claim, by now.\n\nCould you go make sure she's okay, and deliver this message? I'm worried to the point of distraction.\n\nMaybe you could also pick some of her favorite flowers, up that hill? \n\nI'd go myself, but if I can get ELIZA working right, it would do so much to feed people in Hallowfall. And give me more time to spend with Aemyra, too!", objectives = "Take Orren's Message, 6 Crimson Charmer and 6 Amber Bloom to Aemyra at Velhan's Claim.", progress = "These are from Orren? I think they go well together, even though they're so different.", completion = "Wow, that's really sweet of him. I'll be here for a while, dealing with the kobyss, but I should send something back. \n\nSo he knows I'm safe, and that I can't wait to see him." }
WordHunterWoW_QuestEN[82479] = { title = "The Sword is Mightier", description = "I had told Orren I'd be back by now, but Velhan's Claim has larger problems than I expected. The people here need my help against the kobyss.\n\n{name}, I've always been better with a sword than a pen. Strong feelings and being far apart makes it even harder. \n\nI'm more at home protecting the vulnerable than being vulnerable. \n\nPerhaps I could tell you what I want to get across and you could write it for me?", objectives = "Help Aemyra choose the right words for her message to Orren.", progress = "Did you find Aemyra? Is she alright?", completion = "I'm really glad to hear she's okay! But I have a huge problem now." }
WordHunterWoW_QuestEN[82480] = { title = "Job Killing Robot Or...", description = "I shouldn't have set ELIZA to simply gather as much food as she could. She was working, but when a wagon came by, full of food for Mereldar, she started chasing it! And she wouldn't let me access her decision sprockets or tensor springs!\n\nI kept trying, but ELIZA wouldn't stop. Eventually, she outran me. {name}, I need you to stop her before someone gets killed.", objectives = "Stop ELIZA.", progress = "Were you able to stop ELIZA?", completion = "ELIZA didn't work like I expected. But Aemyra believes I'll get it right... I'm going to keep trying. \n\nAnd when I do, lack of food won't be a threat to the Arathi--and lack of time won't keep me from Aemyra!" }
WordHunterWoW_QuestEN[82481] = { title = "Enforcer Extermination", description = "", objectives = "" }
WordHunterWoW_QuestEN[82482] = { title = "Worldsoul: Snuffling", description = "I've wanted to be able to explore beyond Hallowfall's caves for so long now. Of course, I hardly have time, but when I do... there's such surprises everywhere!\n\nTreasures, friends in need, foes great and small... All so wonderful. \n\nI'll just have to live vicariously through you. Deeds need doing! Go out and seek the surprises in every nook and cranny. I'm certain you will find things that need doing!", objectives = "Find Disturbed Earth piles to Snuffle and discover Worldsoul Motes by skyriding all around Khaz Algar.", progress = "Oh, what have you found?! Tell me everything.", completion = "Our world is a wonderful place. Thank you for protecting it." }
WordHunterWoW_QuestEN[82483] = { title = "Worldsoul: Spreading the Light", description = "Darkness continues to spread through Hallowfall. We need your help to keep the fires burning!\n\nThe shadows are deep and dark. My people are strong, but we always need more hope. More sparks for the flame. You are the brightest spark of all.", objectives = "Complete Spreading the Light objectives and slay Rare creatures in Khaz Algar.", completion = "<Faerin breathes deeply.> \n\nEven from here... I can almost feel it. Beledar's strength returning. You've helped push back the darkness. \n\nThank you." }
WordHunterWoW_QuestEN[82485] = { title = "Worldsoul: Cinderbrew Meadery", description = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim.\n\nI can't help but imagine it's how Beledar would taste...\n\nThe earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands.\n\nBut... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", objectives = "Complete the Cinderbrew Meadery dungeon on Normal difficulty or higher.", completion = "Did you get stung by any bees? Did you feel the burn? Maybe you're allergic.\n\n<Faerin chuckles.>\n\nWhat? That wasn't a funny enough joke? Then you do better!" }
WordHunterWoW_QuestEN[82486] = { title = "Worldsoul: The Rookery", description = "The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities!\n\nIt must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. \n\nLook into it, {name}.", objectives = "Complete the Rookery dungeon on Normal difficulty or higher.The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities!\n\nIt must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. \n\nLook into it, <name>.You will learn:" }
WordHunterWoW_QuestEN[82487] = { title = "Worldsoul: The Stonevault", description = "Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. \n\nI can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. \n\nEirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!", objectives = "Complete the Stonevault dungeon on Normal difficulty or higher.", progress = "To corrupt your own people... I can't imagine how the old High Speaker could bear to do that.", completion = "Brinthe and I have heard word of your success! \n\nAs the new High Speaker, I'm sure Brinthe will lead her people with more grace than Eirich." }
WordHunterWoW_QuestEN[82488] = { title = "Worldsoul: Darkflame Cleft", description = "Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them!\n\nTheir little candles... keeping their little flames lit...\n\n<Faerin clasps her hand to her chest with a grin.> \n\nSo brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. \n\nReports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!", objectives = "Complete the Darkflame Cleft dungeon on Normal difficulty or higher.Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them!\n\nTheir little candles... keeping their little flames lit...\n\n<Faerin clasps her hand to her chest with a grin.> \n\nSo brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. \n\nReports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!You will learn:" }
WordHunterWoW_QuestEN[82489] = { title = "Worldsoul: The Dawnbreaker", description = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. \n\nIt is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", objectives = "Complete The Dawnbreaker dungeon on Normal difficulty or higher.", completion = "Our ships are proof of the creativity and ingenuity of the Hallowfall Arathi.\n\nDespite all odds, we still strive to creative beauty. That's what I love most about my people." }
WordHunterWoW_QuestEN[82490] = { title = "Worldsoul: Priory of the Sacred Flame", description = "My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some--\n\n<Faerin pauses, momentarily lost for words.>\n\nThere are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. \n\nBut things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people!\n\nThis isn't what the Light is about, {name}. Stop them.", objectives = "Complete the Priory of the Sacred Flame dungeon at Normal difficulty or higher.My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some--\n\n<Faerin pauses, momentarily lost for words.>\n\nThere are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. \n\nBut things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people!\n\nThis isn't what the Light is about, <name>. Stop them.You will learn:" }
WordHunterWoW_QuestEN[82491] = { title = "Worldsoul: Ara-Kara, City of Echoes", description = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. \n\nThere's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. \n\nWe need to find out what's going on. Bring together your strongest companions and investigate!", objectives = "Complete the Ara-Kara, City of Echoes dungeon on Normal difficulty or higher.", completion = "You're back! I was worried. Tell me everything.\n\n<Faerin looks you over.> \n\nThose spiders didn't... do anything to you, did they? Didn't... plant eggs under your cloak or something? \n\n<Faerin shivers.>" }
WordHunterWoW_QuestEN[82492] = { title = "Worldsoul: City of Threads", description = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. \n\nWe must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!", objectives = "Complete the City of Threads dungeon on Normal difficulty or higher.", completion = "All those spiders. All those legs. \n\n<Faerin shivers.> \n\nI hope you fared well. Good work, <name>." }
WordHunterWoW_QuestEN[82493] = { title = "Worldsoul: The Dawnbreaker", description = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. \n\nIt is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", objectives = "Complete The Dawnbreaker dungeon on Heroic difficulty or higher.", progress = "How goes the preparations?", completion = "Our ships are proof of the creativity and ingenuity of the Hallowfall Arathi.\n\nDespite all odds, we still strive to creative beauty. That's what I love most about my people." }
WordHunterWoW_QuestEN[82494] = { title = "Worldsoul: Ara-Kara, City of Echoes", description = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. \n\nThere's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. \n\nWe need to find out what's going on. Bring together your strongest companions and investigate!", objectives = "Complete the Ara-Kara, City of Echoes dungeon on Heroic difficulty or higher.", completion = "You're back! I was worried. Tell me everything.\n\n<Faerin looks you over.> \n\nThose spiders didn't... do anything to you, did they? Didn't... plant eggs under your cloak or something? \n\n<Faerin shivers.>" }
WordHunterWoW_QuestEN[82495] = { title = "Worldsoul: Cinderbrew Meadery", description = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim.\n\nI can't help but imagine it's how Beledar would taste...\n\nThe earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands.\n\nBut... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", objectives = "Complete the Cinderbrew Meadery dungeon on Heroic difficulty or higher.", completion = "Did you get stung by any bees? Did you feel the burn? Maybe you're allergic.\n\n<Faerin chuckles.>\n\nWhat? That wasn't a funny enough joke? Then you do better!" }
WordHunterWoW_QuestEN[82496] = { title = "Worldsoul: City of Threads", description = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. \n\nWe must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!", objectives = "Complete the City of Threads dungeon on Heroic difficulty or higher.", completion = "All those spiders. All those legs. \n\n<Faerin shivers.> \n\nI hope you fared well. Good work, <name>." }
WordHunterWoW_QuestEN[82497] = { title = "Worldsoul: The Stonevault", description = "Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. \n\nI can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. \n\nEirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!", objectives = "Complete the Stonevault dungeon on Heroic difficulty or higher.", progress = "To corrupt your own people... I can't imagine how the old High Speaker could bear to do that.", completion = "Brinthe and I have heard word of your success! \n\nAs the new High Speaker, I'm sure Brinthe will lead her people with more grace than Eirich." }
WordHunterWoW_QuestEN[82498] = { title = "Worldsoul: Darkflame Cleft", description = "Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them!\n\nTheir little candles... keeping their little flames lit...\n\n<Faerin clasps her hand to her chest with a grin.> \n\nSo brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. \n\nReports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!", objectives = "Complete the Darkflame Cleft dungeon on Heroic difficulty or higher.Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them!\n\nTheir little candles... keeping their little flames lit...\n\n<Faerin clasps her hand to her chest with a grin.> \n\nSo brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. \n\nReports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!You will learn:" }
