WordHunterWoW_QuestEN[82509] = { title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", objectives = "Complete the Nerub-ar Palace raid on LFR difficulty or higher.Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!You will learn:" }
WordHunterWoW_QuestEN[82510] = { title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", objectives = "Complete the Nerub-ar Palace raid on Heroic difficulty or higher.Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!You will learn:" }
WordHunterWoW_QuestEN[82511] = { title = "Worldsoul: Awakening Machine", description = "The earthen tell me of this \"Awakening Machine\" that is part of their life cycle.\n\nIt imbues them with energy, once a gift of the titans but now from the Worldsoul.\n\n<Faerin smiles faintly and nods knowingly.>\n\nThey hold it in high reverence--as we do Beledar. \n\nI will fight to defend it with the same fervor as I would defend our own star! \n\nAid me, {name}. We can't let them down.", objectives = "Defeat 20 cumulative waves of enemies in the Awakening Machine.", completion = "Wonderful! I know our earthen allies appreciate your aid." }
WordHunterWoW_QuestEN[82512] = { title = "Worldsoul: World Boss", description = "Hallowfall is not the only land beset by enemies. \n\nGreat monsters wander all of Khaz Algar--savage beasts and intelligent fiends alike. They murder Arathi, earthen, and adventurers in equal measure from innocent farmers to great warriors. \n\nI know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", objectives = "Defeat any World Boss and 5 rare creatures in Khaz Algar.", progress = "I've seen monsters shifting in the distant darkness of Hallowfall. Things that haunt my nightmares.", completion = "How did you fare? Any new scars? Or new tales to tell?" }
WordHunterWoW_QuestEN[82516] = { title = "Worldsoul: Forging a Pact", description = "I've heard some reports of the goings on in Azj-Kahet. Nerubians have killed my people mercilessly since we arrived... it is very difficult to imagine them as allies.\n\nBut... I understand feeling... different from the rest of your people. Perhaps these nerubians who have interest in us are also... different. \n\n<Faerin sighs.> \n\nNo matter the cost... I can't bear to not give them a chance. Are they not also inhabitants of Khaz Algar?\n\nSee what aid you can bring them, my friend.", objectives = "Select a Severed Threads Pact to represent in Azj-Kahet, complete objectives in their name, and slay rares in Khaz Algar.", progress = "I want to believe some nerubians can be different... can be better. But please be careful.", completion = "Well, you look no worse for wear. I'm glad you didn't become spider food. \n\n<Faerin frowns and picks a scrap of web off your shoulder.>" }
