WordHunterWoW_QuestEN[82539] = { title = "Radiant Echoes", description = "<A missive finds its way to you.>\n\n{name}, please come to Dalaran at once. Strange phenomena are appearing all across Azeroth. We believe they may be connected to the Radiant Song. I'd like you to investigate.", objectives = "Meet Khadgar in Dalaran.", completion = "Thank you for answering my summons." }
WordHunterWoW_QuestEN[82540] = { title = "Memories of Adventures Past", description = "It seems that Azeroth has grown... agitated? Something must have happened when Magni tried to commune with her. \n\nPast events have now come to life once more. I believe they're Azeroth's memories.\n\nMemories they may be, these Radiant Echoes are all too real and could cause serious danger if left unattended. I ask that you investigate one of them and help however you can.", objectives = "Go the portrait room in Dalaran and use a glowing portal to join a Radiant Echoes event. Once it begins kill the area boss to complete the event.", progress = "Radiant Echoes and Radiant Visions, all appearing at once. What could Azeroth be trying to tell us? Or perhaps it's just... instinct.", completion = "Excellent work, <name>. Keep assisting with these Radiant Echoes and see if you can find a common thread. They must be connected somehow." }
