WordHunterWoW_QuestEN[82627] = { title = "DNT REUSE ME", description = "Baron Braunpyke and his brother have been working on removing our lingering kobyss problem from near the veneration grounds.\n\nMeet with them there and see what help you can offer.", objectives = "Meet the Braunpyke brothers near the Veneration grounds." }
WordHunterWoW_QuestEN[82628] = { title = "The Brothers Braunpyke", description = "Baron Braunpyke and his brother have been working on removing our lingering kobyss problem from near the Veneration Grounds.\n\nMeet with them there and see what help you can offer.", objectives = "Meet the Braunpyke brothers near the Veneration Grounds.", completion = "I hope you're here to get your hands dirty!" }
WordHunterWoW_QuestEN[82629] = { title = "Nerub-ar Palace: For Nerubian Eyes Only", description = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. \n\nFetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", objectives = "Collect 3 Signets of the Thousand Scars and 3 Signets of the Skeinspiner within Nerub-ar Palace on Normal difficulty.", progress = "Safe passage has its price.", completion = "Do not stray into the shadows, <name>--I cannot guarantee your safety." }
WordHunterWoW_QuestEN[82638] = { title = "Nerub-ar Palace: For Nerubian Eyes Only", description = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. \n\nFetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", objectives = "Collect 3 Signets of the Thousand Scars and 3 Signets of the Skeinspiner within Nerub-ar Palace on Heroic difficulty.", progress = "Safe passage has its price.", completion = "Do not stray into the shadows, <name>--I cannot guarantee your safety." }
WordHunterWoW_QuestEN[82639] = { title = "Nerub-ar Palace: For Nerubian Eyes Only", description = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. \n\nFetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", objectives = "Collect 3 Signets of the Thousand Scars and 3 Signets of the Skeinspiner within Nerub-ar Palace on Mythic difficulty.", progress = "Safe passage has its price.", completion = "Do not stray into the shadows, <name>--I cannot guarantee your safety." }
WordHunterWoW_QuestEN[82650] = { title = "A Pinch of Salt", description = "", objectives = "" }
WordHunterWoW_QuestEN[82651] = { title = "Omens Unified", description = "By the titans! Observe this item, <class>.\n\n<Custodian Khubon shows you something resembling a fractured gem.>\n\nThis is a fractured spark of omens. In the hands of a skilled crafter, a reagent such as this can be infused into other materials to vastly improve the final product.\n\nHowever, this is merely a fragment. If you chance upon another in your adventures, bring it to me. I will combine this one with yours and grant you a complete spark of your own.", objectives = "Find another Fractured Spark of Omens.", progress = "Ah, <name>. What is the progress of your search for another fractured spark of omens?", completion = "Excellent. If you acquire more fractured sparks, you can combine them yourself for use in your own crafting efforts." }
WordHunterWoW_QuestEN[82653] = { title = "Aggregation of Horrors", description = "", objectives = "" }
WordHunterWoW_QuestEN[82658] = { title = "Drop and Go", description = "", objectives = "" }
WordHunterWoW_QuestEN[82659] = { title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", objectives = "Complete the Nerub-ar Palace raid on Normal difficulty or higher." }
WordHunterWoW_QuestEN[82672] = { title = "Another Timely Invitation", description = "The bronze dragonflight is throwing a celebration just outside the Caverns of Time in Tanaris!\n\nThere are all sorts of new activities to partake in that honor and remember what has transpired over the years.\n\nHead to Tanaris and join in the festivities.", objectives = "Visit the celebration in Tanaris outside the Caverns of Time.", completion = "Welcome! \n\nIt's that special time of year when the bronze dragonflight celebrates all that has happened over the years.\n\nYou, <name>, are a most honored guest!" }
WordHunterWoW_QuestEN[82676] = { title = "Broken Masquerade", description = "I cannot remember how I arrived at this swamp, but it was great luck that I did. As I wandered, I spotted Lady Katrana Prestor entering a strange toothy cave. Now, what would a noblewoman be doing in such a ghoulish place?\n\nFollowing her closely, I found a great clutch of black dragon eggs within the lair. Such evidence is clear. Katrana is Lady Onyxia! \n\nI beg of you, aid me in defeating this vile dragon once and for all.", objectives = "Defeat Remembered Onyxia during a Radiant Echoes event.", progress = "If only Varian were here. Surely he'd have no issue slaying her.", completion = "Is it true? She finally rests?\n\nHers was an unwavering ambition. It's good that we stopped her when we did. I cannot imagine the tragedies that would have followed if she was allowed to continue her ploys and schemes." }
WordHunterWoW_QuestEN[82678] = { title = "Archives: The First Disc", description = "I am pleased to report progress has been made restoring the titan Vault of Memory in the Archive. I have the mainframe up and running--but part of its internal mechanism has failed over time.\n\nGetting parts for it will be a challenge, which is why we need your help. Come with me to the Vault of Memory. We can discuss what we need with Dagran.", objectives = "Meet with Dagran in the Vault of Memory and assist him in finding titan disc fragments.\n\nThese disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar.", progress = "Did you happen to find anything?", completion = "These are perfect! The corrosion levels on these parts are minimal. We should be able tae salvage whatever information they hold.\n\nLet's uncover some buried knowledge, <name>!" }
WordHunterWoW_QuestEN[82679] = { title = "Archives: Seeking History", description = "We're still processing the data in the Archive and restoring what we can. But... the discs we've recovered so far in the Archive itself are unusable.\n\nFinding more of these discs are a priority. We must reclaim our memories.\n\nReturn what you find to Dagran. He is assisting me in rebuilding the Archive.", objectives = "Collect 100 titan disc fragments.\n\nThese disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar.", progress = "Have ye found anythin'?", completion = "More o' them! I wonder what we'll discover this time!" }
WordHunterWoW_QuestEN[82680] = { title = "Birdman of the Three Shields", description = "Are you here to watch the mosswools? No? \n\nThat's too bad. I find the elemental creatures on our isle fascinating. I'm not the only one. \n\nAn old friend of mine named Olbarig resides out on the Three Shields. He studies the wild cloudrooks there.\n\nBut come to think of it, I haven't heard from him in awhile. Maybe someone should check on him. Hm. Would you mind?", objectives = "Find Olbarig on the Three Shields.", completion = "Harmot sent you to check on me? \n\nHuh. Well, I didn't know that sack of charcoal cared.\n\nBut he does have an innate sense of when elementals are in turmoil. Maybe he knew something was brewing out here.\n\nHarmot's timing is good, outlander. And your aid would be most welcome." }
WordHunterWoW_QuestEN[82681] = { title = "Cloudrook Down", description = "You see that flock in the distance? Wild cloudrooks. \n\nThey've lived on these islands peacefully for ages. But recent events have stirred other elementals from the earth and sea. One of the cloudrooks was attacked, and it was... disincorporated.\n\nNow the flock circles endlessly. Surely they will tire soon. If they get too tired...\n\nPerhaps if we cleared the hostile elementals from this island, they will return and take their rest.", objectives = "Cull the riled elementals from the central Shield.", progress = "This is the cloudrooks' habitat. Your crash and our war with the nerubians is what caused the other elementals to come.\n\nWe should set this right.", completion = "Many thanks for your help, outlander. Though the cloudrooks do not seem any more inclined to return to land.\n\nIf this is some kind of mourning, I worry it could drive the rooks to exhaustion and their own disincorporation. \n\nWe must try something else." }
WordHunterWoW_QuestEN[82682] = { title = "Elemental Hors D'Oeuvres", description = "The cloudrooks cannot possibly circle forever, and I cannot bear more of them being lost. But maybe they'd roost if we tempted them with their favorite food?\n\nThe eels that swim in these waters carry a small electrical charge not unlike the mosswool favored by their faster, stronger cousins the stormrooks. I once reasoned that cloudrooks might enjoy the eels for similar reasons. \n\nAnd I confess... I've been feeding them the eels ever since. \n\nGather some up and give it a go.", objectives = "Gather 10 Electric Eels.", progress = "The eels may not pack quite the punch of Rambleshire mosswool, but the cloudrooks seem to prefer it that way.", completion = "These should do.\n\nHope you didn't get any nasty shocks gathering them up.\n\nWe can restore some energy to the cloudrooks and show them that it's safe to land." }
WordHunterWoW_QuestEN[82689] = { title = "Only Darkness", description = "Long have I waited for this day, hero. Are you and your allies prepared to bring the Lich King to justice? We charge on your command!", objectives = "Defeat Remembered Lich King during a Radiant Echoes event.", progress = "We battle for the fate of Azeroth. For the light of dawn!", completion = "So, at last it is done.\n\nMay the people of Azeroth remember our deeds here forevermore. May the sacrifices of so many burn in their hearts eternally. May they never fail to risk mortal peril in the face of great evil." }
WordHunterWoW_QuestEN[82690] = { title = "Lingering Shadows", description = "When we faced Xal'atath's forces in Hallowfall, I sensed something dark just beneath the surface. Something that was not her, but it still troubles me.\n\nI have learned that running into every situation myself is not always the best tactic. Sometimes, a leader must stand back to see the field.\n\nSo, I send you.\n\nGo to Hallowfall, and uncover what you can about this mysterious force. I don't want to be caught blind again.", objectives = "Return to where Alleria sensed Black Blood in Hallowfall.", completion = "I didn't expect to see you here.\n\nBut then, you always manage to show up where there's something interesting, don't you? \n\nThere is no time for talk, though. My people have run into problems." }
WordHunterWoW_QuestEN[82691] = { title = "No Breathing Room", description = "We all followed Orweyna to these surface caves because we believed in what we were doing. But this... We did not bargain for so many injuries, so much dogged searching.\n\nFor now, we just need a little breathing room. Slay the creatures out there that are harming us, and we can get the space to address the real issue.", objectives = "Slay Seeping creatures.", progress = "Our people are fierce and strong. We are accustomed to being outnumbered. But this is too much.", completion = "That should give us some space to retreat.\n\nAnd now we must deal with the crux of the issue. That is, Orweyna's ever-lasting determination to pursue this mission, no matter the cost.\n\nIt's time we had a talk." }
WordHunterWoW_QuestEN[82692] = { title = "Price of a Mission", description = "I don't know what prompted you to come here, but we could use your help. \n\nWe came to investigate signs of the Black Blood in this area, but the creatures overwhelmed us. Several of us are still out in the field.\n\nYou are hale and hearty. Go find my people so they can return.\n\nAnd, if you have the strength, take a closer look at the strange flowers that grow from the blood that seeps beneath the ground. They may hold a clue as to how we can fight against its corruption.", objectives = "Find the pinned-down haranir and examine Strange Flowers.", progress = "Have you found my people?", completion = "<Orweyna counts the number of haranir silently-- to reassure herself. Then she nods.>\n\nThat's all of us. And I'm grateful. \n\nThose flowers you found are also odd. They seem to have corrupted properties and have become something new. I have to dig into this more.\n\nWe can't stop now. Not when we're so close. This could be the key to how we fight back." }
WordHunterWoW_QuestEN[82693] = { title = "Standing in the Way", description = "Some of these creatures are stronger than others. When we were able to act together and fresh to the fight, these creatures were no threat. Now our injuries and separation leave us vulnerable. \n\nMy people are resilient, but we are not immortal.\n\nThere is one beast larger than all the others. That beast is making it difficult for the haranir to return and recover.\n\nSlay it, so they can be safe.", objectives = "Defeat the Bloodcrust Behemoth.", progress = "Once we are together again I know we will be able to regroup and continue.", completion = "<Orweyna nods.>\n\nThank you." }
WordHunterWoW_QuestEN[82694] = { title = "Together, Alone", description = "I am not blind. I know that they are tired and weary. But we are so close to figuring out what we can do about the Black Blood.\n\nThe importance of what we uncover goes beyond Hallowfall, or the nerubian kingdom. There is so much more work if we are to find a solution.\n\nFor now, let us withdraw and recover. Somewhere away from these creatures.", objectives = "Meet Hannan in Hallowfall to hear the plan.", completion = "Na'layro. Kai'shae. Ney'leia. On'hiea.\n\nHannan.\n\nWe were a family all on our own, here, far away from home. \n\nI do not blame them for wanting to return, but I would blame myself if I gave up now. I must focus on what comes next." }
WordHunterWoW_QuestEN[82695] = { title = "The Voice", description = "Here is where I must focus. I can hear the voice of my goddess, and she must be near.\n\nI will enter a meditation to ask what I must do. How can I continue this mission alone? How can I go on without the others?\n\nStay close. I don't know what may lurk or threaten while I am concentrating.", objectives = "Defend Orweyna as she meditates.", progress = "<Orweyna is unresponsive as she focuses entirely on her meditation.>", completion = "I understand.\n\nWe must go to where I can hear the sounds of things moving beneath the stones. I don't know what it means, I only know that I must go there.\n\nWill you go with me?" }
WordHunterWoW_QuestEN[82696] = { title = "Ringing in the Deeps", description = "My vision was clear to me. I need to continue this work.\n\nI need to find out how we can stop the Black Blood from spreading, before it's too late for your people, and for mine.\n\nMeet me in the Ringing Deeps. I will be in a form that allows me to hide and to listen without anyone noticing.", objectives = "Meet Orweyna at Camp Murroch in the Ringing Deeps.", completion = "There seem to be goblins everywhere now. \n\nDo not look too closely at me, or you will draw attention. We need to get closer to where the goblins are working." }
WordHunterWoW_QuestEN[82697] = { title = "Good Help These Days", description = "Seeing you here is a welcome surprise!\n\nThere's something big happening over at Opportunity Point, but it's hard to know what without getting closer to the people working there. \n\nI know Haxle's involved. We'll need his paperwork if we want to be able to ask around without trouble. \n\nHe's headed down to Opportunity Point. \n\nGo, follow him, and see if he's got anything on him we can use. Don't worry about the mess-- I know you're discreet when you need to be.\n\nAnd... also not, when you need to be.", objectives = "Find Haxle Drillbit and shake him down for access to the operation.", progress = "Got that work order? We can open up way more doors with it than without it.", completion = "Perfect. Now anytime someone asks why we're here, we've got this. Now it's time to do a little snooping.\n\n... There are a lot more goblins here than I remember. Something's definitely going on." }
